begin;
alter table public.exams disable trigger trg_exams_sync_bank;
do $do$ declare r jsonb; e jsonb; h text; begin
  for r in select * from jsonb_array_elements($j$[{"id":1183580,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":3,"options":["4,8.10<sup>3</sup>N","4,8N","48N","4,8.10<sup>−3</sup>N"],"question":"Một điện tích điểm q = 2 μC được đặt tại điểm M trong điện trường đều có cường độ<br>E = 2400 V/m thì chịu tác dụng của lực điện có độ lớn là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm đặt trong điện trường đều có độ lớn: $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $q = 2\\ \\mu C = 2\\cdot 10^{-6}\\ C$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2\\cdot 10^{-6} \\cdot 2400 = 4{,}8\\cdot 10^{-3}\\ N$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực điện có độ lớn $4{,}8\\cdot 10^{-3}\\ N$, đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":819,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":3,"options":["4,8.10<sup>3</sup>N","4,8N","48N","4,8.10<sup>−3</sup>N"],"question":"Một điện tích điểm q = 2 μC được đặt tại điểm M trong điện trường đều có cường độ<br>E = 2400 V/m thì chịu tác dụng của lực điện có độ lớn là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm đặt trong điện trường đều có độ lớn: $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $q = 2\\ \\mu C = 2\\cdot 10^{-6}\\ C$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2\\cdot 10^{-6} \\cdot 2400 = 4{,}8\\cdot 10^{-3}\\ N$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực điện có độ lớn $4{,}8\\cdot 10^{-3}\\ N$, đáp án D.</p>","difficultySource":"ai"}}]},{"id":1183581,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực tương tác giữa hai điện tích","question":"Cho hai điện tích điểm  $q_1=−4.10^{−7}C$ và  $q_2=5.10^{−7}C$  đặt cách nhau 10 cm trong chân không. Lấy k =  $\\frac{1}{4\\pi \\varepsilon_0}$ = 9.10<sup>9</sup> N.m2/C2<br>a)","difficulty":"kho","statements":[{"text":"Hai điện tích hút nhau, lực hút tuân theo định luật Coulomb.<br>b)","answer":true},{"text":"Lực tương tác giữa hai điện tích có độ lớn bằng 0,18 N.<br>c)","answer":true},{"text":"Nếu đồng thời tăng độ lớn của mỗi điện tích và khoảng cách giũa chúng lên gấp đôi thì lực hút giữa hai điện tích sẽ giảm hai lần<br>d)","answer":false},{"text":"Đặt hệ thống hai điện tích trên và giữ nguyên khoảng cách ban đầu vào trong dầu hỏa có hằng số điện môi $\\varepsilon$ = 2 thì lực tương tác giữa 2 điện tích sẽ giảm 4 lần","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Định luật Coulomb:</strong> Với hai điện tích điểm đứng yên trong môi trường đồng tính, lực tương tác có độ lớn $F=k\\dfrac{|q_1q_2|}{\\varepsilon r^2}$, phương là đường thẳng nối hai điện tích. Điện tích trái dấu thì hút nhau, cùng dấu thì đẩy nhau.</p><p class=\"text-base leading-relaxed my-2\"><strong>a) Đúng.</strong> Vì $q_1\\lt 0$ và $q_2\\gt 0$ nên hai điện tích trái dấu, chúng hút nhau. Lực tương tác này tuân theo định luật Coulomb.</p><p class=\"text-base leading-relaxed my-2\"><strong>b) Đúng.</strong> Trong chân không $\\varepsilon=1$, $r=0{,}1$ m:</p><p class=\"text-base leading-relaxed my-2\">$F=9\\cdot 10^{9}\\cdot\\dfrac{|-4\\cdot 10^{-7}|\\cdot|5\\cdot 10^{-7}|}{1\\cdot(0{,}1)^2}=9\\cdot 10^{9}\\cdot\\dfrac{20\\cdot 10^{-14}}{0{,}01}=0{,}18\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\"><strong>c) Sai.</strong> Khi tăng mỗi điện tích lên 2 lần thì $|q_1q_2|$ tăng $2\\cdot 2=4$ lần. Khi tăng khoảng cách lên 2 lần thì $r^2$ tăng 4 lần. Khi đó:</p><p class=\"text-base leading-relaxed my-2\">$F'=k\\dfrac{4|q_1q_2|}{4r^2}=F$</p><p class=\"text-base leading-relaxed my-2\">Lực hút không đổi, không giảm 2 lần.</p><p class=\"text-base leading-relaxed my-2\"><strong>d) Sai.</strong> Khi đặt trong dầu hỏa có $\\varepsilon=2$, với cùng khoảng cách:</p><p class=\"text-base leading-relaxed my-2\">$F'=\\dfrac{F}{\\varepsilon}=\\dfrac{0{,}18}{2}=0{,}09\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Lực chỉ giảm 2 lần, không phải 4 lần.</p>","difficultySource":"ai"},"ex":[{"exam":819,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Lực tương tác giữa hai điện tích","question":"Cho hai điện tích điểm  $q_1=−4.10^{−7}C$ và  $q_2=5.10^{−7}C$  đặt cách nhau 10 cm trong chân không. Lấy k =  $\\frac{1}{4\\pi \\varepsilon_0}$ = 9.10<sup>9</sup> N.m2/C2<br>a)","difficulty":"kho","statements":[{"text":"Hai điện tích hút nhau, lực hút tuân theo định luật Coulomb.<br>b)","answer":true},{"text":"Lực tương tác giữa hai điện tích có độ lớn bằng 0,18 N.<br>c)","answer":true},{"text":"Nếu đồng thời tăng độ lớn của mỗi điện tích và khoảng cách giũa chúng lên gấp đôi thì lực hút giữa hai điện tích sẽ giảm hai lần<br>d)","answer":false},{"text":"Đặt hệ thống hai điện tích trên và giữ nguyên khoảng cách ban đầu vào trong dầu hỏa có hằng số điện môi $\\varepsilon$ = 2 thì lực tương tác giữa 2 điện tích sẽ giảm 4 lần","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Định luật Coulomb:</strong> Với hai điện tích điểm đứng yên trong môi trường đồng tính, lực tương tác có độ lớn $F=k\\dfrac{|q_1q_2|}{\\varepsilon r^2}$, phương là đường thẳng nối hai điện tích. Điện tích trái dấu thì hút nhau, cùng dấu thì đẩy nhau.</p><p class=\"text-base leading-relaxed my-2\"><strong>a) Đúng.</strong> Vì $q_1\\lt 0$ và $q_2\\gt 0$ nên hai điện tích trái dấu, chúng hút nhau. Lực tương tác này tuân theo định luật Coulomb.</p><p class=\"text-base leading-relaxed my-2\"><strong>b) Đúng.</strong> Trong chân không $\\varepsilon=1$, $r=0{,}1$ m:</p><p class=\"text-base leading-relaxed my-2\">$F=9\\cdot 10^{9}\\cdot\\dfrac{|-4\\cdot 10^{-7}|\\cdot|5\\cdot 10^{-7}|}{1\\cdot(0{,}1)^2}=9\\cdot 10^{9}\\cdot\\dfrac{20\\cdot 10^{-14}}{0{,}01}=0{,}18\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\"><strong>c) Sai.</strong> Khi tăng mỗi điện tích lên 2 lần thì $|q_1q_2|$ tăng $2\\cdot 2=4$ lần. Khi tăng khoảng cách lên 2 lần thì $r^2$ tăng 4 lần. Khi đó:</p><p class=\"text-base leading-relaxed my-2\">$F'=k\\dfrac{4|q_1q_2|}{4r^2}=F$</p><p class=\"text-base leading-relaxed my-2\">Lực hút không đổi, không giảm 2 lần.</p><p class=\"text-base leading-relaxed my-2\"><strong>d) Sai.</strong> Khi đặt trong dầu hỏa có $\\varepsilon=2$, với cùng khoảng cách:</p><p class=\"text-base leading-relaxed my-2\">$F'=\\dfrac{F}{\\varepsilon}=\\dfrac{0{,}18}{2}=0{,}09\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Lực chỉ giảm 2 lần, không phải 4 lần.</p>","difficultySource":"ai"}}]},{"id":1183582,"nq":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Một điện tích điểm Q = 8.10<sup>−4</sup>C được đặt trong chân không. Hằng số k = 9.10<sup>9</sup> Nm2/C2. Điểm M cách Q một đoạn 4cm.<br>a)","difficulty":"kho","statements":[{"text":"Véc tơ cường độ điện trường do điện tích Q gây ra tại M biểu diễn như hình vẽ     <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216687413-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>b)","answer":true},{"text":"Cường độ điện trường tại M có giá trị là 45.108 V/m<br>c)","answer":true},{"text":"Nếu cùng lúc đổi dấu điện tích Q và đổi vị trí điểm M thì hướng véc tơ cường độ điện trường tại M vẫn sẽ hướng xa điện tích Q<br>d)","answer":false},{"text":"Giữ nguyên hệ thống ban đầu, đặt một điện tích thử q >0 tại M rồi tăng dần độ lớn q thì thấy độ lớn của cường độ điện trường tại M giảm dần vì chúng tuân theo công thức E = F/q","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Đúng. $Q\\gt 0$ nên véctơ cường độ điện trường tại M hướng ra xa Q, đúng với hình vẽ (mũi tên hướng sang phải, ra xa Q).</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. $E=\\dfrac{k|Q|}{r^2}=\\dfrac{9.10^9\\cdot 8.10^{-4}}{(0{,}04)^2}=4{,}5.10^9\\ \\text{V/m}=45.10^8\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. Khi đổi dấu Q thành điện tích âm thì tại mọi điểm, kể cả điểm M ở vị trí mới, véctơ cường độ điện trường hướng về phía Q chứ không xa Q.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. Cường độ điện trường tại M chỉ phụ thuộc Q và khoảng cách r, không phụ thuộc điện tích thử q; tăng q thì F tăng tỉ lệ nên $E=F/q$ không đổi.</p>","difficultySource":"ai"},"ex":[{"exam":819,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Một điện tích điểm Q = 8.10<sup>−4</sup>C được đặt trong chân không. Hằng số k = 9.10<sup>9</sup> Nm2/C2. Điểm M cách Q một đoạn 4cm.<br>a)","difficulty":"kho","statements":[{"text":"Véc tơ cường độ điện trường do điện tích Q gây ra tại M biểu diễn như hình vẽ     <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216687413-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>b)","answer":true},{"text":"Cường độ điện trường tại M có giá trị là 45.108 V/m<br>c)","answer":true},{"text":"Nếu cùng lúc đổi dấu điện tích Q và đổi vị trí điểm M thì hướng véc tơ cường độ điện trường tại M vẫn sẽ hướng xa điện tích Q<br>d)","answer":false},{"text":"Giữ nguyên hệ thống ban đầu, đặt một điện tích thử q >0 tại M rồi tăng dần độ lớn q thì thấy độ lớn của cường độ điện trường tại M giảm dần vì chúng tuân theo công thức E = F/q","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1183583,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"3,16","question":"Cho hai điện tích điểm q1 và  q2 có độ lớn bằng nhau đặt trong không khí cách nhau 10cm. Biết lực hút tĩnh điện giữa hai điện tích là 0,09N; Cho K = 9.10<sup>9</sup> Nm2/C2. Độ lớn hai điện tích có giá trị là |q1| = |q2| = a.10<sup>−7</sup>C. Tìm a ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong không khí được tính theo định luật Cu-lông: $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $\\varepsilon = 1$ (không khí), $r$ là khoảng cách giữa hai điện tích.</p><p class=\"text-base leading-relaxed my-2\">Vì $|q_1| = |q_2| = q$ nên $F = k\\dfrac{q^2}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q^2 = \\dfrac{F r^2}{k}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q^2 = \\dfrac{0{,}09 \\cdot (0{,}1)^2}{9\\cdot 10^9} = \\dfrac{9\\cdot 10^{-4}}{9\\cdot 10^{9}} = 10^{-13}\\ \\text{C}^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q = \\sqrt{10^{-13}} \\approx 3{,}16\\cdot 10^{-7}\\ \\text{C}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $a \\approx 3{,}16$.</p>","difficultySource":"ai"},"ex":[{"exam":819,"idx":14,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"3,16","question":"Cho hai điện tích điểm q1 và  q2 có độ lớn bằng nhau đặt trong không khí cách nhau 10cm. Biết lực hút tĩnh điện giữa hai điện tích là 0,09N; Cho K = 9.10<sup>9</sup> Nm2/C2. Độ lớn hai điện tích có giá trị là |q1| = |q2| = a.10<sup>−7</sup>C. Tìm a ?","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1184861,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Cho hai điện tích điểm q1 và q2 có độ lớn bằng nhau đặt trong chân không, cách nhau một khoảng $r = 2\\,\\text{cm}$. Lực đẩy tĩnh điện giữa chúng là F = 18.10<sup>−5</sup> N.","difficulty":"trung-binh","statements":[{"text":"Lực mà hai điện tích tác dụng lên nhau tuân theo quy luật Coulomb.","answer":true},{"text":"Lực tương tác giữa hai điện tính được xác định bởi công thức <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216750127-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />.","answer":true},{"text":"Hai điện tích q1 và q2 nhiễm điện trái dấu.","answer":false},{"text":"Nếu khoảng cách giữa hai điện tích tăng lên 3 lần thì lực điện tương tác giữa chúng có độ lớn là 2.10<sup>−5</sup> N.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Đúng. Hai điện tích có độ lớn bằng nhau nên $F=k\\dfrac{|q_1q_2|}{r^2}$ đúng định luật Coulomb.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Trong chân không $F=\\dfrac{|q_1q_2|}{4\\pi\\varepsilon_0r^2}=9.10^9\\dfrac{|q_1q_2|}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. Lực là lực đẩy nên hai điện tích cùng dấu.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. $F\\sim\\dfrac1{r^2}$: r tăng 3 lần thì F giảm 9 lần, $F'=\\dfrac{18.10^{-5}}{9}=2.10^{-5}\\ \\text{N}$.</p>","difficultySource":"ai"},"ex":[{"exam":821,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Cho hai điện tích điểm q1 và q2 có độ lớn bằng nhau đặt trong chân không, cách nhau một khoảng $r = 2\\,\\text{cm}$. Lực đẩy tĩnh điện giữa chúng là F = 18.10<sup>−5</sup> N.","difficulty":"trung-binh","statements":[{"text":"Lực mà hai điện tích tác dụng lên nhau tuân theo quy luật Coulomb.","answer":true},{"text":"Lực tương tác giữa hai điện tính được xác định bởi công thức <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216750127-hinh-11.png\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />.","answer":true},{"text":"Hai điện tích q1 và q2 nhiễm điện trái dấu.","answer":false},{"text":"Nếu khoảng cách giữa hai điện tích tăng lên 3 lần thì lực điện tương tác giữa chúng có độ lớn là 2.10<sup>−5</sup> N.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1184862,"nq":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Một điện tích điểm $Q = +2.10^{-8}\\,\\text{C}$ đặt tại M trong chân không. Lấy <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216750552-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Điện trường do điện tích Q gây ra xung quanh nó là điện trường đều.","answer":false},{"text":"Cường độ điện trường do điện tích do Q gây ra tại một điểm cách nó một khoảng r được xác định theo công thức $E = k\\dfrac{|Q|}{r^2}$","answer":true},{"text":"Vect-tơ cường độ điện trường do điện tích Q gây ra tại điểm N có chiều hướng từ N đến M.","answer":false},{"text":"Một điện tích thử $q = 2.10^{-8}\\,\\text{C}$ đặt tại N cách M là 3cm thì lực điện tác dụng lên q cùng hướng với vec-tơ cường độ điện trường $\\overrightarrow{E_N}$ do Q gây ra tại N và có độ lớn là 4.10<sup>−3</sup> N.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Sai. Điện trường của điện tích điểm có hướng và độ lớn thay đổi theo vị trí nên không phải điện trường đều.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Đó là công thức $E=k\\dfrac{|Q|}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. $Q\\gt 0$ nên $\\vec E_N$ hướng ra xa Q, tức hướng từ M đến N chứ không phải từ N đến M.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. $q\\gt 0$ nên $\\vec F$ cùng hướng $\\vec E_N$; $F=\\dfrac{k|Qq|}{r^2}=\\dfrac{9.10^9\\cdot2.10^{-8}\\cdot2.10^{-8}}{(0{,}03)^2}=4.10^{-3}\\ \\text{N}$.</p>","difficultySource":"ai"},"ex":[{"exam":821,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Một điện tích điểm $Q = +2.10^{-8}\\,\\text{C}$ đặt tại M trong chân không. Lấy <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216750552-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Điện trường do điện tích Q gây ra xung quanh nó là điện trường đều.","answer":false},{"text":"Cường độ điện trường do điện tích do Q gây ra tại một điểm cách nó một khoảng r được xác định theo công thức $E = k\\dfrac{|Q|}{r^2}$","answer":true},{"text":"Vect-tơ cường độ điện trường do điện tích Q gây ra tại điểm N có chiều hướng từ N đến M.","answer":false},{"text":"Một điện tích thử $q = 2.10^{-8}\\,\\text{C}$ đặt tại N cách M là 3cm thì lực điện tác dụng lên q cùng hướng với vec-tơ cường độ điện trường $\\overrightarrow{E_N}$ do Q gây ra tại N và có độ lớn là 4.10<sup>−3</sup> N.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1185049,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":1,"options":["0,025 V/m.","4000 V/m.","2,5.10<sup>−4</sup> V/m.","40 V/m."],"question":"Có hai tấm kim loại phẳng, đặt song song, cách nhau một khoảng 5 cm được tích điện cùng độ lớn nhưng trái dấu nhờ một hiệu điện thế 200 V. Cường độ điện trường trong vùng không gian ở giữa hai bản là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trường giữa hai bản kim loại phẳng song song, tích điện trái dấu, là điện trường đều. Cường độ điện trường được tính theo công thức $E = \\dfrac{U}{d}$, trong đó $U$ là hiệu điện thế giữa hai bản và $d$ là khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $d = 5\\ \\text{cm} = 0{,}05\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = \\dfrac{200}{0{,}05} = 4000\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ điện trường giữa hai bản là $4000\\ \\text{V/m}$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":822,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":1,"options":["0,025 V/m.","4000 V/m.","2,5.10<sup>−4</sup> V/m.","40 V/m."],"question":"Có hai tấm kim loại phẳng, đặt song song, cách nhau một khoảng 5 cm được tích điện cùng độ lớn nhưng trái dấu nhờ một hiệu điện thế 200 V. Cường độ điện trường trong vùng không gian ở giữa hai bản là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trường giữa hai bản kim loại phẳng song song, tích điện trái dấu, là điện trường đều. Cường độ điện trường được tính theo công thức $E = \\dfrac{U}{d}$, trong đó $U$ là hiệu điện thế giữa hai bản và $d$ là khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $d = 5\\ \\text{cm} = 0{,}05\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = \\dfrac{200}{0{,}05} = 4000\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ điện trường giữa hai bản là $4000\\ \\text{V/m}$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":1185051,"nq":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216757373-hinh-2.webp\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Màng tế bào là một màng sinh học phân cách môi trường bên trong của các tế bào với môi trường bên ngoài của chúng, có thể cho phép các ion thấm qua một cách có chọn lọc và kiểm soát sự di chuyển của các chất ra và vào tế bào. Sự thẩm thấu các ion khác nhau khiến cho hai mặt của màng tế bào nhiễm điện trái dấu, mặt ngoài nhiễm điện dương, mặt trong nhiễm điện âm và tạo ra chệnh lệch điện thế, gọi là hiệu điện thế màng. (Tổng hợp từ internet)<br>Xét một màng tế bào dày 8 nm, có hiệu điện thế màng 50 mV đang cho một ion K+ có điện tích 1,6.10<sup>−19</sup> C đi từ bên trong tế bào ra ngoài. Trong các nhận định sau, nhận dịnh nào đúng, nhận định nào sai?","difficulty":"kho","statements":[{"text":"Nếu lấy điện thế mặt trong màng tế bào làm mốc thì điện thế mặt ngoài là 50 mV.","answer":true},{"text":"Điện trường trên màng tế bào có chiều hướng từ ngoài vào trong.","answer":true},{"text":"Ion K+ đang di chuyển cùng chiều điện trường trên màng nên lực điện trường sinh công dương.","answer":false},{"text":"Công của lực điện tác dụng lên ion K+ là 8.10<sup>−21</sup> J.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Mặt ngoài tích điện dương, mặt trong tích điện âm, hiệu điện thế màng $U=50\\ \\text{mV}$.</p><p class=\"text-base leading-relaxed my-2\">a) Đúng. Mốc ở mặt trong thì $V_{ngoài}-V_{trong}=50\\ \\text{mV}$ nên $V_{ngoài}=50\\ \\text{mV}$.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Điện trường hướng từ nơi điện thế cao (mặt ngoài) sang nơi điện thế thấp (mặt trong), tức từ ngoài vào trong.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. Ion $K^+$ đi từ trong ra ngoài, ngược chiều điện trường nên lực điện sinh công âm.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. $A=qU_{trong\\to ngoài}=-1{,}6.10^{-19}\\cdot 0{,}05=-8.10^{-21}\\ \\text{J}$; độ lớn 8.10<sup>−21</sup> J nhưng công là âm.</p>","difficultySource":"ai"},"ex":[{"exam":822,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216757373-hinh-2.webp\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Màng tế bào là một màng sinh học phân cách môi trường bên trong của các tế bào với môi trường bên ngoài của chúng, có thể cho phép các ion thấm qua một cách có chọn lọc và kiểm soát sự di chuyển của các chất ra và vào tế bào. Sự thẩm thấu các ion khác nhau khiến cho hai mặt của màng tế bào nhiễm điện trái dấu, mặt ngoài nhiễm điện dương, mặt trong nhiễm điện âm và tạo ra chệnh lệch điện thế, gọi là hiệu điện thế màng. (Tổng hợp từ internet)<br>Xét một màng tế bào dày 8 nm, có hiệu điện thế màng 50 mV đang cho một ion K+ có điện tích 1,6.10<sup>−19</sup> C đi từ bên trong tế bào ra ngoài. Trong các nhận định sau, nhận dịnh nào đúng, nhận định nào sai?","difficulty":"kho","statements":[{"text":"Nếu lấy điện thế mặt trong màng tế bào làm mốc thì điện thế mặt ngoài là 50 mV.","answer":true},{"text":"Điện trường trên màng tế bào có chiều hướng từ ngoài vào trong.","answer":true},{"text":"Ion K+ đang di chuyển cùng chiều điện trường trên màng nên lực điện trường sinh công dương.","answer":false},{"text":"Công của lực điện tác dụng lên ion K+ là 8.10<sup>−21</sup> J.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1185054,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"2000","question":"Một điện tích 4.10<sup>−7</sup> C khi đặt trong điện trường thì chịu một lực điện có độ lớn 8.10<sup>−4</sup> N. Độ lớn cường độ điện trường bằng bao nhiêu V/m?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường tại một điểm được xác định bằng tỉ số giữa lực điện tác dụng lên điện tích thử và độ lớn của điện tích đó: $E = \\dfrac{F}{|q|}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $F = 8.10^{-4}\\ \\text{N}$ và $|q| = 4.10^{-7}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$E = \\dfrac{8.10^{-4}}{4.10^{-7}} = 2000\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn cường độ điện trường là $2000\\ \\text{V/m}$.</p>","difficultySource":"ai"},"ex":[{"exam":822,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"2000","question":"Một điện tích 4.10<sup>−7</sup> C khi đặt trong điện trường thì chịu một lực điện có độ lớn 8.10<sup>−4</sup> N. Độ lớn cường độ điện trường bằng bao nhiêu V/m?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường tại một điểm được xác định bằng tỉ số giữa lực điện tác dụng lên điện tích thử và độ lớn của điện tích đó: $E = \\dfrac{F}{|q|}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $F = 8.10^{-4}\\ \\text{N}$ và $|q| = 4.10^{-7}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$E = \\dfrac{8.10^{-4}}{4.10^{-7}} = 2000\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn cường độ điện trường là $2000\\ \\text{V/m}$.</p>","difficultySource":"ai"}}]},{"id":1185390,"nq":{"form":"bai_tap","type":"true_false","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","question":"A, B, C là ba điểm tạo thành tam giác vuông tại A đặt trong điện trường đều của một tụ phẳng không khí. Biết hiệu điện thế giữa hai bản tụ là U = 300V và khoảng cách giữa hai bản là d = 15 cm. Cho  $\\alpha =60^{\\circ}$ ;  $BC=12cm$ . <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216764713-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>a)","difficulty":"kho","statements":[{"text":"Điện trường bên trong tụ điện là điện trường đều và đường sức điện hướng từ bản âm sang bản dương<br>b)","answer":false},{"text":"Đặt một điện tích dương tại điểm B thì nó sẽ di chuyển sang bản âm<br>c)","answer":true},{"text":"Độ lớn cường độ điện trường là E = 2000 V/m<br>d)","answer":true},{"text":"Công thực hiện để dịch chuyển điện tích  $q=10^{-9}C$  từ B đến C là 1,5.10<sup>−7</sup> J","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Bản trái dương, bản phải âm; $U=300\\ \\text{V}$, $d=15\\ \\text{cm}$.</p><p class=\"text-base leading-relaxed my-2\">a) Sai. Đường sức điện hướng từ bản dương sang bản âm.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. Điện tích dương chịu lực cùng chiều điện trường nên di chuyển về phía bản âm.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $E=\\dfrac{U}{d}=\\dfrac{300}{0{,}15}=2000\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. Hình chiếu của BC lên phương đường sức: $BA=BC\\cos60^\\circ=6\\ \\text{cm}$. $A=qE\\cdot BA=10^{-9}\\cdot2000\\cdot0{,}06=1{,}2.10^{-7}\\ \\text{J}$, khác $1{,}5.10^{-7}\\ \\text{J}$.</p>","difficultySource":"ai"},"ex":[{"exam":823,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","question":"A, B, C là ba điểm tạo thành tam giác vuông tại A đặt trong điện trường đều của một tụ phẳng không khí. Biết hiệu điện thế giữa hai bản tụ là U = 300V và khoảng cách giữa hai bản là d = 15 cm. Cho  $\\alpha =60^{\\circ}$ ;  $BC=12cm$ . <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216764713-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>a)","difficulty":"kho","statements":[{"text":"Điện trường bên trong tụ điện là điện trường đều và đường sức điện hướng từ bản âm sang bản dương<br>b)","answer":false},{"text":"Đặt một điện tích dương tại điểm B thì nó sẽ di chuyển sang bản âm<br>c)","answer":true},{"text":"Độ lớn cường độ điện trường là E = 2000 V/m<br>d)","answer":true},{"text":"Công thực hiện để dịch chuyển điện tích  $q=10^{-9}C$  từ B đến C là 1,5.10<sup>−7</sup> J","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1185420,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":2,"options":["0,2 µC.","0,15 µC.","0,1 µC.","0,25 µC."],"question":"Hai quả cầu nhỏ mang điện tích có độ lớn bằng nhau, đặt cách nhau 10 cm trong chân không thì tác dụng lên nhau một lực 9.10<sup>−3</sup> N. Xác định độ lớn điện tích của hai quả cầu đó.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác giữa hai điện tích điểm đặt trong chân không là $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Hai quả cầu có điện tích độ lớn bằng nhau, $|q_1| = |q_2| = q$, nên $F = k\\dfrac{q^2}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $q^2 = \\dfrac{F\\,r^2}{k}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q^2 = \\dfrac{9.10^{-3}\\cdot(0,1)^2}{9.10^9} = \\dfrac{9.10^{-5}}{9.10^9} = 10^{-14}\\ \\text{C}^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q = 10^{-7}\\ \\text{C} = 0,1\\ \\mu\\text{C}$</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn điện tích của mỗi quả cầu là $0,1\\ \\mu\\text{C}$, chọn đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":824,"idx":0,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":2,"options":["0,2 µC.","0,15 µC.","0,1 µC.","0,25 µC."],"question":"Hai quả cầu nhỏ mang điện tích có độ lớn bằng nhau, đặt cách nhau 10 cm trong chân không thì tác dụng lên nhau một lực 9.10<sup>−3</sup> N. Xác định độ lớn điện tích của hai quả cầu đó.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác giữa hai điện tích điểm đặt trong chân không là $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Hai quả cầu có điện tích độ lớn bằng nhau, $|q_1| = |q_2| = q$, nên $F = k\\dfrac{q^2}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra $q^2 = \\dfrac{F\\,r^2}{k}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q^2 = \\dfrac{9.10^{-3}\\cdot(0,1)^2}{9.10^9} = \\dfrac{9.10^{-5}}{9.10^9} = 10^{-14}\\ \\text{C}^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q = 10^{-7}\\ \\text{C} = 0,1\\ \\mu\\text{C}$</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn điện tích của mỗi quả cầu là $0,1\\ \\mu\\text{C}$, chọn đáp án C.</p>","difficultySource":"ai"}}]},{"id":1185424,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Tụ điện và điện dung","answer":3,"options":["4.10<sup>−3</sup>C","6.10<sup>−4</sup>C","3.10<sup>−3</sup>C","24.10<sup>−4</sup>C"],"question":"Trên vỏ một tụ điện có ghi 20 µF − 200 V. Nối hai bản tụ điện với một hiệu điện thế 120 V. Tụ điện tích được điện tích là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Tụ điện ghi $20\\ \\mu F - 200\\ V$: điện dung $C = 20\\ \\mu F$, hiệu điện thế giới hạn $U_{gh} = 200\\ V$.</p><p class=\"text-base leading-relaxed my-2\">Hiệu điện thế đặt vào $U = 120\\ V \\lt U_{gh} = 200\\ V$ nên tụ không bị đánh thủng và có thể tích điện bình thường.</p><p class=\"text-base leading-relaxed my-2\">Điện tích tích được: $Q = C \\cdot U$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 20 \\cdot 10^{-6} \\cdot 120 = 2{,}4 \\cdot 10^{-3}\\ C = 24 \\cdot 10^{-4}\\ C$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện tích tụ tích được là $24 \\cdot 10^{-4}\\ C$, chọn đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":824,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Tụ điện và điện dung","answer":3,"options":["4.10<sup>−3</sup>C","6.10<sup>−4</sup>C","3.10<sup>−3</sup>C","24.10<sup>−4</sup>C"],"question":"Trên vỏ một tụ điện có ghi 20 µF − 200 V. Nối hai bản tụ điện với một hiệu điện thế 120 V. Tụ điện tích được điện tích là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Tụ điện ghi $20\\ \\mu F - 200\\ V$: điện dung $C = 20\\ \\mu F$, hiệu điện thế giới hạn $U_{gh} = 200\\ V$.</p><p class=\"text-base leading-relaxed my-2\">Hiệu điện thế đặt vào $U = 120\\ V \\lt U_{gh} = 200\\ V$ nên tụ không bị đánh thủng và có thể tích điện bình thường.</p><p class=\"text-base leading-relaxed my-2\">Điện tích tích được: $Q = C \\cdot U$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $Q = 20 \\cdot 10^{-6} \\cdot 120 = 2{,}4 \\cdot 10^{-3}\\ C = 24 \\cdot 10^{-4}\\ C$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: điện tích tụ tích được là $24 \\cdot 10^{-4}\\ C$, chọn đáp án D.</p>","difficultySource":"ai"}}]},{"id":1185431,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Khái niệm điện trường. Cường độ điện trường","question":"Đặt một điện tích q trong một vùng không gian có điện trường mà các đường sức điện trường có phương nằm ngang, song song với nhau","difficulty":"trung-binh","statements":[{"text":"Nếu thay điện tích q > 0 thành điện tích q < 0 thì hướng điện trường thay đổi.","answer":false},{"text":"Cho q = -1,6.10<sup>−19</sup>C; E = 1600 V/m thì độ lớn lực điện tác dụng lên điện tích q là 2,56.10<sup>−16</sup> N.","answer":true},{"text":"q < 0 thì  $\\vec{F}$  cùng phương ngược chiều với $\\vec{E}$","answer":true},{"text":"q > 0 thì  $\\vec{F}$  cùng phương cùng chiều với $\\vec{E}$","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm $q$ đặt trong điện trường $\\vec{E}$: $\\vec{F} = q\\vec{E}$, có độ lớn $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\"><b>a) Sai.</b> Véctơ cường độ điện trường $\\vec{E}$ chỉ phụ thuộc vào nguồn tạo ra điện trường, không phụ thuộc vào điện tích thử $q$. Đổi dấu $q$ chỉ làm đổi chiều lực $\\vec{F}$, không làm đổi hướng điện trường.</p><p class=\"text-base leading-relaxed my-2\"><b>b) Đúng.</b> $F = |q|E = 1{,}6.10^{-19}\\cdot 1600 = 2{,}56.10^{-16}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\"><b>c) Đúng.</b> Khi $q \\lt 0$ thì $\\vec{F} = q\\vec{E}$ ngược hướng với $\\vec{E}$, nên $\\vec{F}$ cùng phương, ngược chiều với $\\vec{E}$.</p><p class=\"text-base leading-relaxed my-2\"><b>d) Đúng.</b> Khi $q \\gt 0$ thì $\\vec{F} = q\\vec{E}$ cùng hướng với $\\vec{E}$, nên $\\vec{F}$ cùng phương, cùng chiều với $\\vec{E}$.</p>","difficultySource":"ai"},"ex":[{"exam":824,"idx":11,"el":{"form":"ly_thuyet","type":"true_false","topic":"Khái niệm điện trường. Cường độ điện trường","question":"Đặt một điện tích q trong một vùng không gian có điện trường mà các đường sức điện trường có phương nằm ngang, song song với nhau","difficulty":"trung-binh","statements":[{"text":"Nếu thay điện tích q > 0 thành điện tích q < 0 thì hướng điện trường thay đổi.","answer":false},{"text":"Cho q = -1,6.10<sup>−19</sup>C; E = 1600 V/m thì độ lớn lực điện tác dụng lên điện tích q là 2,56.10<sup>−16</sup> N.","answer":true},{"text":"q < 0 thì  $\\vec{F}$  cùng phương ngược chiều với $\\vec{E}$","answer":true},{"text":"q > 0 thì  $\\vec{F}$  cùng phương cùng chiều với $\\vec{E}$","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm $q$ đặt trong điện trường $\\vec{E}$: $\\vec{F} = q\\vec{E}$, có độ lớn $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\"><b>a) Sai.</b> Véctơ cường độ điện trường $\\vec{E}$ chỉ phụ thuộc vào nguồn tạo ra điện trường, không phụ thuộc vào điện tích thử $q$. Đổi dấu $q$ chỉ làm đổi chiều lực $\\vec{F}$, không làm đổi hướng điện trường.</p><p class=\"text-base leading-relaxed my-2\"><b>b) Đúng.</b> $F = |q|E = 1{,}6.10^{-19}\\cdot 1600 = 2{,}56.10^{-16}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\"><b>c) Đúng.</b> Khi $q \\lt 0$ thì $\\vec{F} = q\\vec{E}$ ngược hướng với $\\vec{E}$, nên $\\vec{F}$ cùng phương, ngược chiều với $\\vec{E}$.</p><p class=\"text-base leading-relaxed my-2\"><b>d) Đúng.</b> Khi $q \\gt 0$ thì $\\vec{F} = q\\vec{E}$ cùng hướng với $\\vec{E}$, nên $\\vec{F}$ cùng phương, cùng chiều với $\\vec{E}$.</p>","difficultySource":"ai"}}]},{"id":1185432,"nq":{"form":"bai_tap","type":"true_false","topic":"Tụ điện và điện dung","question":"Trên vỏ một tụ điện có ghi 5 µF – 220 V. Từ thông số trên vỏ của tụ ta có?","difficulty":"trung-binh","statements":[{"text":"Nối hai bản tụ với hiệu điện thế 120 V, điện tích của tụ điện tích được là 6.10<sup>−3</sup> C.","answer":false},{"text":"Năng lượng điện trường dự trữ trong tụ điện là  0,2 J.","answer":false},{"text":"Điện tích tối đa mà tụ điện tích được là 11. 10<sup>−4</sup> C","answer":true},{"text":"Điện dung của tụ điện là 5.10<sup>−6</sup> F","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông số trên vỏ tụ: điện dung $C = 5\\ \\mu F = 5\\cdot 10^{-6}\\ F$, hiệu điện thế định mức $U_{max} = 220\\ V$.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Điện tích của tụ: $Q = CU$. Với $U = 120\\ V$: $Q = 5\\cdot 10^{-6}\\cdot 120 = 6\\cdot 10^{-4}\\ C$, không phải $6\\cdot 10^{-3}\\ C$. Ý a) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Năng lượng điện trường lớn nhất khi tụ tích điện ở hiệu điện thế định mức: $W = \\dfrac{1}{2}CU^2 = \\dfrac{1}{2}\\cdot 5\\cdot 10^{-6}\\cdot 220^2 = 0{,}121\\ J$.</p><p class=\"text-base leading-relaxed my-2\">Không có hiệu điện thế nào trong giới hạn an toàn cho năng lượng $0{,}2\\ J$, vì khi đó $U = \\sqrt{\\dfrac{2W}{C}} \\approx 283\\ V \\gt  220\\ V$. Ý b) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Điện tích tối đa tụ tích được: $Q_{max} = CU_{max} = 5\\cdot 10^{-6}\\cdot 220 = 1{,}1\\cdot 10^{-3}\\ C = 11\\cdot 10^{-4}\\ C$. Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Điện dung của tụ là $C = 5\\ \\mu F = 5\\cdot 10^{-6}\\ F$, đúng với thông số ghi trên vỏ. Ý d) <b>Đúng</b>.</p>","difficultySource":"ai"},"ex":[{"exam":824,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Tụ điện và điện dung","question":"Trên vỏ một tụ điện có ghi 5 µF – 220 V. Từ thông số trên vỏ của tụ ta có?","difficulty":"trung-binh","statements":[{"text":"Nối hai bản tụ với hiệu điện thế 120 V, điện tích của tụ điện tích được là 6.10<sup>−3</sup> C.","answer":false},{"text":"Năng lượng điện trường dự trữ trong tụ điện là  0,2 J.","answer":false},{"text":"Điện tích tối đa mà tụ điện tích được là 11. 10<sup>−4</sup> C","answer":true},{"text":"Điện dung của tụ điện là 5.10<sup>−6</sup> F","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Từ thông số trên vỏ tụ: điện dung $C = 5\\ \\mu F = 5\\cdot 10^{-6}\\ F$, hiệu điện thế định mức $U_{max} = 220\\ V$.</p><p class=\"text-base leading-relaxed my-2\"><b>a)</b> Điện tích của tụ: $Q = CU$. Với $U = 120\\ V$: $Q = 5\\cdot 10^{-6}\\cdot 120 = 6\\cdot 10^{-4}\\ C$, không phải $6\\cdot 10^{-3}\\ C$. Ý a) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>b)</b> Năng lượng điện trường lớn nhất khi tụ tích điện ở hiệu điện thế định mức: $W = \\dfrac{1}{2}CU^2 = \\dfrac{1}{2}\\cdot 5\\cdot 10^{-6}\\cdot 220^2 = 0{,}121\\ J$.</p><p class=\"text-base leading-relaxed my-2\">Không có hiệu điện thế nào trong giới hạn an toàn cho năng lượng $0{,}2\\ J$, vì khi đó $U = \\sqrt{\\dfrac{2W}{C}} \\approx 283\\ V \\gt  220\\ V$. Ý b) <b>Sai</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>c)</b> Điện tích tối đa tụ tích được: $Q_{max} = CU_{max} = 5\\cdot 10^{-6}\\cdot 220 = 1{,}1\\cdot 10^{-3}\\ C = 11\\cdot 10^{-4}\\ C$. Ý c) <b>Đúng</b>.</p><p class=\"text-base leading-relaxed my-2\"><b>d)</b> Điện dung của tụ là $C = 5\\ \\mu F = 5\\cdot 10^{-6}\\ F$, đúng với thông số ghi trên vỏ. Ý d) <b>Đúng</b>.</p>","difficultySource":"ai"}}]},{"id":1185433,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"5","question":"Cường độ điện trường do điện tích Q = -6.10 – 9C gây ra tại một điểm M trong không khí cách điện tích Q là 2,16.10<sup>4</sup> V/m. Khoảng cách từ Q đến M bằng bao nhiêu (theo đơn vị cm) ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm $Q$ gây ra trong không khí (hằng số điện môi $\\varepsilon = 1$) tại điểm cách $Q$ một khoảng $r$ là:</p><p class=\"text-base leading-relaxed my-2\">$E = k\\dfrac{|Q|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r = \\sqrt{\\dfrac{k|Q|}{E}}$</p><p class=\"text-base leading-relaxed my-2\">Thay số với $|Q| = 6.10^{-9}\\ \\text{C}$ và $E = 2{,}16.10^4\\ \\text{V/m}$:</p><p class=\"text-base leading-relaxed my-2\">$r = \\sqrt{\\dfrac{9.10^9 \\cdot 6.10^{-9}}{2{,}16.10^4}} = \\sqrt{\\dfrac{54}{2{,}16.10^4}} = \\sqrt{2{,}5.10^{-3}} = 0{,}05\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r = 0{,}05\\ \\text{m} = 5\\ \\text{cm}$</p><p class=\"text-base leading-relaxed my-2\">Vậy khoảng cách từ $Q$ đến $M$ là $5$ cm.</p>","difficultySource":"ai"},"ex":[{"exam":824,"idx":13,"el":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"5","question":"Cường độ điện trường do điện tích Q = -6.10 – 9C gây ra tại một điểm M trong không khí cách điện tích Q là 2,16.10<sup>4</sup> V/m. Khoảng cách từ Q đến M bằng bao nhiêu (theo đơn vị cm) ?","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1186036,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Coulomb","answer":3,"options":["$F= \\frac{r^2}{k.\\left|q_1q_2\\right|}$","$F= r^2\\frac{\\left|q_1q_2\\right|}{k.}$","$F= \\frac{\\left|q_1q_2\\right|}{kr^2}$","$F= k\\frac{\\left|q_1q_2\\right|}{r^2}$"],"question":"Công thức nào dưới đây xác định độ lớn lực tương tác tĩnh điện giữa hai điện tích điểm q1, q2 đặt cách nhau một khoảng r trong chân không, với k = 9.10<sup>9</sup> N.m2/C2?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm trong chân không có độ lớn tỉ lệ thuận với tích độ lớn các điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $F = k\\dfrac{|q_1 q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$, $r$ là khoảng cách giữa hai điện tích (m), $q_1, q_2$ là độ lớn điện tích (C).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là phương án D.</p>","difficultySource":"ai"},"ex":[{"exam":825,"idx":0,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Coulomb","answer":3,"options":["$F= \\frac{r^2}{k.\\left|q_1q_2\\right|}$","$F= r^2\\frac{\\left|q_1q_2\\right|}{k.}$","$F= \\frac{\\left|q_1q_2\\right|}{kr^2}$","$F= k\\frac{\\left|q_1q_2\\right|}{r^2}$"],"question":"Công thức nào dưới đây xác định độ lớn lực tương tác tĩnh điện giữa hai điện tích điểm q1, q2 đặt cách nhau một khoảng r trong chân không, với k = 9.10<sup>9</sup> N.m2/C2?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm trong chân không có độ lớn tỉ lệ thuận với tích độ lớn các điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $F = k\\dfrac{|q_1 q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$, $r$ là khoảng cách giữa hai điện tích (m), $q_1, q_2$ là độ lớn điện tích (C).</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là phương án D.</p>","difficultySource":"ai"}}]},{"id":1186049,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"90","question":"Hai điện tích q1 = 3.10<sup>−6</sup> C và q2 = 3.10<sup>−6</sup> C đặt cách nhau một khoảng 3cm trong chân không. Lực tương tác giữa chúng có độ lớn bao nhiêu N?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực tương tác giữa hai điện tích điểm đặt trong chân không được xác định bởi định luật Coulomb: $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khoảng cách: $r = 3\\ \\text{cm} = 0{,}03\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $|q_1 q_2| = (3.10^{-6})(3.10^{-6}) = 9.10^{-12}\\ \\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">$F = 9.10^9 \\cdot \\dfrac{9.10^{-12}}{(0{,}03)^2} = \\dfrac{81.10^{-3}}{9.10^{-4}} = 90\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực tương tác giữa hai điện tích có độ lớn $F = 90\\ \\text{N}$ (lực đẩy vì hai điện tích cùng dấu).</p>","difficultySource":"ai"},"ex":[{"exam":825,"idx":13,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Coulomb","answer":"90","question":"Hai điện tích q1 = 3.10<sup>−6</sup> C và q2 = 3.10<sup>−6</sup> C đặt cách nhau một khoảng 3cm trong chân không. Lực tương tác giữa chúng có độ lớn bao nhiêu N?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực tương tác giữa hai điện tích điểm đặt trong chân không được xác định bởi định luật Coulomb: $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị khoảng cách: $r = 3\\ \\text{cm} = 0{,}03\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $|q_1 q_2| = (3.10^{-6})(3.10^{-6}) = 9.10^{-12}\\ \\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">$F = 9.10^9 \\cdot \\dfrac{9.10^{-12}}{(0{,}03)^2} = \\dfrac{81.10^{-3}}{9.10^{-4}} = 90\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: lực tương tác giữa hai điện tích có độ lớn $F = 90\\ \\text{N}$ (lực đẩy vì hai điện tích cùng dấu).</p>","difficultySource":"ai"}}]},{"id":1186052,"nq":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"-32","question":"Biết điện thế tại điểm M trong điện trường là 20V. Electron có điện tích e = -1,6.10<sup>−19</sup> C đặt tại điểm M có thế năng là bao nhiêu x.10<sup>−19</sup> J. Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng của điện tích $q$ tại điểm M có điện thế $V_M$ được tính theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$W_M = q\\cdot V_M$</p><p class=\"text-base leading-relaxed my-2\">Thay $q = -1{,}6\\cdot 10^{-19}\\ \\text{C}$ và $V_M = 20\\ \\text{V}$:</p><p class=\"text-base leading-relaxed my-2\">$W_M = -1{,}6\\cdot 10^{-19}\\cdot 20 = -32\\cdot 10^{-19}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x = -32$.</p>","difficultySource":"ai"},"ex":[{"exam":825,"idx":16,"el":{"form":"bai_tap","type":"short_answer","topic":"Thế năng điện. Điện thế","answer":"-32","question":"Biết điện thế tại điểm M trong điện trường là 20V. Electron có điện tích e = -1,6.10<sup>−19</sup> C đặt tại điểm M có thế năng là bao nhiêu x.10<sup>−19</sup> J. Giá trị của x là bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng của điện tích $q$ tại điểm M có điện thế $V_M$ được tính theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$W_M = q\\cdot V_M$</p><p class=\"text-base leading-relaxed my-2\">Thay $q = -1{,}6\\cdot 10^{-19}\\ \\text{C}$ và $V_M = 20\\ \\text{V}$:</p><p class=\"text-base leading-relaxed my-2\">$W_M = -1{,}6\\cdot 10^{-19}\\cdot 20 = -32\\cdot 10^{-19}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x = -32$.</p>","difficultySource":"ai"}}]},{"id":1186342,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":3,"options":["2.10<sup>4</sup>V/m","6.10<sup>5</sup>V/m","7,2.10<sup>3</sup>V/m","3,6.10<sup>3</sup>V/m"],"question":"Quả cầu nhỏ mang điện tích 10−9C đặt trong không khí. Cường độ điện trường tại một điểm cách quả cầu 5cm là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện tích điểm trong không khí ($\\varepsilon=1$): $E=\\dfrac{k|q|}{r^2}$ với $q=10^{-9}\\ C$, $r=0,05\\ m$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E=\\dfrac{9.10^9\\cdot 10^{-9}}{(0,05)^2}=\\dfrac{9}{0,0025}=3600=3,6.10^3\\ V/m$.</p><p class=\"text-base leading-relaxed my-2\">Chọn D.</p>","difficultySource":"ai"},"ex":[{"exam":826,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Cường độ điện trường của điện tích điểm","answer":3,"options":["2.10<sup>4</sup>V/m","6.10<sup>5</sup>V/m","7,2.10<sup>3</sup>V/m","3,6.10<sup>3</sup>V/m"],"question":"Quả cầu nhỏ mang điện tích 10−9C đặt trong không khí. Cường độ điện trường tại một điểm cách quả cầu 5cm là:","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1186349,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nguyên lí chồng chất điện trường","answer":"-12","question":"Ba điểm A, B, C trong không khí tạo thành tam giác vuông tại A, AB = 4 cm, AC=3cm. Tại A đặt điện tích q1 = 2,7 nC, tại B đặt điện tích q2. Lấy k= 9.10<sup>9</sup>(N.m2/C2). Véc tơ cường độ điện trường  $E$  tổng hợp tại C có phương song song với AB. Điện tích q2 có giá trị bằng bao nhiêu n $C$ ? (kết quả chỉ lấy phần nguyên)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216793267-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Tại C: $\\vec E_1$ do $q_1\\gt 0$ ở A hướng ra xa A, tức nằm ngang; $E_1=\\dfrac{k|q_1|}{AC^2}=\\dfrac{9.10^9\\cdot2{,}7.10^{-9}}{(0{,}03)^2}=2{,}7.10^4\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">Để $\\vec E$ tổng hợp song song AB thì thành phần ngang của $\\vec E_2$ phải triệt tiêu $E_1$, nên $\\vec E_2$ hướng về phía B (q2 âm). $BC=5\\ \\text{cm}$, thành phần ngang của $\\vec E_2$ là $E_2\\cdot\\dfrac{AC}{BC}=E_2\\cdot\\dfrac35$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$E_2\\cdot\\dfrac35=2{,}7.10^4$ nên $E_2=4{,}5.10^4\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$|q_2|=\\dfrac{E_2\\cdot BC^2}{k}=\\dfrac{4{,}5.10^4\\cdot(0{,}05)^2}{9.10^9}=1{,}25.10^{-8}\\ \\text{C}=12{,}5\\ \\text{nC}$.</p><p class=\"text-base leading-relaxed my-2\">Vì $q_2\\lt 0$ nên $q_2=-12{,}5\\ \\text{nC}$, lấy phần nguyên là -12.</p>","difficultySource":"ai"},"ex":[{"exam":826,"idx":17,"el":{"form":"bai_tap","type":"short_answer","topic":"Nguyên lí chồng chất điện trường","answer":"-12","question":"Ba điểm A, B, C trong không khí tạo thành tam giác vuông tại A, AB = 4 cm, AC=3cm. Tại A đặt điện tích q1 = 2,7 nC, tại B đặt điện tích q2. Lấy k= 9.10<sup>9</sup>(N.m2/C2). Véc tơ cường độ điện trường  $E$  tổng hợp tại C có phương song song với AB. Điện tích q2 có giá trị bằng bao nhiêu n $C$ ? (kết quả chỉ lấy phần nguyên)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791216793267-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","explanation":"","difficultySource":"ai"}}]},{"id":1186672,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Coulomb","answer":1,"options":["$F=r^2\\frac{\\left|q_1q_2\\right|}{k}$ .","$F=k\\frac{\\left|q_1q_2\\right|}{r^2}$ .","$F=\\frac{r^2}{k\\left|q_1q_2\\right|}$ .","$F=\\frac{\\left|q_1q_2\\right|}{k.r^2}$ ."],"question":"Công thức nào dưới đây xác định độ lớn lực tương tác tĩnh điện giữa hai điện tích điểm q1, q2 đặt cách nhau một khoảng r trong chân không, với k = 9.10<sup>9</sup> N.m2/C2 là hằng số Coulomb?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Coulomb: lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không có độ lớn tỉ lệ thuận với tích độ lớn các điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $F = k\\dfrac{|q_1 q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$, $q_1, q_2$ là độ lớn các điện tích (C), $r$ là khoảng cách (m).</p><p class=\"text-base leading-relaxed my-2\">Đối chiếu các phương án: A và C sai vì $r^2$ nằm sai vị trí; D sai vì $k$ đặt ở mẫu.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>B</b>.</p>","difficultySource":"ai"},"ex":[{"exam":827,"idx":1,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Coulomb","answer":1,"options":["$F=r^2\\frac{\\left|q_1q_2\\right|}{k}$ .","$F=k\\frac{\\left|q_1q_2\\right|}{r^2}$ .","$F=\\frac{r^2}{k\\left|q_1q_2\\right|}$ .","$F=\\frac{\\left|q_1q_2\\right|}{k.r^2}$ ."],"question":"Công thức nào dưới đây xác định độ lớn lực tương tác tĩnh điện giữa hai điện tích điểm q1, q2 đặt cách nhau một khoảng r trong chân không, với k = 9.10<sup>9</sup> N.m2/C2 là hằng số Coulomb?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Coulomb: lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không có độ lớn tỉ lệ thuận với tích độ lớn các điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $F = k\\dfrac{|q_1 q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$, $q_1, q_2$ là độ lớn các điện tích (C), $r$ là khoảng cách (m).</p><p class=\"text-base leading-relaxed my-2\">Đối chiếu các phương án: A và C sai vì $r^2$ nằm sai vị trí; D sai vì $k$ đặt ở mẫu.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là <b>B</b>.</p>","difficultySource":"ai"}}]},{"id":1186684,"nq":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Một proton có khối lượng 1,67.10<sup>−27</sup> kg và có điện tích 1,6.10<sup>−19</sup> C bay theo phương của một đường sức điện trường đều. Lúc proton ở điểm A thì tốc độ của nó bằng 2,5.10<sup>4</sup> m/s. Khi bay đến B vận tốc của proton bằng không. Bỏ qua tác dụng của trọng lực.","difficulty":"trung-binh","statements":[{"text":"Chiều đường điện trường từ A đến B.","answer":false},{"text":"Hiệu điện thế giữa hai điểm A,B là UAB = 13 V.","answer":false},{"text":"Nếu điện thế tại A bằng 400 V thì điện thế tại điểm B bằng 413 V.","answer":false},{"text":"Khi đến B, proton sẽ chuyển động ngược lại và khi đến A tốc độ của nó vẫn là 2,5.10<sup>4</sup> m/s.","answer":true}],"explanation":"","difficultySource":"ai"},"ex":[{"exam":827,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Một proton có khối lượng 1,67.10<sup>−27</sup> kg và có điện tích 1,6.10<sup>−19</sup> C bay theo phương của một đường sức điện trường đều. Lúc proton ở điểm A thì tốc độ của nó bằng 2,5.10<sup>4</sup> m/s. Khi bay đến B vận tốc của proton bằng không. Bỏ qua tác dụng của trọng lực.","difficulty":"trung-binh","statements":[{"text":"Chiều đường điện trường từ A đến B.","answer":false},{"text":"Hiệu điện thế giữa hai điểm A,B là UAB = 13 V.","answer":false},{"text":"Nếu điện thế tại A bằng 400 V thì điện thế tại điểm B bằng 413 V.","answer":false},{"text":"Khi đến B, proton sẽ chuyển động ngược lại và khi đến A tốc độ của nó vẫn là 2,5.10<sup>4</sup> m/s.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1187679,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng của tụ điện","answer":1,"options":["12 J.","7,2.10<sup>−5</sup> J.","1,2.10<sup>−5</sup> J.","1,44.10<sup>−4</sup> J."],"question":"Một tụ điện có điện dung 1 µF được tích điện ở hiệu điện thế 12 V. Năng lượng điện trường dự trữ trong tụ điện là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng điện trường dự trữ trong tụ điện được tính theo công thức: $W = \\dfrac{1}{2}CU^2$, trong đó $C$ là điện dung (F) và $U$ là hiệu điện thế (V).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 1\\ \\mu F = 1.10^{-6}\\ F$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W = \\dfrac{1}{2}\\cdot 1.10^{-6}\\cdot 12^2 = \\dfrac{1}{2}\\cdot 1.10^{-6}\\cdot 144$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W = 72.10^{-6}\\ J = 7,2.10^{-5}\\ J$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: năng lượng điện trường dự trữ trong tụ là $7,2.10^{-5}\\ J$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":830,"idx":2,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng của tụ điện","answer":1,"options":["12 J.","7,2.10<sup>−5</sup> J.","1,2.10<sup>−5</sup> J.","1,44.10<sup>−4</sup> J."],"question":"Một tụ điện có điện dung 1 µF được tích điện ở hiệu điện thế 12 V. Năng lượng điện trường dự trữ trong tụ điện là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng điện trường dự trữ trong tụ điện được tính theo công thức: $W = \\dfrac{1}{2}CU^2$, trong đó $C$ là điện dung (F) và $U$ là hiệu điện thế (V).</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $C = 1\\ \\mu F = 1.10^{-6}\\ F$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W = \\dfrac{1}{2}\\cdot 1.10^{-6}\\cdot 12^2 = \\dfrac{1}{2}\\cdot 1.10^{-6}\\cdot 144$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W = 72.10^{-6}\\ J = 7,2.10^{-5}\\ J$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: năng lượng điện trường dự trữ trong tụ là $7,2.10^{-5}\\ J$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":1187692,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"4500","question":"Cường độ điện trường gây ra bởi điện tích Q = 5.10<sup>−9</sup> C, tại một điểm trong chân không cách điện tích một khoảng 10 cm có độ lớn là bao nhiêu V/m? Cho biết  $k=9.10^9 Nm^2/C^2$ .","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm $Q$ gây ra trong chân không tại điểm cách nó khoảng $r$ là: $E = k\\dfrac{|Q|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 10\\ \\text{cm} = 0{,}1\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = 9.10^9 \\cdot \\dfrac{5.10^{-9}}{(0{,}1)^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E = \\dfrac{45}{0{,}01} = 4500\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy cường độ điện trường tại điểm đó có độ lớn là $4500\\ \\text{V/m}$.</p>","difficultySource":"ai"},"ex":[{"exam":830,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"4500","question":"Cường độ điện trường gây ra bởi điện tích Q = 5.10<sup>−9</sup> C, tại một điểm trong chân không cách điện tích một khoảng 10 cm có độ lớn là bao nhiêu V/m? Cho biết  $k=9.10^9 Nm^2/C^2$ .","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm $Q$ gây ra trong chân không tại điểm cách nó khoảng $r$ là: $E = k\\dfrac{|Q|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 10\\ \\text{cm} = 0{,}1\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = 9.10^9 \\cdot \\dfrac{5.10^{-9}}{(0{,}1)^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E = \\dfrac{45}{0{,}01} = 4500\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy cường độ điện trường tại điểm đó có độ lớn là $4500\\ \\text{V/m}$.</p>","difficultySource":"ai"}}]},{"id":1187834,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":1,"options":["8.10<sup>−6</sup> (C).","1,25.10<sup>−3</sup> (C).","12,5 (μC).","8.10<sup>−6</sup> (μ<br>C) ."],"question":"Một điện tích đặt tại điểm có cường độ điện trường 0,16 (V/m). Lực tác dụng lên điện tích đó bằng 2.10<sup>−4</sup> (N). Độ lớn điện tích đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm đặt trong điện trường được xác định bởi công thức $F = |q|E$, trong đó $F$ là độ lớn lực điện (N), $E$ là cường độ điện trường (V/m) và $q$ là điện tích (C).</p><p class=\"text-base leading-relaxed my-2\">Suy ra độ lớn điện tích: $|q| = \\dfrac{F}{E}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $|q| = \\dfrac{2\\cdot 10^{-4}}{0,16}$ (C).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow |q| = 1,25\\cdot 10^{-3}$ (C) $= 1250$ (μC).</p><p class=\"text-base leading-relaxed my-2\">So sánh với các phương án: đáp án B khớp với kết quả. Phương án C ($12,5$ μC $= 1,25\\cdot 10^{-5}$ C) sai về lũy thừa 10 và độ lớn.</p><p class=\"text-base leading-relaxed my-2\">Vậy độ lớn điện tích là $1,25\\cdot 10^{-3}$ C.</p>","difficultySource":"ai"},"ex":[{"exam":831,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":1,"options":["8.10<sup>−6</sup> (C).","1,25.10<sup>−3</sup> (C).","12,5 (μC).","8.10<sup>−6</sup> (μ<br>C) ."],"question":"Một điện tích đặt tại điểm có cường độ điện trường 0,16 (V/m). Lực tác dụng lên điện tích đó bằng 2.10<sup>−4</sup> (N). Độ lớn điện tích đó là","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1187849,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cân bằng của điện tích chịu nhiều lực","answer":"45","question":"Quả cầu nhỏ khối lượng m = 25 g, mang điện tích q = 2,5.10<sup>−7</sup> C được treo bởi một sợi dây không dãn, khối lượng không đáng kể và đặt vào trong một điện trường đều với cường độ điện trường  $\\vec{E}$  có phương nằm ngang và có độ lớn E = 106 V/m. Lấy g = 10 $m/s^2$. Góc lệch của dây treo so với phương thẳng đứng là bao nhiêu độ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Quả cầu chịu ba lực: trọng lực $\\vec{P}$ (thẳng đứng xuống), lực điện $\\vec{F}$ (nằm ngang, cùng phương với $\\vec{E}$ vì điện tích dương) và lực căng dây $\\vec{T}$. Quả cầu cân bằng nên hợp lực của ba lực bằng 0, tức $\\vec{T} = -(\\vec{P} + \\vec{F})$.</p><p class=\"text-base leading-relaxed my-2\">Lực điện: $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2{,}5.10^{-7} \\cdot 10^{6} = 0{,}25$ N.</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng: $P = mg$, với $m = 25$ g $= 0{,}025$ kg.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $P = 0{,}025 \\cdot 10 = 0{,}25$ N.</p><p class=\"text-base leading-relaxed my-2\">Dây treo lệch khỏi phương thẳng đứng một góc $\\alpha$ thoả mãn:</p><p class=\"text-base leading-relaxed my-2\">$\\tan\\alpha = \\dfrac{F}{P} = \\dfrac{qE}{mg}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\tan\\alpha = \\dfrac{0{,}25}{0{,}25} = 1$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = 45^\\circ$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: góc lệch của dây treo so với phương thẳng đứng là $45^\\circ$.</p>","difficultySource":"ai"},"ex":[{"exam":831,"idx":16,"el":{"form":"bai_tap","type":"short_answer","topic":"Cân bằng của điện tích chịu nhiều lực","answer":"45","question":"Quả cầu nhỏ khối lượng m = 25 g, mang điện tích q = 2,5.10<sup>−7</sup> C được treo bởi một sợi dây không dãn, khối lượng không đáng kể và đặt vào trong một điện trường đều với cường độ điện trường  $\\vec{E}$  có phương nằm ngang và có độ lớn E = 106 V/m. Lấy g = 10 m/s2. Góc lệch của dây treo so với phương thẳng đứng là bao nhiêu độ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Quả cầu chịu ba lực: trọng lực $\\vec{P}$ (thẳng đứng xuống), lực điện $\\vec{F}$ (nằm ngang, cùng phương với $\\vec{E}$ vì điện tích dương) và lực căng dây $\\vec{T}$. Quả cầu cân bằng nên hợp lực của ba lực bằng 0, tức $\\vec{T} = -(\\vec{P} + \\vec{F})$.</p><p class=\"text-base leading-relaxed my-2\">Lực điện: $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 2{,}5.10^{-7} \\cdot 10^{6} = 0{,}25$ N.</p><p class=\"text-base leading-relaxed my-2\">Trọng lượng: $P = mg$, với $m = 25$ g $= 0{,}025$ kg.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $P = 0{,}025 \\cdot 10 = 0{,}25$ N.</p><p class=\"text-base leading-relaxed my-2\">Dây treo lệch khỏi phương thẳng đứng một góc $\\alpha$ thoả mãn:</p><p class=\"text-base leading-relaxed my-2\">$\\tan\\alpha = \\dfrac{F}{P} = \\dfrac{qE}{mg}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\tan\\alpha = \\dfrac{0{,}25}{0{,}25} = 1$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\alpha = 45^\\circ$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: góc lệch của dây treo so với phương thẳng đứng là $45^\\circ$.</p>","difficultySource":"ai"}}]},{"id":1191946,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Chuyển động của điện tích trong điện trường đều","answer":1,"options":["20V/m.","200V/m.","300V/m.","400V/m."],"question":"Hai tấm kim loại song song, cách nhau 2cm, tích điện trái dấu. Để một điện tích q=5.10<sup>−10</sup>C di chuyển từ tấm này sang tấm kia cần tốn một công A=2.10<sup>−9</sup>J. Coi điện trường trong khoảng không gian giữa hai tấm là đều. Cường độ điện trường bên trong hai tấm kim loại bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích $q$ di chuyển giữa hai điểm trong điện trường đều: $A = qEd$, trong đó $d$ là khoảng cách giữa hai điểm theo phương đường sức.</p><p class=\"text-base leading-relaxed my-2\">Suy ra cường độ điện trường: $E = \\dfrac{A}{q\\,d}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $d = 2\\text{ cm} = 0{,}02\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = \\dfrac{2.10^{-9}}{5.10^{-10}\\cdot 0{,}02} = \\dfrac{2.10^{-9}}{1.10^{-11}} = 200\\text{ V/m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ điện trường giữa hai tấm là $200\\text{ V/m}$, đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":832,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Chuyển động của điện tích trong điện trường đều","answer":1,"options":["20V/m.","200V/m.","300V/m.","400V/m."],"question":"Hai tấm kim loại song song, cách nhau 2cm, tích điện trái dấu. Để một điện tích q=5.10<sup>−10</sup>C di chuyển từ tấm này sang tấm kia cần tốn một công A=2.10<sup>−9</sup>J. Coi điện trường trong khoảng không gian giữa hai tấm là đều. Cường độ điện trường bên trong hai tấm kim loại bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích $q$ di chuyển giữa hai điểm trong điện trường đều: $A = qEd$, trong đó $d$ là khoảng cách giữa hai điểm theo phương đường sức.</p><p class=\"text-base leading-relaxed my-2\">Suy ra cường độ điện trường: $E = \\dfrac{A}{q\\,d}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $d = 2\\text{ cm} = 0{,}02\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = \\dfrac{2.10^{-9}}{5.10^{-10}\\cdot 0{,}02} = \\dfrac{2.10^{-9}}{1.10^{-11}} = 200\\text{ V/m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ điện trường giữa hai tấm là $200\\text{ V/m}$, đáp án B.</p>","difficultySource":"ai"}}]},{"id":1192633,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"144","question":"Cường độ điện trường do một điện tích 4.10<sup>−8</sup> C gây ra tại điểm cách nó 5 cm trong chân không có dạng  $a\\times 10^3$  (V/m). Xác định  $a$ ? Biết hệ số tỉ lệ k = 9.10<sup>9</sup> Nm2/C2.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm $q$ gây ra tại điểm cách nó khoảng $r$ trong chân không:</p><p class=\"text-base leading-relaxed my-2\">$E = k\\dfrac{|q|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 5\\ \\text{cm} = 0{,}05\\ \\text{m}$, $|q| = 4\\cdot 10^{-8}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$E = 9\\cdot 10^{9}\\cdot\\dfrac{4\\cdot 10^{-8}}{(0{,}05)^2} = \\dfrac{360}{2{,}5\\cdot 10^{-3}} = 1{,}44\\cdot 10^{5}\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Viết dưới dạng $a\\times 10^3$ (V/m): $1{,}44\\cdot 10^{5} = 144\\cdot 10^{3}$, nên $a = 144$.</p>","difficultySource":"ai"},"ex":[{"exam":834,"idx":14,"el":{"form":"bai_tap","type":"short_answer","topic":"Cường độ điện trường của điện tích điểm","answer":"144","question":"Cường độ điện trường do một điện tích 4.10<sup>−8</sup> C gây ra tại điểm cách nó 5 cm trong chân không có dạng  $a\\times 10^3$  (V/m). Xác định  $a$ ? Biết hệ số tỉ lệ k = 9.10<sup>9</sup> Nm2/C2.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường do điện tích điểm $q$ gây ra tại điểm cách nó khoảng $r$ trong chân không:</p><p class=\"text-base leading-relaxed my-2\">$E = k\\dfrac{|q|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 5\\ \\text{cm} = 0{,}05\\ \\text{m}$, $|q| = 4\\cdot 10^{-8}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$E = 9\\cdot 10^{9}\\cdot\\dfrac{4\\cdot 10^{-8}}{(0{,}05)^2} = \\dfrac{360}{2{,}5\\cdot 10^{-3}} = 1{,}44\\cdot 10^{5}\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$ Viết dưới dạng $a\\times 10^3$ (V/m): $1{,}44\\cdot 10^{5} = 144\\cdot 10^{3}$, nên $a = 144$.</p>","difficultySource":"ai"}}]},{"id":1192692,"nq":{"form":"bai_tap","type":"true_false","topic":"Tụ điện và điện dung","question":"Một tụ điện khởi động cho động cơ (tụ đề) có các thông số như Hình 1. Đơn vị VAC (hay V.AC) là điện áp ứng với dòng điện xoay chiều, còn VDC (hay V.DC) là điện áp ứng với dòng điện một chiều cùng được đọc là vôn. Tụ đề thường được gọi là tụ không phân cực, nó có nhiệm vụ tăng momen khởi động cho motor trong một khoảng thời gian ngắn. Đồng thời, cho phép motor có thể dừng hoặc hoạt động 1 cách nhanh chóng. Nguyên lý hoạt động của tụ điện chính là khả năng nạp xả thông minh, ngăn được điện áp 1 chiều để cho điện áp xoay chiều lưu thông, giúp lọc điện áp xoay chiều trở thành điện áp 1 chiều, làm lệch pha cho điện áp đặt vào động cơ.<br>Nguồn Internet.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217004144-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Điện dung của tụ điện là 2200 F.","answer":false},{"text":"Để tích điện cho tụ ta mắc 2 đầu tụ vào hiệu điện thế xoay chiều tối đa 35V.","answer":true},{"text":"Nếu ghép song song 2 tụ ta thu được điện dung của bộ tụ này là 44.10<sup>−4</sup> F.","answer":true},{"text":"Điện tích tối đa mà tụ có thể tích được là 750 C","answer":false}],"explanation":"","difficultySource":"ai"},"ex":[{"exam":835,"idx":15,"el":{"form":"bai_tap","type":"true_false","topic":"Tụ điện và điện dung","question":"Một tụ điện khởi động cho động cơ (tụ đề) có các thông số như Hình 1. Đơn vị VAC (hay V.AC) là điện áp ứng với dòng điện xoay chiều, còn VDC (hay V.DC) là điện áp ứng với dòng điện một chiều cùng được đọc là vôn. Tụ đề thường được gọi là tụ không phân cực, nó có nhiệm vụ tăng momen khởi động cho motor trong một khoảng thời gian ngắn. Đồng thời, cho phép motor có thể dừng hoặc hoạt động 1 cách nhanh chóng. Nguyên lý hoạt động của tụ điện chính là khả năng nạp xả thông minh, ngăn được điện áp 1 chiều để cho điện áp xoay chiều lưu thông, giúp lọc điện áp xoay chiều trở thành điện áp 1 chiều, làm lệch pha cho điện áp đặt vào động cơ.<br>Nguồn Internet.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217004144-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Điện dung của tụ điện là 2200 F.","answer":false},{"text":"Để tích điện cho tụ ta mắc 2 đầu tụ vào hiệu điện thế xoay chiều tối đa 35V.","answer":true},{"text":"Nếu ghép song song 2 tụ ta thu được điện dung của bộ tụ này là 44.10<sup>−4</sup> F.","answer":true},{"text":"Điện tích tối đa mà tụ có thể tích được là 750 C","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1192695,"nq":{"form":"bai_tap","type":"true_false","topic":"Đường đặc trưng vôn – ampe","question":"Các thiết bị điện mà chúng ta dùng hằng ngày đều có các điện trở. Hình bên biểu diễn đường đặc trưng vôn – ampe của điện trở R1 và điện trở R2 của 2 thiết bị điện ở một nhiệt độ xác định.<br>III. PHẦN TỰ LUẬN (1,5  điểm) Học sinh giải vào giấy từ bài 1 đến bài 6.<br>Bài 1: Chọ tụ điện như hình bên, hãy cho biết ý nghĩa của cặp giá trị (3300 µF – 35 V) ghi trên tụ?<br>Bài 2: Ghép 2 tụ như hình bên biết: C1= 6. 10<sup>−6</sup>F, C2= 5. 10<sup>−6</sup>F. Tính điện dung tương đương của bộ tụ<br>Bài 3: Một máy hàn bu - lông dùng hiệu điện thế $220\\,\\text{V}$ không đổi có bộ tụ điện với điện dung C=0,09F. Năng lượng mà bộ tụ điện của máy hàn trên có thể tích được (tính theo đơn vị J) là bao nhiêu?<br>Bài 4: Trong thời gian 30 giây có một điện lượng 60 C chuyển qua tiết diện thẳng của dây dẫn. Cường độ dòng điện qua dây dẫn bằng bao nhiêu ampe?<br>Bài 5: Đồng là loại vật liệu dẫn điện phổ biến, mật độ electron tự do trong đồng là 8,5.10<sup>28</sup> m-3. Một dây dẫn bằng đồng có tiết diện 5. 10<sup>−6</sup> m2 mang dòng điện 15 A. Tốc độ trôi của electron trong dây dẫn trên là bao nhiêu? Lấy độ lớn điện tích của mỗi electron là $e = 1{,}6\\times 10^{-19}$C.<br>Bài 6: Một bóng đèn xe máy lúc thắp sáng có điện trở 12 Ω và cường độ dòng điện chạy qua dây tóc bóng đèn là 0,5 A. Hiệu điện thế giữa hai đầu dây tóc bóng đèn khi đó là bao nhiêu V?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217005172-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Từ đồ thị cho thấy  I tỉ lệ nghịch với U.","answer":false},{"text":"Đường đặc trưng Vôn-Ampe là một đoạn thẳng đi qua gốc toạ độ.","answer":true},{"text":"Điện trở R1 có giá trị nhỏ hơn R2.","answer":false},{"text":"Điện trở  R2 có giá trị là 5 Ω.","answer":true}],"explanation":"","difficultySource":"ai"},"ex":[{"exam":835,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Đường đặc trưng vôn – ampe","question":"Các thiết bị điện mà chúng ta dùng hằng ngày đều có các điện trở. Hình bên biểu diễn đường đặc trưng vôn – ampe của điện trở R1 và điện trở R2 của 2 thiết bị điện ở một nhiệt độ xác định.<br>III. PHẦN TỰ LUẬN (1,5  điểm) Học sinh giải vào giấy từ bài 1 đến bài 6.<br>Bài 1: Chọ tụ điện như hình bên, hãy cho biết ý nghĩa của cặp giá trị (3300 µF – 35 V) ghi trên tụ?<br>Bài 2: Ghép 2 tụ như hình bên biết: C1= 6. 10<sup>−6</sup>F, C2= 5. 10<sup>−6</sup>F. Tính điện dung tương đương của bộ tụ<br>Bài 3: Một máy hàn bu - lông dùng hiệu điện thế $220\\,\\text{V}$ không đổi có bộ tụ điện với điện dung C=0,09F. Năng lượng mà bộ tụ điện của máy hàn trên có thể tích được (tính theo đơn vị J) là bao nhiêu?<br>Bài 4: Trong thời gian 30 giây có một điện lượng 60 C chuyển qua tiết diện thẳng của dây dẫn. Cường độ dòng điện qua dây dẫn bằng bao nhiêu ampe?<br>Bài 5: Đồng là loại vật liệu dẫn điện phổ biến, mật độ electron tự do trong đồng là 8,5.10<sup>28</sup> m-3. Một dây dẫn bằng đồng có tiết diện 5. 10<sup>−6</sup> m2 mang dòng điện 15 A. Tốc độ trôi của electron trong dây dẫn trên là bao nhiêu? Lấy độ lớn điện tích của mỗi electron là $e = 1{,}6\\times 10^{-19}$C.<br>Bài 6: Một bóng đèn xe máy lúc thắp sáng có điện trở 12 Ω và cường độ dòng điện chạy qua dây tóc bóng đèn là 0,5 A. Hiệu điện thế giữa hai đầu dây tóc bóng đèn khi đó là bao nhiêu V?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217005172-hinh-7.jpg\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Từ đồ thị cho thấy  I tỉ lệ nghịch với U.","answer":false},{"text":"Đường đặc trưng Vôn-Ampe là một đoạn thẳng đi qua gốc toạ độ.","answer":true},{"text":"Điện trở R1 có giá trị nhỏ hơn R2.","answer":false},{"text":"Điện trở  R2 có giá trị là 5 Ω.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1192899,"nq":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Hai bản kim loại phẳng rộng giống nhau, đặt song song đối diện cách nhau 5 mm, chúng được tích điện có độ lớn bằng nhau nhưng trái dấu, hiệu điện thế giữa hai bản là 25 V. Xét một electron chuyển động từ bản kim loại tích điện âm về bản kim loại tích điện dương với vận tốc đầu bằng không. Biết electron có điện tích -1,6.10<sup>−19</sup>C và khối lượng 9,1.10<sup>−31</sup> kg.","difficulty":"trung-binh","statements":[{"text":"Đường sức điện của điện trường giữa hai bản có chiều từ bản âm tới bản dương.","answer":false},{"text":"Lực điện tác dụng lên electron có độ lớn 8.10<sup>−19</sup> N.","answer":false},{"text":"Khi bay đến bản dương, tốc độ của electron đạt được là 2,96.10<sup>6</sup> m/s.","answer":true},{"text":"Điện trường giữa hai bản kim loại là điện trường đều.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Cường độ điện trường giữa hai bản:</strong></p><p class=\"text-base leading-relaxed my-2\">Công thức: $E = \\dfrac{U}{d}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = \\dfrac{25}{5.10^{-3}} = 5000\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý a) Sai.</strong> Đường sức điện luôn đi từ bản dương sang bản âm, tức là từ bản tích điện dương tới bản tích điện âm. Chiều được nêu trong đề là ngược lại.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý b) Sai.</strong></p><p class=\"text-base leading-relaxed my-2\">Lực điện: $F = |q|E$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 1{,}6.10^{-19}\\cdot 5000 = 8.10^{-16}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Giá trị $8.10^{-19}$ N trong đề là sai.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý c) Đúng.</strong></p><p class=\"text-base leading-relaxed my-2\">Định lí động năng: công của lực điện bằng độ biến thiên động năng. Electron xuất phát từ trạng thái nghỉ nên:</p><p class=\"text-base leading-relaxed my-2\">$|q|U = \\dfrac{1}{2}mv^2 - 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\sqrt{\\dfrac{2|q|U}{m}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\sqrt{\\dfrac{2\\cdot 1{,}6.10^{-19}\\cdot 25}{9{,}1.10^{-31}}} \\approx 2{,}96.10^{6}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý d) Đúng.</strong> Hai bản kim loại phẳng, rộng, đặt song song và tích điện trái dấu, bằng nhau về độ lớn, tạo ra điện trường đều ở khoảng giữa hai bản (bỏ qua hiệu ứng rìa).</p>","difficultySource":"ai"},"ex":[{"exam":836,"idx":14,"el":{"form":"bai_tap","type":"true_false","topic":"Chuyển động của điện tích trong điện trường đều","question":"Hai bản kim loại phẳng rộng giống nhau, đặt song song đối diện cách nhau 5 mm, chúng được tích điện có độ lớn bằng nhau nhưng trái dấu, hiệu điện thế giữa hai bản là 25 V. Xét một electron chuyển động từ bản kim loại tích điện âm về bản kim loại tích điện dương với vận tốc đầu bằng không. Biết electron có điện tích -1,6.10<sup>−19</sup>C và khối lượng 9,1.10<sup>−31</sup> kg.","difficulty":"trung-binh","statements":[{"text":"Đường sức điện của điện trường giữa hai bản có chiều từ bản âm tới bản dương.","answer":false},{"text":"Lực điện tác dụng lên electron có độ lớn 8.10<sup>−19</sup> N.","answer":false},{"text":"Khi bay đến bản dương, tốc độ của electron đạt được là 2,96.10<sup>6</sup> m/s.","answer":true},{"text":"Điện trường giữa hai bản kim loại là điện trường đều.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Cường độ điện trường giữa hai bản:</strong></p><p class=\"text-base leading-relaxed my-2\">Công thức: $E = \\dfrac{U}{d}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $E = \\dfrac{25}{5.10^{-3}} = 5000\\ \\text{V/m}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý a) Sai.</strong> Đường sức điện luôn đi từ bản dương sang bản âm, tức là từ bản tích điện dương tới bản tích điện âm. Chiều được nêu trong đề là ngược lại.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý b) Sai.</strong></p><p class=\"text-base leading-relaxed my-2\">Lực điện: $F = |q|E$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 1{,}6.10^{-19}\\cdot 5000 = 8.10^{-16}\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Giá trị $8.10^{-19}$ N trong đề là sai.</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý c) Đúng.</strong></p><p class=\"text-base leading-relaxed my-2\">Định lí động năng: công của lực điện bằng độ biến thiên động năng. Electron xuất phát từ trạng thái nghỉ nên:</p><p class=\"text-base leading-relaxed my-2\">$|q|U = \\dfrac{1}{2}mv^2 - 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\sqrt{\\dfrac{2|q|U}{m}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\sqrt{\\dfrac{2\\cdot 1{,}6.10^{-19}\\cdot 25}{9{,}1.10^{-31}}} \\approx 2{,}96.10^{6}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Ý d) Đúng.</strong> Hai bản kim loại phẳng, rộng, đặt song song và tích điện trái dấu, bằng nhau về độ lớn, tạo ra điện trường đều ở khoảng giữa hai bản (bỏ qua hiệu ứng rìa).</p>","difficultySource":"ai"}}]},{"id":1192900,"nq":{"form":"bai_tap","type":"true_false","topic":"Tụ điện và điện dung","question":"Cho tụ điện có các thông số như hình ảnh bên dưới. Biết electron có điện tích -1,6.10<sup>−19</sup>C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217010078-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Nếu đặt hiệu điện thế 15 V vào hai bản tụ thì có 9,375.10<sup>17</sup> electron di chuyển đến bản âm của tụ.","answer":true},{"text":"Với hiệu điện thế giữa hai bản từ 25 V trở xuống thì tụ hoạt động ổn định.","answer":true},{"text":"Điện dung của tụ điện này bằng 10-2 F.","answer":true},{"text":"Khi đặt hiệu điện thế 25 V vào hai bản tụ thì sẽ có dòng điện không đổi chạy qua tụ.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">Tụ ghi $10000\\ \\mu\\text{F}-25\\ \\text{V}$: điện dung $C=10^{-2}\\ \\text{F}$, hiệu điện thế tối đa $25\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">a) Đúng. Ở $U=15\\ \\text{V}$: $Q=CU=10^{-2}\\cdot15=0{,}15\\ \\text{C}$; số electron $N=\\dfrac{Q}{|e|}=\\dfrac{0{,}15}{1{,}6\\cdot10^{-19}}=9{,}375\\cdot10^{17}$ hạt.</p><p class=\"text-base leading-relaxed my-2\">b) Đúng. $25\\ \\text{V}$ là giới hạn nên $U\\le25\\ \\text{V}$ tụ hoạt động ổn định.</p><p class=\"text-base leading-relaxed my-2\">c) Đúng. $C=10000\\ \\mu\\text{F}=10^{-2}\\ \\text{F}$.</p><p class=\"text-base leading-relaxed my-2\">d) Sai. Tụ điện không cho dòng điện một chiều không đổi chạy qua (chỉ có dòng nạp thoáng qua rồi dừng).</p>","difficultySource":"ai"},"ex":[{"exam":836,"idx":15,"el":{"form":"bai_tap","type":"true_false","topic":"Tụ điện và điện dung","question":"Cho tụ điện có các thông số như hình ảnh bên dưới. Biết electron có điện tích -1,6.10<sup>−19</sup>C.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217010078-hinh-4.png\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","statements":[{"text":"Nếu đặt hiệu điện thế 15 V vào hai bản tụ thì có 9,375.10<sup>17</sup> electron di chuyển đến bản âm của tụ.","answer":true},{"text":"Với hiệu điện thế giữa hai bản từ 25 V trở xuống thì tụ hoạt động ổn định.","answer":true},{"text":"Điện dung của tụ điện này bằng 10-2 F.","answer":true},{"text":"Khi đặt hiệu điện thế 25 V vào hai bản tụ thì sẽ có dòng điện không đổi chạy qua tụ.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1192902,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"9,8","question":"Một đoạn dây dẫn kim loại có tiết diện đều 3,0 mm2 có dòng điện không đổi chạy qua, cứ mỗi phút có điện lượng 240 C dịch chuyển qua tiết diện thẳng của dây. Mật độ electron tự do trong dây dẫn là 8,5.10<sup>28</sup> electron/m3. Biết electron có điện tích -1,6.10<sup>−19</sup>C. Tốc độ dịch chuyển có hướng (tốc độ trôi) của electron trong dây dẫn này là x.10<sup>−5</sup> m/s. Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện không đổi được xác định bởi điện lượng dịch chuyển qua tiết diện thẳng trong thời gian $t$:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{q}{t}$</p><p class=\"text-base leading-relaxed my-2\">Thay số, với $q = 240\\ \\text{C}$ và $t = 1\\ \\text{phút} = 60\\ \\text{s}$:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{240}{60} = 4\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">Với dòng điện trong dây dẫn kim loại, cường độ dòng điện liên hệ với tốc độ trôi $v$ của electron theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$I = n\\,e\\,S\\,v$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\dfrac{I}{n\\,e\\,S}$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $n = 8{,}5\\cdot10^{28}\\ \\text{electron/m}^3$, $e = 1{,}6\\cdot10^{-19}\\ \\text{C}$, $S = 3{,}0\\ \\text{mm}^2 = 3{,}0\\cdot10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$v = \\dfrac{4}{8{,}5\\cdot10^{28}\\cdot1{,}6\\cdot10^{-19}\\cdot3{,}0\\cdot10^{-6}} = \\dfrac{4}{4{,}08\\cdot10^{4}} \\approx 9{,}8\\cdot10^{-5}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x = 9{,}8$.</p>","difficultySource":"ai"},"ex":[{"exam":836,"idx":17,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"9,8","question":"Một đoạn dây dẫn kim loại có tiết diện đều 3,0 mm2 có dòng điện không đổi chạy qua, cứ mỗi phút có điện lượng 240 C dịch chuyển qua tiết diện thẳng của dây. Mật độ electron tự do trong dây dẫn là 8,5.10<sup>28</sup> electron/m3. Biết electron có điện tích -1,6.10<sup>−19</sup>C. Tốc độ dịch chuyển có hướng (tốc độ trôi) của electron trong dây dẫn này là x.10<sup>−5</sup> m/s. Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số hàng phần mười)?","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện không đổi được xác định bởi điện lượng dịch chuyển qua tiết diện thẳng trong thời gian $t$:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{q}{t}$</p><p class=\"text-base leading-relaxed my-2\">Thay số, với $q = 240\\ \\text{C}$ và $t = 1\\ \\text{phút} = 60\\ \\text{s}$:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{240}{60} = 4\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">Với dòng điện trong dây dẫn kim loại, cường độ dòng điện liên hệ với tốc độ trôi $v$ của electron theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$I = n\\,e\\,S\\,v$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\dfrac{I}{n\\,e\\,S}$</p><p class=\"text-base leading-relaxed my-2\">Trong đó $n = 8{,}5\\cdot10^{28}\\ \\text{electron/m}^3$, $e = 1{,}6\\cdot10^{-19}\\ \\text{C}$, $S = 3{,}0\\ \\text{mm}^2 = 3{,}0\\cdot10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$v = \\dfrac{4}{8{,}5\\cdot10^{28}\\cdot1{,}6\\cdot10^{-19}\\cdot3{,}0\\cdot10^{-6}} = \\dfrac{4}{4{,}08\\cdot10^{4}} \\approx 9{,}8\\cdot10^{-5}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x = 9{,}8$.</p>","difficultySource":"ai"}}]},{"id":1192904,"nq":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động và điện trở trong của nguồn","answer":"3","question":"Lực lạ thực hiện một công là 0,15 J làm dịch chuyển một lượng điện tích 5.10<sup>−2</sup> C giữa hai cực bên trong nguồn điện. Suất điện động của nguồn điện này là bao nhiêu vôn?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Suất điện động của nguồn: $\\xi=\\dfrac{A}{q}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\xi=\\dfrac{0,15}{5.10^{-2}}=3\\ V$.</p><p class=\"text-base leading-relaxed my-2\">Đáp số: $3$ V.</p>","difficultySource":"ai"},"ex":[{"exam":836,"idx":19,"el":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động và điện trở trong của nguồn","answer":"3","question":"Lực lạ thực hiện một công là 0,15 J làm dịch chuyển một lượng điện tích 5.10<sup>−2</sup> C giữa hai cực bên trong nguồn điện. Suất điện động của nguồn điện này là bao nhiêu vôn?","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1192905,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện trở. Định luật Ohm","answer":"1,02","question":"Một đoạn dây dẫn bằng đồng có chiều dài 40 m, tiết diện 2 mm2, điện trở suất 1,7.10<sup>−8</sup> Ωm. Nếu dòng điện chạy qua dây có cường độ 3 A thì độ chênh lệch điện thế ở hai đầu dây là bao nhiêu vôn (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trở của đoạn dây dẫn được tính theo công thức $R = \\rho \\dfrac{l}{S}$, trong đó $\\rho$ là điện trở suất, $l$ là chiều dài và $S$ là tiết diện dây.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $S = 2\\ \\text{mm}^2 = 2 \\cdot 10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $R = 1{,}7 \\cdot 10^{-8} \\cdot \\dfrac{40}{2 \\cdot 10^{-6}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow R = 0{,}34\\ \\Omega$</p><p class=\"text-base leading-relaxed my-2\">Theo định luật Ôm cho đoạn mạch, độ chênh lệch điện thế giữa hai đầu dây là $U = I \\cdot R$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $U = 3 \\cdot 0{,}34$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U = 1{,}02\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Độ chênh lệch điện thế ở hai đầu dây là $1{,}02$ V.</p>","difficultySource":"ai"},"ex":[{"exam":836,"idx":20,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện trở. Định luật Ohm","answer":"1,02","question":"Một đoạn dây dẫn bằng đồng có chiều dài 40 m, tiết diện 2 mm2, điện trở suất 1,7.10<sup>−8</sup> Ωm. Nếu dòng điện chạy qua dây có cường độ 3 A thì độ chênh lệch điện thế ở hai đầu dây là bao nhiêu vôn (làm tròn kết quả đến chữ số hàng phần trăm)?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trở của đoạn dây dẫn được tính theo công thức $R = \\rho \\dfrac{l}{S}$, trong đó $\\rho$ là điện trở suất, $l$ là chiều dài và $S$ là tiết diện dây.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $S = 2\\ \\text{mm}^2 = 2 \\cdot 10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $R = 1{,}7 \\cdot 10^{-8} \\cdot \\dfrac{40}{2 \\cdot 10^{-6}}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow R = 0{,}34\\ \\Omega$</p><p class=\"text-base leading-relaxed my-2\">Theo định luật Ôm cho đoạn mạch, độ chênh lệch điện thế giữa hai đầu dây là $U = I \\cdot R$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $U = 3 \\cdot 0{,}34$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U = 1{,}02\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Độ chênh lệch điện thế ở hai đầu dây là $1{,}02$ V.</p>","difficultySource":"ai"}}]},{"id":1193587,"nq":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Một điện tích điểm Q = -8.10<sup>−10</sup> C đặt trong chân không. Điểm A cách Q một khoảng<br>20 cm","difficulty":"trung-binh","statements":[{"text":"Điện trường xung quanh điện tích Q là điện trường đều","answer":false},{"text":"Vectơ cường độ điện trường tại A có chiều hướng lại gần điện tích Q.","answer":true},{"text":"Cường độ điện trường tại A là 1,8 V/m.","answer":false},{"text":"Lực điện tác dụng lên điện tích q = 2.10<sup>−9</sup> C tại A là 36.10<sup>−5</sup> N","answer":false}],"explanation":"","difficultySource":"ai"},"ex":[{"exam":837,"idx":12,"el":{"form":"bai_tap","type":"true_false","topic":"Cường độ điện trường của điện tích điểm","question":"Một điện tích điểm Q = -8.10<sup>−10</sup> C đặt trong chân không. Điểm A cách Q một khoảng<br>20 cm","difficulty":"trung-binh","statements":[{"text":"Điện trường xung quanh điện tích Q là điện trường đều","answer":false},{"text":"Vectơ cường độ điện trường tại A có chiều hướng lại gần điện tích Q.","answer":true},{"text":"Cường độ điện trường tại A là 1,8 V/m.","answer":false},{"text":"Lực điện tác dụng lên điện tích q = 2.10<sup>−9</sup> C tại A là 36.10<sup>−5</sup> N","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1193588,"nq":{"form":"bai_tap","type":"true_false","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","question":"Một dây dẫn bằng đồng có dòng điện 4 A chạy qua. Biết rằng các điện tích dịch chuyển có hướng tạo nên dòng điện này là các electron.","difficulty":"trung-binh","statements":[{"text":"Cường độ dòng điện là đại lượng đặc trưng cho tác dụng mạnh hay yếu của dòng điện.","answer":true},{"text":"Cường độ dòng điện chay qua dây dẫn có biểu thức I = nSve. Trong đó S là độ dịch chuyển của electron.","answer":false},{"text":"Điện lượng dịch chuyển qua một tiết diện thẳng của dây dẫn trong 2 phút bằng 8 C","answer":false},{"text":"Số electron đã chuyển qua tiết diện thẳng của dây dẫn trong 2 phút bằng 3.10<sup>21</sup> electron","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>a) Đúng.</b> Cường độ dòng điện đặc trưng cho tác dụng mạnh hay yếu của dòng điện, được xác định bằng điện lượng chuyển qua tiết diện thẳng của dây dẫn trong một đơn vị thời gian: $I=\\dfrac{q}{t}$.</p><p class=\"text-base leading-relaxed my-2\"><b>b) Sai.</b> Biểu thức $I = nSve$ đúng, nhưng trong đó $S$ là tiết diện thẳng của dây dẫn (diện tích), $v$ là tốc độ trôi của electron, $n$ là mật độ electron tự do và $e$ là điện tích nguyên tố. $S$ không phải là độ dịch chuyển của electron.</p><p class=\"text-base leading-relaxed my-2\"><b>c) Sai.</b> Đổi $t = 2\\text{ phút} = 120\\text{ s}$.</p><p class=\"text-base leading-relaxed my-2\">Điện lượng: $q = It = 4\\cdot 120 = 480\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Giá trị $8\\ \\text{C}$ là sai.</p><p class=\"text-base leading-relaxed my-2\"><b>d) Đúng.</b> Số electron chuyển qua tiết diện thẳng:</p><p class=\"text-base leading-relaxed my-2\">$N = \\dfrac{q}{e} = \\dfrac{480}{1{,}6\\cdot 10^{-19}} = 3\\cdot 10^{21}\\ \\text{electron}$.</p>","difficultySource":"ai"},"ex":[{"exam":837,"idx":13,"el":{"form":"bai_tap","type":"true_false","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","question":"Một dây dẫn bằng đồng có dòng điện 4 A chạy qua. Biết rằng các điện tích dịch chuyển có hướng tạo nên dòng điện này là các electron.","difficulty":"trung-binh","statements":[{"text":"Cường độ dòng điện là đại lượng đặc trưng cho tác dụng mạnh hay yếu của dòng điện.","answer":true},{"text":"Cường độ dòng điện chay qua dây dẫn có biểu thức I = nSve. Trong đó S là độ dịch chuyển của electron.","answer":false},{"text":"Điện lượng dịch chuyển qua một tiết diện thẳng của dây dẫn trong 2 phút bằng 8 C","answer":false},{"text":"Số electron đã chuyển qua tiết diện thẳng của dây dẫn trong 2 phút bằng 3.10<sup>21</sup> electron","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>a) Đúng.</b> Cường độ dòng điện đặc trưng cho tác dụng mạnh hay yếu của dòng điện, được xác định bằng điện lượng chuyển qua tiết diện thẳng của dây dẫn trong một đơn vị thời gian: $I=\\dfrac{q}{t}$.</p><p class=\"text-base leading-relaxed my-2\"><b>b) Sai.</b> Biểu thức $I = nSve$ đúng, nhưng trong đó $S$ là tiết diện thẳng của dây dẫn (diện tích), $v$ là tốc độ trôi của electron, $n$ là mật độ electron tự do và $e$ là điện tích nguyên tố. $S$ không phải là độ dịch chuyển của electron.</p><p class=\"text-base leading-relaxed my-2\"><b>c) Sai.</b> Đổi $t = 2\\text{ phút} = 120\\text{ s}$.</p><p class=\"text-base leading-relaxed my-2\">Điện lượng: $q = It = 4\\cdot 120 = 480\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Giá trị $8\\ \\text{C}$ là sai.</p><p class=\"text-base leading-relaxed my-2\"><b>d) Đúng.</b> Số electron chuyển qua tiết diện thẳng:</p><p class=\"text-base leading-relaxed my-2\">$N = \\dfrac{q}{e} = \\dfrac{480}{1{,}6\\cdot 10^{-19}} = 3\\cdot 10^{21}\\ \\text{electron}$.</p>","difficultySource":"ai"}}]},{"id":1193590,"nq":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm điện trường. Cường độ điện trường","answer":"3","question":"Một điện tích điểm q =10-7 C đặt trong điện trường của điện tích điểm Q, chịu tác dụng của lực F=3.10<sup>−3</sup> N. Tính cường độ điện trường E tại điểm đặt điện tích q. ( tính theo 104 V/m)","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ điện trường tại điểm đặt $q$: $E=\\dfrac{F}{q}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E=\\dfrac{3.10^{-3}}{10^{-7}}=3.10^4\\ V/m$.</p><p class=\"text-base leading-relaxed my-2\">Tính theo đơn vị $10^4$ V/m thì $E=3$.</p>","difficultySource":"ai"},"ex":[{"exam":837,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm điện trường. Cường độ điện trường","answer":"3","question":"Một điện tích điểm q =10-7 C đặt trong điện trường của điện tích điểm Q, chịu tác dụng của lực F=3.10<sup>−3</sup> N. Tính cường độ điện trường E tại điểm đặt điện tích q. ( tính theo 104 V/m)","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1193594,"nq":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm điện trường. Cường độ điện trường","answer":"0,02","question":"Một điện tích q = 5.10<sup>−8</sup> C đặt tại điểm M. Cường độ điện trường tại M có độ lớn<br>4.10<sup>5</sup> V/m. Lực điện tác dụng lên điện tích q có độ lớn bao nhiêu newton (N)","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm $q$ đặt trong điện trường $\\vec{E}$ có độ lớn được xác định theo công thức: $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $q = 5.10^{-8}\\ \\text{C}$ và $E = 4.10^{5}\\ \\text{V/m}$:</p><p class=\"text-base leading-relaxed my-2\">$F = 5.10^{-8} \\cdot 4.10^{5} = 20.10^{-3}\\ \\text{N} = 0{,}02\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vậy lực điện tác dụng lên điện tích có độ lớn $0{,}02\\ \\text{N}$.</p>","difficultySource":"ai"},"ex":[{"exam":837,"idx":19,"el":{"form":"bai_tap","type":"short_answer","topic":"Khái niệm điện trường. Cường độ điện trường","answer":"0,02","question":"Một điện tích q = 5.10<sup>−8</sup> C đặt tại điểm M. Cường độ điện trường tại M có độ lớn<br>4.10<sup>5</sup> V/m. Lực điện tác dụng lên điện tích q có độ lớn bao nhiêu newton (N)","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích điểm $q$ đặt trong điện trường $\\vec{E}$ có độ lớn được xác định theo công thức: $F = |q|E$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $q = 5.10^{-8}\\ \\text{C}$ và $E = 4.10^{5}\\ \\text{V/m}$:</p><p class=\"text-base leading-relaxed my-2\">$F = 5.10^{-8} \\cdot 4.10^{5} = 20.10^{-3}\\ \\text{N} = 0{,}02\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vậy lực điện tác dụng lên điện tích có độ lớn $0{,}02\\ \\text{N}$.</p>","difficultySource":"ai"}}]},{"id":1193641,"nq":{"form":"bai_tap","type":"true_false","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","question":"Một dây kim loại có các electron tự do chạy qua và tạo thành một dòng điện không đổi. Dây có tiết diện ngang S = 0,6mm2, trong thời gian 10s có điện lượng q = 9,6C di qua. Cho mật độ electron tự do là n = 4.10<sup>28</sup> hạt/m3.<br>Ý\tLỜI GIẢI\tKẾT LUẬN<br>a\tCường độ dòng điện qua dây dẫn là 0,96 A\tĐ<br>b\tMật độ dòng điện qua dây dẫn là 1,6.10<sup>6</sup> (A/m2).\tS<br>c\tSố electron đi qua tiết diện ngang của dây dẫn trong 10s là 6.10<sup>19</sup> hạt\tS<br>d\tTốc độ trung bình của các hạt tạo nên dòng điện là 0,25 mm/s.\tĐ<br>Câu 3<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217033392-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Cho các dụng cụ sau: nguồn điện có suất điện động 6 V và điện trở trong 1 , biến trở R, một bóng đèn ghi 3V – 3W, dây nối có điện trở không đáng kể, hai đồng hồ đo điện đa năng hiện số dùng làm ampe kế và vôn kế.<br>Ý\tLỜI GIẢI\tKẾT LUẬN<br>a\tĐồng hồ đo điện đa năng dùng làm vôn kế phải để ở thang đo phù hợp trong vùng có ký hiệu “V~”.\tS<br>b\tĐể đo cường độ dòng điện chạy qua bóng đèn và hiệu điện thế ở hai đầu bóng đèn thì phải mắc mạch điện như hình vẽ.\tĐ<br>c\tKhi biến trở R có giá trị 2  thì đèn sáng bình thường.\tĐ<br>d\tKhi biến trở R có giá trị 4  thì công suất tỏa nhiệt trên biến trở cực đại và đèn sáng yếu hơn bình thường.\tĐ","difficulty":"kho","statements":[{"text":"Cường độ dòng điện qua dây dẫn là 0,96 A.","answer":true},{"text":"Mật độ dòng điện qua dây dẫn là 1,6.10<sup>5</sup> (A/m2).","answer":false},{"text":"Số electron đi qua tiết diện ngang của dây dẫn trong 10s là 6.10<sup>20</sup> hạt.","answer":false},{"text":"Tốc độ trung bình của các hạt tạo nên dòng điện là 0,25 mm/s.","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Đúng. $I=\\dfrac qt=\\dfrac{9{,}6}{10}=0{,}96\\ \\text{A}$.</p><p class=\"text-base leading-relaxed my-2\">b) Sai. $J=\\dfrac IS=\\dfrac{0{,}96}{0{,}6\\cdot10^{-6}}=1{,}6\\cdot10^{6}\\ \\text{A/m}^2$, khác $1{,}6\\cdot10^{5}$.</p><p class=\"text-base leading-relaxed my-2\">c) Sai. $N=\\dfrac{q}{|e|}=\\dfrac{9{,}6}{1{,}6\\cdot10^{-19}}=6\\cdot10^{19}$ hạt, khác $6\\cdot10^{20}$.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng. $v=\\dfrac{I}{nSe}=\\dfrac{0{,}96}{4\\cdot10^{28}\\cdot0{,}6\\cdot10^{-6}\\cdot1{,}6\\cdot10^{-19}}=2{,}5\\cdot10^{-4}\\ \\text{m/s}=0{,}25\\ \\text{mm/s}$.</p>","difficultySource":"ai"},"ex":[{"exam":838,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","question":"Một dây kim loại có các electron tự do chạy qua và tạo thành một dòng điện không đổi. Dây có tiết diện ngang S = 0,6mm2, trong thời gian 10s có điện lượng q = 9,6C di qua. Cho mật độ electron tự do là n = 4.10<sup>28</sup> hạt/m3.<br>Ý\tLỜI GIẢI\tKẾT LUẬN<br>a\tCường độ dòng điện qua dây dẫn là 0,96 A\tĐ<br>b\tMật độ dòng điện qua dây dẫn là 1,6.10<sup>6</sup> (A/m2).\tS<br>c\tSố electron đi qua tiết diện ngang của dây dẫn trong 10s là 6.10<sup>19</sup> hạt\tS<br>d\tTốc độ trung bình của các hạt tạo nên dòng điện là 0,25 mm/s.\tĐ<br>Câu 3<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217033392-hinh-3.png\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" />Cho các dụng cụ sau: nguồn điện có suất điện động 6 V và điện trở trong 1 , biến trở R, một bóng đèn ghi 3V – 3W, dây nối có điện trở không đáng kể, hai đồng hồ đo điện đa năng hiện số dùng làm ampe kế và vôn kế.<br>Ý\tLỜI GIẢI\tKẾT LUẬN<br>a\tĐồng hồ đo điện đa năng dùng làm vôn kế phải để ở thang đo phù hợp trong vùng có ký hiệu “V~”.\tS<br>b\tĐể đo cường độ dòng điện chạy qua bóng đèn và hiệu điện thế ở hai đầu bóng đèn thì phải mắc mạch điện như hình vẽ.\tĐ<br>c\tKhi biến trở R có giá trị 2  thì đèn sáng bình thường.\tĐ<br>d\tKhi biến trở R có giá trị 4  thì công suất tỏa nhiệt trên biến trở cực đại và đèn sáng yếu hơn bình thường.\tĐ","difficulty":"kho","statements":[{"text":"Cường độ dòng điện qua dây dẫn là 0,96 A.","answer":true},{"text":"Mật độ dòng điện qua dây dẫn là 1,6.10<sup>5</sup> (A/m2).","answer":false},{"text":"Số electron đi qua tiết diện ngang của dây dẫn trong 10s là 6.10<sup>20</sup> hạt.","answer":false},{"text":"Tốc độ trung bình của các hạt tạo nên dòng điện là 0,25 mm/s.","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1194573,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":2,"options":["0,15 µC.","4,4 µC.","0,2 µC.","0,1 µC."],"question":"Hai điện tích điểm mang điện tích có độ lớn bằng nhau được đặt cách nhau 20 cm trong chân không thì tác dụng lên nhau một lực có độ lớn là 9.10<sup>−3</sup> N. Độ lớn điện tích của hai quả cầu đó là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai điện tích điểm đặt trong chân không, lực tương tác tuân theo định luật Coulomb: $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Hai điện tích có độ lớn bằng nhau, $|q_1| = |q_2| = q$, nên: $F = k\\dfrac{q^2}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $q = r\\sqrt{\\dfrac{F}{k}}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 20\\ \\text{cm} = 0{,}2\\ \\text{m}$, $F = 9.10^{-3}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $q = 0{,}2\\sqrt{\\dfrac{9.10^{-3}}{9.10^{9}}} = 0{,}2\\sqrt{10^{-12}} = 0{,}2.10^{-6}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $q = 2.10^{-7}\\ \\text{C} = 0{,}2\\ \\mu\\text{C}$. Đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":839,"idx":3,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":2,"options":["0,15 µC.","4,4 µC.","0,2 µC.","0,1 µC."],"question":"Hai điện tích điểm mang điện tích có độ lớn bằng nhau được đặt cách nhau 20 cm trong chân không thì tác dụng lên nhau một lực có độ lớn là 9.10<sup>−3</sup> N. Độ lớn điện tích của hai quả cầu đó là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Hai điện tích điểm đặt trong chân không, lực tương tác tuân theo định luật Coulomb: $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^9\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Hai điện tích có độ lớn bằng nhau, $|q_1| = |q_2| = q$, nên: $F = k\\dfrac{q^2}{r^2}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $q = r\\sqrt{\\dfrac{F}{k}}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $r = 20\\ \\text{cm} = 0{,}2\\ \\text{m}$, $F = 9.10^{-3}\\ \\text{N}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $q = 0{,}2\\sqrt{\\dfrac{9.10^{-3}}{9.10^{9}}} = 0{,}2\\sqrt{10^{-12}} = 0{,}2.10^{-6}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: $q = 2.10^{-7}\\ \\text{C} = 0{,}2\\ \\mu\\text{C}$. Đáp án C.</p>","difficultySource":"ai"}}]},{"id":1194581,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":3,"options":["6,53.10<sup>−6</sup> J.","- 6,53.10<sup>−6</sup> J.","8,49.10<sup>−6</sup> J.","- 8,49.10<sup>−6</sup> J."],"question":"Một điện tích điểm q = -3.10<sup>−8</sup> C chuyển động trong điện trường đều từ điểm M đến điểm N. Cho biết cường độ điện trường E = 4000 V/m, MN = 10 cm và hướng dịch chuyển hợp với hướng đường sức điện một góc 450. Công của lực điện có giá trị bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217058860-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />PHẦN II. Câu trắc nghiệm đúng sai. Thí sinh trả lời từ câu 1 đến câu 2. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện trong điện trường đều: $A = qEd$, với $d = MN\\cos\\alpha$ là hình chiếu độ dời lên phương đường sức.</p><p class=\"text-base leading-relaxed my-2\">$d = 0{,}1\\cdot\\cos 45^\\circ \\approx 0{,}0707\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A = (-3\\cdot 10^{-8})\\cdot 4000\\cdot 0{,}0707 \\approx -8{,}49\\cdot 10^{-6}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Điện tích âm đi theo hướng có thành phần cùng chiều đường sức nên công âm. Chọn <b>D</b>; A, B dùng sai góc, C sai dấu.</p>","difficultySource":"ai"},"ex":[{"exam":839,"idx":11,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":3,"options":["6,53.10<sup>−6</sup> J.","- 6,53.10<sup>−6</sup> J.","8,49.10<sup>−6</sup> J.","- 8,49.10<sup>−6</sup> J."],"question":"Một điện tích điểm q = -3.10<sup>−8</sup> C chuyển động trong điện trường đều từ điểm M đến điểm N. Cho biết cường độ điện trường E = 4000 V/m, MN = 10 cm và hướng dịch chuyển hợp với hướng đường sức điện một góc 450. Công của lực điện có giá trị bằng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791217058860-hinh-6.jpg\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />PHẦN II. Câu trắc nghiệm đúng sai. Thí sinh trả lời từ câu 1 đến câu 2. Trong mỗi ý a), b), c), d) ở mỗi câu, thí sinh chọn đúng hoặc sai.","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1194584,"nq":{"form":"bai_tap","type":"short_answer","topic":"Chuyển động của điện tích trong điện trường đều","answer":"14,2","question":"Một electron bay dọc theo đường sức của một điện trường đều với tốc độ ban đầu là 106 m/s. Sau khi đi được quãng đường 20 cm thì dừng lại. Cho biết electron có điện tích là -1,6.10<sup>−19</sup> C, khối lượng me = 9,1.10<sup>−31</sup> kg. Tính độ lớn cường độ điện trường của điện trường đều này ra đơn vị Vôn/mét (V/m)? Kết quả làm tròn đến chữ số phần mười.","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Electron dừng lại do lực điện sinh công cản. Định lí động năng: $0 - \\dfrac{1}{2}m v_0^2 = -|e|Es$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E = \\dfrac{m v_0^2}{2|e|s} = \\dfrac{9{,}1\\cdot 10^{-31}\\cdot (10^{6})^2}{2\\cdot 1{,}6\\cdot 10^{-19}\\cdot 0{,}2}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E \\approx 14{,}22\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">Làm tròn đến phần mười: <b>14,2</b> V/m.</p>","difficultySource":"ai"},"ex":[{"exam":839,"idx":14,"el":{"form":"bai_tap","type":"short_answer","topic":"Chuyển động của điện tích trong điện trường đều","answer":"14,2","question":"Một electron bay dọc theo đường sức của một điện trường đều với tốc độ ban đầu là 106 m/s. Sau khi đi được quãng đường 20 cm thì dừng lại. Cho biết electron có điện tích là -1,6.10<sup>−19</sup> C, khối lượng me = 9,1.10<sup>−31</sup> kg. Tính độ lớn cường độ điện trường của điện trường đều này ra đơn vị Vôn/mét (V/m)? Kết quả làm tròn đến chữ số phần mười.","difficulty":"kho","explanation":"","difficultySource":"ai"}}]},{"id":1194585,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"1,25","question":"Một dây dẫn hình trụ có diện tích tiết diện S = 10 mm2 có dòng điện cường độ 2 A chạy qua. Hạt mang điện tự do trong dây dẫn là electron có độ lớn điện tích là 1,6.10<sup>−19</sup> C. Biết tốc độ trung bình của electron trong chuyển động có hướng là 0,1 mm/s, mật độ hạt electron trong dây dẫn là X.10<sup>28</sup> hạt/m3. Tính X.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện trong dây dẫn liên hệ với mật độ hạt mang điện tự do, điện tích hạt, tốc độ trung bình có hướng và tiết diện dây theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$I = n \\cdot |e| \\cdot v \\cdot S$</p><p class=\"text-base leading-relaxed my-2\">Suy ra mật độ hạt electron:</p><p class=\"text-base leading-relaxed my-2\">$n = \\dfrac{I}{|e| \\cdot v \\cdot S}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $S = 10\\ \\text{mm}^2 = 10^{-5}\\ \\text{m}^2$; $v = 0{,}1\\ \\text{mm/s} = 10^{-4}\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$n = \\dfrac{2}{1{,}6\\cdot 10^{-19}\\cdot 10^{-4}\\cdot 10^{-5}} = \\dfrac{2}{1{,}6\\cdot 10^{-28}} = 1{,}25\\cdot 10^{28}\\ \\text{hạt/m}^3$</p><p class=\"text-base leading-relaxed my-2\">Vậy $X = 1{,}25$.</p>","difficultySource":"ai"},"ex":[{"exam":839,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"1,25","question":"Một dây dẫn hình trụ có diện tích tiết diện S = 10 mm2 có dòng điện cường độ 2 A chạy qua. Hạt mang điện tự do trong dây dẫn là electron có độ lớn điện tích là 1,6.10<sup>−19</sup> C. Biết tốc độ trung bình của electron trong chuyển động có hướng là 0,1 mm/s, mật độ hạt electron trong dây dẫn là X.10<sup>28</sup> hạt/m3. Tính X.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện trong dây dẫn liên hệ với mật độ hạt mang điện tự do, điện tích hạt, tốc độ trung bình có hướng và tiết diện dây theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$I = n \\cdot |e| \\cdot v \\cdot S$</p><p class=\"text-base leading-relaxed my-2\">Suy ra mật độ hạt electron:</p><p class=\"text-base leading-relaxed my-2\">$n = \\dfrac{I}{|e| \\cdot v \\cdot S}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $S = 10\\ \\text{mm}^2 = 10^{-5}\\ \\text{m}^2$; $v = 0{,}1\\ \\text{mm/s} = 10^{-4}\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$n = \\dfrac{2}{1{,}6\\cdot 10^{-19}\\cdot 10^{-4}\\cdot 10^{-5}} = \\dfrac{2}{1{,}6\\cdot 10^{-28}} = 1{,}25\\cdot 10^{28}\\ \\text{hạt/m}^3$</p><p class=\"text-base leading-relaxed my-2\">Vậy $X = 1{,}25$.</p>","difficultySource":"ai"}}]},{"id":1194586,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện trở phụ thuộc nhiệt độ","answer":"2020","question":"Một bóng đèn 220 V – 40 W có dây tóc làm bằng vônfram khi ở nhiệt độ 200C thì có điện trở là 121 Ω. Cho biết hệ số nhiệt điện trở của vônfram là α = 4,5.10<sup>−3</sup> K-1. Nhiệt độ của dây tóc khi bóng đèn sáng bình thường là bao nhiêu độ C (0C)?","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trở của đèn khi sáng bình thường (hiệu điện thế định mức 220 V, công suất định mức 40 W):</p><p class=\"text-base leading-relaxed my-2\">$R = \\dfrac{U^2}{P} = \\dfrac{220^2}{40} = 1210\\ \\Omega$</p><p class=\"text-base leading-relaxed my-2\">Sự phụ thuộc điện trở của kim loại vào nhiệt độ: $R = R_0[1+\\alpha(t-t_0)]$, với $R_0 = 121\\ \\Omega$ ở $t_0 = 20^\\circ$C và $\\alpha = 4{,}5.10^{-3}\\ \\text{K}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 1210 = 121[1+4{,}5.10^{-3}(t-20)]$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 1+4{,}5.10^{-3}(t-20) = 10$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t-20 = \\dfrac{9}{4{,}5.10^{-3}} = 2000$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t = 2020^\\circ$C</p><p class=\"text-base leading-relaxed my-2\">Vậy nhiệt độ của dây tóc khi đèn sáng bình thường là $2020^\\circ$C.</p>","difficultySource":"ai"},"ex":[{"exam":839,"idx":16,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện trở phụ thuộc nhiệt độ","answer":"2020","question":"Một bóng đèn 220 V – 40 W có dây tóc làm bằng vônfram khi ở nhiệt độ 200C thì có điện trở là 121 Ω. Cho biết hệ số nhiệt điện trở của vônfram là α = 4,5.10<sup>−3</sup> K-1. Nhiệt độ của dây tóc khi bóng đèn sáng bình thường là bao nhiêu độ C (0C)?","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trở của đèn khi sáng bình thường (hiệu điện thế định mức 220 V, công suất định mức 40 W):</p><p class=\"text-base leading-relaxed my-2\">$R = \\dfrac{U^2}{P} = \\dfrac{220^2}{40} = 1210\\ \\Omega$</p><p class=\"text-base leading-relaxed my-2\">Sự phụ thuộc điện trở của kim loại vào nhiệt độ: $R = R_0[1+\\alpha(t-t_0)]$, với $R_0 = 121\\ \\Omega$ ở $t_0 = 20^\\circ$C và $\\alpha = 4{,}5.10^{-3}\\ \\text{K}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 1210 = 121[1+4{,}5.10^{-3}(t-20)]$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 1+4{,}5.10^{-3}(t-20) = 10$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t-20 = \\dfrac{9}{4{,}5.10^{-3}} = 2000$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow t = 2020^\\circ$C</p><p class=\"text-base leading-relaxed my-2\">Vậy nhiệt độ của dây tóc khi đèn sáng bình thường là $2020^\\circ$C.</p>","difficultySource":"ai"}}]},{"id":1194799,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"4,68","question":"Một dây dẫn bằng đồng có đường kính tiết diện 2 mm, đang có dòng điện cường độ 2 A chạy qua. Biết mật độ electron tự do trong đồng là 8,5.10<sup>28</sup> hạt/m3. Vận tốc trôi của các electron tự do trong dây dẫn trên là X.10<sup>−5</sup> m/s. Xác định giá trị của X. Kết quả làm tròn đến hàng phần trăm.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi dòng điện không đổi chạy trong dây dẫn, cường độ dòng điện được tính theo công thức $I = n\\,e\\,S\\,v$, trong đó $n$ là mật độ electron tự do, $e = 1{,}6.10^{-19}\\ \\text{C}$ là điện tích electron, $S$ là tiết diện dây và $v$ là vận tốc trôi.</p><p class=\"text-base leading-relaxed my-2\">Suy ra vận tốc trôi: $v = \\dfrac{I}{n\\,e\\,S}$.</p><p class=\"text-base leading-relaxed my-2\">Tiết diện dây: $S = \\dfrac{\\pi d^2}{4} = \\dfrac{\\pi (2.10^{-3})^2}{4} = \\pi.10^{-6}\\ \\text{m}^2 \\approx 3{,}1416.10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v = \\dfrac{2}{8{,}5.10^{28}\\cdot 1{,}6.10^{-19}\\cdot 3{,}1416.10^{-6}} = \\dfrac{2}{4{,}2726.10^{4}} \\approx 4{,}68.10^{-5}\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy $X = 4{,}68$.</p>","difficultySource":"ai"},"ex":[{"exam":840,"idx":16,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"4,68","question":"Một dây dẫn bằng đồng có đường kính tiết diện 2 mm, đang có dòng điện cường độ 2 A chạy qua. Biết mật độ electron tự do trong đồng là 8,5.10<sup>28</sup> hạt/m3. Vận tốc trôi của các electron tự do trong dây dẫn trên là X.10<sup>−5</sup> m/s. Xác định giá trị của X. Kết quả làm tròn đến hàng phần trăm.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Khi dòng điện không đổi chạy trong dây dẫn, cường độ dòng điện được tính theo công thức $I = n\\,e\\,S\\,v$, trong đó $n$ là mật độ electron tự do, $e = 1{,}6.10^{-19}\\ \\text{C}$ là điện tích electron, $S$ là tiết diện dây và $v$ là vận tốc trôi.</p><p class=\"text-base leading-relaxed my-2\">Suy ra vận tốc trôi: $v = \\dfrac{I}{n\\,e\\,S}$.</p><p class=\"text-base leading-relaxed my-2\">Tiết diện dây: $S = \\dfrac{\\pi d^2}{4} = \\dfrac{\\pi (2.10^{-3})^2}{4} = \\pi.10^{-6}\\ \\text{m}^2 \\approx 3{,}1416.10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v = \\dfrac{2}{8{,}5.10^{28}\\cdot 1{,}6.10^{-19}\\cdot 3{,}1416.10^{-6}} = \\dfrac{2}{4{,}2726.10^{4}} \\approx 4{,}68.10^{-5}\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">Vậy $X = 4{,}68$.</p>","difficultySource":"ai"}}]},{"id":1195261,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Chuyển động của điện tích trong điện trường đều","answer":0,"options":["9,4.10<sup>7</sup> m/s","6,4.10<sup>7</sup> m/s","8,4.10<sup>7</sup> m/s","7,4.10<sup>7</sup> m/s"],"question":"Trong đèn hình của máy thu hình, các electron được tăng tốc bởi hiệu điện thế 25.000 V. Bỏ qua tốc độ ban đầu của các electron. Biết electron có khối lượng 9,1.10<sup>−31</sup> kg và điện tích – 1,6.10<sup>−19</sup> C Hỏi khi đập vào màn hình thì  tốc độ của các electron bằng bao nhiêu ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định lí động năng: công của lực điện trường bằng độ biến thiên động năng của electron. Electron xuất phát từ trạng thái nghỉ nên động năng ban đầu bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Công của lực điện: $A = |q|U = \\frac{1}{2}mv^2 - 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\sqrt{\\frac{2|q|U}{m}}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v = \\sqrt{\\frac{2 \\cdot 1{,}6\\cdot 10^{-19} \\cdot 25\\,000}{9{,}1\\cdot 10^{-31}}} = \\sqrt{8{,}79\\cdot 10^{15}} \\approx 9{,}4\\cdot 10^{7}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy khi đập vào màn hình, tốc độ của electron xấp xỉ $9{,}4\\cdot 10^{7}$ m/s, chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":841,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Chuyển động của điện tích trong điện trường đều","answer":0,"options":["9,4.10<sup>7</sup> m/s","6,4.10<sup>7</sup> m/s","8,4.10<sup>7</sup> m/s","7,4.10<sup>7</sup> m/s"],"question":"Trong đèn hình của máy thu hình, các electron được tăng tốc bởi hiệu điện thế 25.000 V. Bỏ qua tốc độ ban đầu của các electron. Biết electron có khối lượng 9,1.10<sup>−31</sup> kg và điện tích – 1,6.10<sup>−19</sup> C Hỏi khi đập vào màn hình thì  tốc độ của các electron bằng bao nhiêu ?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định lí động năng: công của lực điện trường bằng độ biến thiên động năng của electron. Electron xuất phát từ trạng thái nghỉ nên động năng ban đầu bằng 0.</p><p class=\"text-base leading-relaxed my-2\">Công của lực điện: $A = |q|U = \\frac{1}{2}mv^2 - 0$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\sqrt{\\frac{2|q|U}{m}}$</p><p class=\"text-base leading-relaxed my-2\">Thay số: $v = \\sqrt{\\frac{2 \\cdot 1{,}6\\cdot 10^{-19} \\cdot 25\\,000}{9{,}1\\cdot 10^{-31}}} = \\sqrt{8{,}79\\cdot 10^{15}} \\approx 9{,}4\\cdot 10^{7}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy khi đập vào màn hình, tốc độ của electron xấp xỉ $9{,}4\\cdot 10^{7}$ m/s, chọn A.</p>","difficultySource":"ai"}}]},{"id":1195264,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":3,"options":["- 1,6.10<sup>−19</sup> J","1,6.10<sup>−17</sup> J","1,6.10<sup>−19</sup> J","- 1,6.10<sup>−17</sup> J"],"question":"Một electron bay từ điểm M đến điểm N trong một điện trường, giữa hai điểm có hiệu điện thế UMN = 100 V. Công lực điện trường sẽ là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện trường khi một điện tích di chuyển từ M đến N: $A_{MN} = q \\cdot U_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">Electron có điện tích $q = -1{,}6\\cdot10^{-19}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A_{MN} = (-1{,}6\\cdot10^{-19})\\cdot 100 = -1{,}6\\cdot10^{-17}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Công âm nghĩa là điện trường cản trở chuyển động của electron từ M đến N.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là D.</p>","difficultySource":"ai"},"ex":[{"exam":841,"idx":4,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Công của lực điện và thế năng điện","answer":3,"options":["- 1,6.10<sup>−19</sup> J","1,6.10<sup>−17</sup> J","1,6.10<sup>−19</sup> J","- 1,6.10<sup>−17</sup> J"],"question":"Một electron bay từ điểm M đến điểm N trong một điện trường, giữa hai điểm có hiệu điện thế UMN = 100 V. Công lực điện trường sẽ là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện trường khi một điện tích di chuyển từ M đến N: $A_{MN} = q \\cdot U_{MN}$.</p><p class=\"text-base leading-relaxed my-2\">Electron có điện tích $q = -1{,}6\\cdot10^{-19}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A_{MN} = (-1{,}6\\cdot10^{-19})\\cdot 100 = -1{,}6\\cdot10^{-17}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Công âm nghĩa là điện trường cản trở chuyển động của electron từ M đến N.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là D.</p>","difficultySource":"ai"}}]},{"id":1195277,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định nghĩa cường độ dòng điện và mật độ dòng","answer":2,"options":["4 A","1,25.10<sup>19</sup> A","2 A","0,78 A"],"question":"Số electron qua tiết diện thẳng của một dây dẫn kim loại trong  $1$  giây là 1,25.10<sup>19</sup> hạt . Cường độ dòng điện chạy qua dây dẫn đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện được xác định bởi điện lượng dịch chuyển qua tiết diện thẳng trong một đơn vị thời gian: $I = \\dfrac{q}{t}$.</p><p class=\"text-base leading-relaxed my-2\">Điện lượng bằng số electron nhân với độ lớn điện tích electron: $q = N\\cdot |e|$, với $|e| = 1{,}6.10^{-19}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q = 1{,}25.10^{19}\\cdot 1{,}6.10^{-19} = 2\\ \\text{C}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I = \\dfrac{q}{t} = \\dfrac{2}{1} = 2\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ dòng điện là $2\\ \\text{A}$, chọn C.</p>","difficultySource":"ai"},"ex":[{"exam":841,"idx":17,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định nghĩa cường độ dòng điện và mật độ dòng","answer":2,"options":["4 A","1,25.10<sup>19</sup> A","2 A","0,78 A"],"question":"Số electron qua tiết diện thẳng của một dây dẫn kim loại trong  $1$  giây là 1,25.10<sup>19</sup> hạt . Cường độ dòng điện chạy qua dây dẫn đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện được xác định bởi điện lượng dịch chuyển qua tiết diện thẳng trong một đơn vị thời gian: $I = \\dfrac{q}{t}$.</p><p class=\"text-base leading-relaxed my-2\">Điện lượng bằng số electron nhân với độ lớn điện tích electron: $q = N\\cdot |e|$, với $|e| = 1{,}6.10^{-19}\\ \\text{C}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow q = 1{,}25.10^{19}\\cdot 1{,}6.10^{-19} = 2\\ \\text{C}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I = \\dfrac{q}{t} = \\dfrac{2}{1} = 2\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: cường độ dòng điện là $2\\ \\text{A}$, chọn C.</p>","difficultySource":"ai"}}]},{"id":1195283,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"0,25","question":"Một dây dẫn kim loại có các electron tự do chạy qua và tạo thành một dòng điện không đổi. Dây có tiết diện ngang S = 0,6 mm2, trong thời gian 10 s có điện lượng q = 9,6 C đi qua. Biết độ lớn điện tích của electron là e = 1,6.10<sup>−19</sup> C; mật độ electron tự do là n = 4.10<sup>28</sup> hạt/m3. Tính tốc độ trung bình của các electron tạo nên dòng điện. (đơn vị: mm/s)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện không đổi được tính bằng điện lượng chuyển qua tiết diện dây trong một đơn vị thời gian:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{q}{t} = \\dfrac{9{,}6}{10} = 0{,}96\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">Với dòng điện trong kim loại, $I = n|e|Sv$, trong đó $n$ là mật độ electron tự do, $S$ là tiết diện ngang và $v$ là tốc độ trung bình có hướng của electron.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\dfrac{I}{n|e|S}$</p><p class=\"text-base leading-relaxed my-2\">Đổi $S = 0{,}6\\ \\text{mm}^2 = 0{,}6\\cdot 10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\dfrac{0{,}96}{4\\cdot 10^{28}\\cdot 1{,}6\\cdot 10^{-19}\\cdot 0{,}6\\cdot 10^{-6}} = \\dfrac{0{,}96}{3840} = 2{,}5\\cdot 10^{-4}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $v = 2{,}5\\cdot 10^{-4}\\ \\text{m/s} = 0{,}25\\ \\text{mm/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ trung bình của các electron là $v = 0{,}25$ mm/s.</p>","difficultySource":"ai"},"ex":[{"exam":841,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"0,25","question":"Một dây dẫn kim loại có các electron tự do chạy qua và tạo thành một dòng điện không đổi. Dây có tiết diện ngang S = 0,6 mm2, trong thời gian 10 s có điện lượng q = 9,6 C đi qua. Biết độ lớn điện tích của electron là e = 1,6.10<sup>−19</sup> C; mật độ electron tự do là n = 4.10<sup>28</sup> hạt/m3. Tính tốc độ trung bình của các electron tạo nên dòng điện. (đơn vị: mm/s)","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện không đổi được tính bằng điện lượng chuyển qua tiết diện dây trong một đơn vị thời gian:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{q}{t} = \\dfrac{9{,}6}{10} = 0{,}96\\ \\text{A}$</p><p class=\"text-base leading-relaxed my-2\">Với dòng điện trong kim loại, $I = n|e|Sv$, trong đó $n$ là mật độ electron tự do, $S$ là tiết diện ngang và $v$ là tốc độ trung bình có hướng của electron.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\dfrac{I}{n|e|S}$</p><p class=\"text-base leading-relaxed my-2\">Đổi $S = 0{,}6\\ \\text{mm}^2 = 0{,}6\\cdot 10^{-6}\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\dfrac{0{,}96}{4\\cdot 10^{28}\\cdot 1{,}6\\cdot 10^{-19}\\cdot 0{,}6\\cdot 10^{-6}} = \\dfrac{0{,}96}{3840} = 2{,}5\\cdot 10^{-4}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $v = 2{,}5\\cdot 10^{-4}\\ \\text{m/s} = 0{,}25\\ \\text{mm/s}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ trung bình của các electron là $v = 0{,}25$ mm/s.</p>","difficultySource":"ai"}}]},{"id":1195284,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"-9","question":"Khi một điện tích q = 2.10<sup>−6</sup> C di chuyển từ điểm M đến điểm N trong điện trường thì công của lực điện – 1,8.10<sup>−5</sup> J. Tính hiệu điện thế giữa M và N. (đơn vị: V)","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích $q$ di chuyển từ M đến N được tính theo công thức: $A_{MN} = q \\cdot U_{MN}$, suy ra $U_{MN} = \\dfrac{A_{MN}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $A_{MN} = -1{,}8.10^{-5}\\ \\text{J}$ và $q = 2.10^{-6}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$U_{MN} = \\dfrac{-1{,}8.10^{-5}}{2.10^{-6}} = -9\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hiệu điện thế giữa M và N là $U_{MN} = -9\\ \\text{V}$. Dấu âm cho thấy điện thế tại M thấp hơn điện thế tại N.</p>","difficultySource":"ai"},"ex":[{"exam":841,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"-9","question":"Khi một điện tích q = 2.10<sup>−6</sup> C di chuyển từ điểm M đến điểm N trong điện trường thì công của lực điện – 1,8.10<sup>−5</sup> J. Tính hiệu điện thế giữa M và N. (đơn vị: V)","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công của lực điện khi điện tích $q$ di chuyển từ M đến N được tính theo công thức: $A_{MN} = q \\cdot U_{MN}$, suy ra $U_{MN} = \\dfrac{A_{MN}}{q}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $A_{MN} = -1{,}8.10^{-5}\\ \\text{J}$ và $q = 2.10^{-6}\\ \\text{C}$:</p><p class=\"text-base leading-relaxed my-2\">$U_{MN} = \\dfrac{-1{,}8.10^{-5}}{2.10^{-6}} = -9\\ \\text{V}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hiệu điện thế giữa M và N là $U_{MN} = -9\\ \\text{V}$. Dấu âm cho thấy điện thế tại M thấp hơn điện thế tại N.</p>","difficultySource":"ai"}}]},{"id":1195394,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Thế năng điện. Điện thế","answer":1,"options":["$-191.{10}^{-19}$  W.","$-191.{10}^{-19}$  J.","$191.{10}^{-17}$  J.","$-191.{10}^{-17}$  W."],"question":"Một electron đang ở độ cao 1,04 m so với mặt đất, tại nơi có điện trường Trái Đất bằng 115 V/m. Mốc thế năng điện được chọn tại mặt đất, êlectron có điện tích qe = 1,6.10<sup>−19</sup> C. Thế năng của electron đặt tại điểm M có giá trị bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trường Trái Đất hướng thẳng đứng xuống mặt đất; electron có $q=-1,6.10^{-19}$ C. Mốc thế năng tại mặt đất.</p><p class=\"text-base leading-relaxed my-2\">Thế năng tại M bằng công của lực điện khi electron dịch chuyển từ M xuống mốc: $W_M=A_{M0}=qEd$, với $d=1,04$ m (độ dời cùng chiều đường sức nên $d\\gt 0$).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M=(-1,6.10^{-19})\\cdot115\\cdot1,04$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M\\approx-1,9136.10^{-17}\\ \\text{J}=-191.10^{-19}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Thế năng có đơn vị J (W là đơn vị công suất nên A, D sai); giá trị âm nên C sai. Chọn <b>B</b>.</p>","difficultySource":"ai"},"ex":[{"exam":842,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Thế năng điện. Điện thế","answer":1,"options":["$-191.{10}^{-19}$  W.","$-191.{10}^{-19}$  J.","$191.{10}^{-17}$  J.","$-191.{10}^{-17}$  W."],"question":"Một electron đang ở độ cao 1,04 m so với mặt đất, tại nơi có điện trường Trái Đất bằng 115 V/m. Mốc thế năng điện được chọn tại mặt đất, êlectron có điện tích qe = 1,6.10<sup>−19</sup> C. Thế năng của electron đặt tại điểm M có giá trị bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trường Trái Đất hướng thẳng đứng xuống mặt đất; electron có $q=-1,6.10^{-19}$ C. Mốc thế năng tại mặt đất.</p><p class=\"text-base leading-relaxed my-2\">Thế năng tại M bằng công của lực điện khi electron dịch chuyển từ M xuống mốc: $W_M=A_{M0}=qEd$, với $d=1,04$ m (độ dời cùng chiều đường sức nên $d\\gt 0$).</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M=(-1,6.10^{-19})\\cdot115\\cdot1,04$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_M\\approx-1,9136.10^{-17}\\ \\text{J}=-191.10^{-19}\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Thế năng có đơn vị J (W là đơn vị công suất nên A, D sai); giá trị âm nên C sai. Chọn <b>B</b>.</p>","difficultySource":"ai"}}]},{"id":1195397,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng của tụ điện","answer":"4,67","question":"Một máy kích thích tim được sạc đầy năng lượng trong tụ điện của máy. Biết điện dung của tụ điện là 1,10.10<sup>−4</sup> F. Tìm hiệu điện thế cần thiết giữa hai bản tụ điện để lưu trữ 1,20 kJ ( theo đơn vị 103V và làm tròn sau dấu phẩy 2 chữ số).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng dự trữ trong tụ điện được tính theo công thức: $W = \\dfrac{1}{2}CU^2$, trong đó $C$ là điện dung (F), $U$ là hiệu điện thế (V), $W$ là năng lượng (J).</p><p class=\"text-base leading-relaxed my-2\">Suy ra hiệu điện thế cần thiết: $U = \\sqrt{\\dfrac{2W}{C}}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $W = 1{,}20$ kJ $= 1200$ J; $C = 1{,}10\\cdot 10^{-4}$ F.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $U = \\sqrt{\\dfrac{2\\cdot 1200}{1{,}10\\cdot 10^{-4}}} = \\sqrt{2{,}18\\cdot 10^{7}} \\approx 4671\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi sang đơn vị $10^3$ V và làm tròn đến 2 chữ số sau dấu phẩy: $U \\approx 4{,}67\\cdot 10^{3}$ V.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hiệu điện thế cần thiết khoảng $4{,}67\\cdot 10^{3}$ V.</p>","difficultySource":"ai"},"ex":[{"exam":842,"idx":12,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng của tụ điện","answer":"4,67","question":"Một máy kích thích tim được sạc đầy năng lượng trong tụ điện của máy. Biết điện dung của tụ điện là 1,10.10<sup>−4</sup> F. Tìm hiệu điện thế cần thiết giữa hai bản tụ điện để lưu trữ 1,20 kJ ( theo đơn vị 103V và làm tròn sau dấu phẩy 2 chữ số).","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Năng lượng dự trữ trong tụ điện được tính theo công thức: $W = \\dfrac{1}{2}CU^2$, trong đó $C$ là điện dung (F), $U$ là hiệu điện thế (V), $W$ là năng lượng (J).</p><p class=\"text-base leading-relaxed my-2\">Suy ra hiệu điện thế cần thiết: $U = \\sqrt{\\dfrac{2W}{C}}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $W = 1{,}20$ kJ $= 1200$ J; $C = 1{,}10\\cdot 10^{-4}$ F.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $U = \\sqrt{\\dfrac{2\\cdot 1200}{1{,}10\\cdot 10^{-4}}} = \\sqrt{2{,}18\\cdot 10^{7}} \\approx 4671\\ \\text{V}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi sang đơn vị $10^3$ V và làm tròn đến 2 chữ số sau dấu phẩy: $U \\approx 4{,}67\\cdot 10^{3}$ V.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: hiệu điện thế cần thiết khoảng $4{,}67\\cdot 10^{3}$ V.</p>","difficultySource":"ai"}}]},{"id":1195680,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":0,"options":["0,34 N","0,2 N","1,97.10<sup>−3</sup>N","1,97 N"],"question":"Độ lớn lực tương tác điện giữa điện hai tích q1 = −2,4 µC và điện tích q2 = 5,3 µC đặt cách nhau 58 cm trong chân không gần giá trị nào nhất.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật Cu-lông: lực tương tác giữa hai điện tích điểm đặt trong chân không có độ lớn tỉ lệ thuận với tích độ lớn các điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^{9}\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $|q_1| = 2{,}4\\ \\mu\\text{C} = 2{,}4.10^{-6}\\ \\text{C}$; $|q_2| = 5{,}3\\ \\mu\\text{C} = 5{,}3.10^{-6}\\ \\text{C}$; $r = 58\\ \\text{cm} = 0{,}58\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 9.10^{9}\\dfrac{2{,}4.10^{-6}\\cdot 5{,}3.10^{-6}}{0{,}58^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^{9}\\cdot \\dfrac{12{,}72.10^{-12}}{0{,}3364}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F \\approx 0{,}34\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vì $q_1$ và $q_2$ trái dấu nên hai điện tích hút nhau. Lực có độ lớn khoảng $0{,}34\\ \\text{N}$, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":843,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":0,"options":["0,34 N","0,2 N","1,97.10<sup>−3</sup>N","1,97 N"],"question":"Độ lớn lực tương tác điện giữa điện hai tích q1 = −2,4 µC và điện tích q2 = 5,3 µC đặt cách nhau 58 cm trong chân không gần giá trị nào nhất.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Áp dụng định luật Cu-lông: lực tương tác giữa hai điện tích điểm đặt trong chân không có độ lớn tỉ lệ thuận với tích độ lớn các điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $F = k\\dfrac{|q_1 q_2|}{r^2}$, với $k = 9.10^{9}\\ \\text{N.m}^2/\\text{C}^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $|q_1| = 2{,}4\\ \\mu\\text{C} = 2{,}4.10^{-6}\\ \\text{C}$; $|q_2| = 5{,}3\\ \\mu\\text{C} = 5{,}3.10^{-6}\\ \\text{C}$; $r = 58\\ \\text{cm} = 0{,}58\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $F = 9.10^{9}\\dfrac{2{,}4.10^{-6}\\cdot 5{,}3.10^{-6}}{0{,}58^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F = 9.10^{9}\\cdot \\dfrac{12{,}72.10^{-12}}{0{,}3364}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow F \\approx 0{,}34\\ \\text{N}$</p><p class=\"text-base leading-relaxed my-2\">Vì $q_1$ và $q_2$ trái dấu nên hai điện tích hút nhau. Lực có độ lớn khoảng $0{,}34\\ \\text{N}$, đáp án A.</p>","difficultySource":"ai"}}]},{"id":1195686,"nq":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"0,07","question":"Một dây dẫn bằng nhôm hình trụ tròn có đường kính tiết diện 3,0 mm mang dòng điện 15A. Cho biết mật độ electron tự do trong dây dẫn là n= 1,806.10<sup>29</sup> electron/m3 .Tốc độ trôi của electron trong dây dẫn bằng nhôm này bằng bao nhiêu mm/s? Lấy giá trị của π trong máy tính cầm tay. Kết quả lấy đến hai chữ số sau dấu phảy.","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện trong dây dẫn kim loại liên hệ với tốc độ trôi của electron theo công thức $I = n\\,e\\,v\\,S$, trong đó $n$ là mật độ electron tự do, $e = 1{,}6\\cdot10^{-19}\\ \\text{C}$ là điện tích electron, $S$ là tiết diện ngang của dây.</p><p class=\"text-base leading-relaxed my-2\">Suy ra tốc độ trôi: $v = \\dfrac{I}{n\\,e\\,S}$.</p><p class=\"text-base leading-relaxed my-2\">Tiết diện ngang của dây (hình tròn, đường kính $d = 3{,}0\\ \\text{mm} = 3{,}0\\cdot10^{-3}\\ \\text{m}$):</p><p class=\"text-base leading-relaxed my-2\">$S = \\dfrac{\\pi d^2}{4} = \\dfrac{\\pi (3{,}0\\cdot10^{-3})^2}{4} \\approx 7{,}0686\\cdot10^{-6}\\ \\text{m}^2$</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$v = \\dfrac{15}{1{,}806\\cdot10^{29}\\cdot1{,}6\\cdot10^{-19}\\cdot7{,}0686\\cdot10^{-6}} \\approx 7{,}34\\cdot10^{-5}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v \\approx 0{,}0734\\ \\text{mm/s} \\approx 0{,}07\\ \\text{mm/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy tốc độ trôi của electron xấp xỉ $0{,}07$ mm/s.</p>","difficultySource":"ai"},"ex":[{"exam":843,"idx":16,"el":{"form":"bai_tap","type":"short_answer","topic":"Liên hệ cường độ dòng điện với chuyển động hạt tải điện","answer":"0,07","question":"Một dây dẫn bằng nhôm hình trụ tròn có đường kính tiết diện 3,0 mm mang dòng điện 15A. Cho biết mật độ electron tự do trong dây dẫn là n= 1,806.10<sup>29</sup> electron/m3 .Tốc độ trôi của electron trong dây dẫn bằng nhôm này bằng bao nhiêu mm/s? Lấy giá trị của π trong máy tính cầm tay. Kết quả lấy đến hai chữ số sau dấu phảy.","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Cường độ dòng điện trong dây dẫn kim loại liên hệ với tốc độ trôi của electron theo công thức $I = n\\,e\\,v\\,S$, trong đó $n$ là mật độ electron tự do, $e = 1{,}6\\cdot10^{-19}\\ \\text{C}$ là điện tích electron, $S$ là tiết diện ngang của dây.</p><p class=\"text-base leading-relaxed my-2\">Suy ra tốc độ trôi: $v = \\dfrac{I}{n\\,e\\,S}$.</p><p class=\"text-base leading-relaxed my-2\">Tiết diện ngang của dây (hình tròn, đường kính $d = 3{,}0\\ \\text{mm} = 3{,}0\\cdot10^{-3}\\ \\text{m}$):</p><p class=\"text-base leading-relaxed my-2\">$S = \\dfrac{\\pi d^2}{4} = \\dfrac{\\pi (3{,}0\\cdot10^{-3})^2}{4} \\approx 7{,}0686\\cdot10^{-6}\\ \\text{m}^2$</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$v = \\dfrac{15}{1{,}806\\cdot10^{29}\\cdot1{,}6\\cdot10^{-19}\\cdot7{,}0686\\cdot10^{-6}} \\approx 7{,}34\\cdot10^{-5}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v \\approx 0{,}0734\\ \\text{mm/s} \\approx 0{,}07\\ \\text{mm/s}$</p><p class=\"text-base leading-relaxed my-2\">Vậy tốc độ trôi của electron xấp xỉ $0{,}07$ mm/s.</p>","difficultySource":"ai"}}]},{"id":1196115,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":2,"options":["1,2.10<sup>−17</sup> N.","1,1.10<sup>−21</sup> N.","2,4.10<sup>−17</sup> N.","9,4.10<sup>20</sup> N."],"question":"Tại nơi điện trường Trái Đất có cường độ 150 V/m, một ion OH- có điện tích  $−1,6.10^{−19}$ C được phát ra từ một máy lọc không khí. Lực do điện trường Trái Đất tác dụng lên ion này có độ lớn là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích đặt trong điện trường đều có độ lớn: $F = |q|E$, trong đó $|q|$ là độ lớn điện tích (đơn vị C) và $E$ là cường độ điện trường (đơn vị V/m, tương đương N/C).</p><p class=\"text-base leading-relaxed my-2\">Thay số với $|q| = 1,6.10^{-19}$ C và $E = 150$ V/m:</p><p class=\"text-base leading-relaxed my-2\">$F = 1,6.10^{-19} \\cdot 150 = 2,4.10^{-17}$ N</p><p class=\"text-base leading-relaxed my-2\">Vậy lực điện do điện trường Trái Đất tác dụng lên ion OH⁻ có độ lớn $2,4.10^{-17}$ N, đáp án C.</p>","difficultySource":"ai"},"ex":[{"exam":844,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Khái niệm điện trường. Cường độ điện trường","answer":2,"options":["1,2.10<sup>−17</sup> N.","1,1.10<sup>−21</sup> N.","2,4.10<sup>−17</sup> N.","9,4.10<sup>20</sup> N."],"question":"Tại nơi điện trường Trái Đất có cường độ 150 V/m, một ion OH- có điện tích  $−1,6.10^{−19}$ C được phát ra từ một máy lọc không khí. Lực do điện trường Trái Đất tác dụng lên ion này có độ lớn là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Lực điện tác dụng lên điện tích đặt trong điện trường đều có độ lớn: $F = |q|E$, trong đó $|q|$ là độ lớn điện tích (đơn vị C) và $E$ là cường độ điện trường (đơn vị V/m, tương đương N/C).</p><p class=\"text-base leading-relaxed my-2\">Thay số với $|q| = 1,6.10^{-19}$ C và $E = 150$ V/m:</p><p class=\"text-base leading-relaxed my-2\">$F = 1,6.10^{-19} \\cdot 150 = 2,4.10^{-17}$ N</p><p class=\"text-base leading-relaxed my-2\">Vậy lực điện do điện trường Trái Đất tác dụng lên ion OH⁻ có độ lớn $2,4.10^{-17}$ N, đáp án C.</p>","difficultySource":"ai"}}]},{"id":1224418,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đặc điểm và thang sóng điện từ","answer":1,"options":["2.10<sup>8</sup>m/s.","3.10<sup>8</sup>m/s.","2.10<sup>−8</sup>m/s.","3.10<sup>−8</sup>m/s."],"question":"Trong chân không, tất cả các sóng điện từ đều truyền với tốc độ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo lí thuyết về sóng điện từ, trong chân không mọi sóng điện từ (không phụ thuộc tần số) đều lan truyền với cùng một tốc độ bằng tốc độ ánh sáng.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $c = 3.10^{8}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ truyền của sóng điện từ trong chân không là $3.10^{8}\\ \\text{m/s}$, chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":846,"idx":14,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đặc điểm và thang sóng điện từ","answer":1,"options":["2.10<sup>8</sup>m/s.","3.10<sup>8</sup>m/s.","2.10<sup>−8</sup>m/s.","3.10<sup>−8</sup>m/s."],"question":"Trong chân không, tất cả các sóng điện từ đều truyền với tốc độ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo lí thuyết về sóng điện từ, trong chân không mọi sóng điện từ (không phụ thuộc tần số) đều lan truyền với cùng một tốc độ bằng tốc độ ánh sáng.</p><p class=\"text-base leading-relaxed my-2\">Công thức: $c = 3.10^{8}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tốc độ truyền của sóng điện từ trong chân không là $3.10^{8}\\ \\text{m/s}$, chọn đáp án B.</p>","difficultySource":"ai"}}]},{"id":1224419,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đặc điểm và thang sóng điện từ","answer":0,"options":["Tia X.","Tia tử ngoại.","Tia hồng ngoại.","Tia Gamma"],"question":"Sóng điện từ có bước sóng 3.10<sup>−10</sup>m là loại sóng điện từ nào sau đây?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Đề hiểu là bước sóng $\\lambda=3.10^{-10}$ m.</p><p class=\"text-base leading-relaxed my-2\">Đối chiếu thang sóng điện từ (giá trị gần đúng): hồng ngoại có $\\lambda\\gt 7{,}6.10^{-7}$ m; tử ngoại cỡ $10^{-8}$ đến $3{,}8.10^{-7}$ m; tia X cỡ $10^{-11}$ đến $10^{-8}$ m; tia gamma $\\lambda\\lt 10^{-11}$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow 10^{-11}\\lt 3.10^{-10}\\lt 10^{-8}$ (m), nằm trong vùng tia X.</p><p class=\"text-base leading-relaxed my-2\">Không đúng vì: B và C có bước sóng lớn hơn $10^{-8}$ m nên $3.10^{-10}$ m nhỏ hơn nhiều; D cần $\\lambda\\lt 10^{-11}$ m trong khi $3.10^{-10}$ m lớn hơn khoảng 30 lần.</p><p class=\"text-base leading-relaxed my-2\">Chọn A.</p>","difficultySource":"ai"},"ex":[{"exam":846,"idx":15,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Đặc điểm và thang sóng điện từ","answer":0,"options":["Tia X.","Tia tử ngoại.","Tia hồng ngoại.","Tia Gamma"],"question":"Sóng điện từ có bước sóng 3.10<sup>−10</sup>m là loại sóng điện từ nào sau đây?","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1227144,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Sóng điện từ","answer":0,"options":["Sóng điện từ chỉ truyền được trong môi trường vật chất đàn hồi.","Sóng điện từ là sóng ngang.","Sóng điện từ truyền trong chân không với vận tốc c=3.10<sup>8</sup> m/s.","Sóng điện từ bị phản xạ khi gặp mặt phân cách giữa hai môi trường."],"question":"Khi nói về sóng điện từ, phát biểu nào sau đây là sai?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ là sóng ngang, lan truyền được cả trong chân không, không cần môi trường vật chất đàn hồi.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai: sóng điện từ truyền được trong chân không, khác với sóng cơ học cần môi trường đàn hồi.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng: vectơ cường độ điện trường $\\vec{E}$ và cảm ứng từ $\\vec{B}$ đều vuông góc với phương truyền sóng.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng: trong chân không, tốc độ sóng điện từ là $c = 3.10^{8}\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng: sóng điện từ có các tính chất phản xạ, khúc xạ, giao thoa như mọi sóng khác.</p><p class=\"text-base leading-relaxed my-2\">Vậy phát biểu sai là A.</p>","difficultySource":"ai"},"ex":[{"exam":849,"idx":14,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Sóng điện từ","answer":0,"options":["Sóng điện từ chỉ truyền được trong môi trường vật chất đàn hồi.","Sóng điện từ là sóng ngang.","Sóng điện từ truyền trong chân không với vận tốc c=3.10<sup>8</sup> m/s.","Sóng điện từ bị phản xạ khi gặp mặt phân cách giữa hai môi trường."],"question":"Khi nói về sóng điện từ, phát biểu nào sau đây là sai?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ là sóng ngang, lan truyền được cả trong chân không, không cần môi trường vật chất đàn hồi.</p><p class=\"text-base leading-relaxed my-2\">Xét từng phương án:</p><p class=\"text-base leading-relaxed my-2\">A. Sai: sóng điện từ truyền được trong chân không, khác với sóng cơ học cần môi trường đàn hồi.</p><p class=\"text-base leading-relaxed my-2\">B. Đúng: vectơ cường độ điện trường $\\vec{E}$ và cảm ứng từ $\\vec{B}$ đều vuông góc với phương truyền sóng.</p><p class=\"text-base leading-relaxed my-2\">C. Đúng: trong chân không, tốc độ sóng điện từ là $c = 3.10^{8}\\ \\text{m/s}$.</p><p class=\"text-base leading-relaxed my-2\">D. Đúng: sóng điện từ có các tính chất phản xạ, khúc xạ, giao thoa như mọi sóng khác.</p><p class=\"text-base leading-relaxed my-2\">Vậy phát biểu sai là A.</p>","difficultySource":"ai"}}]},{"id":1227495,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Đặc điểm và thang sóng điện từ","answer":0,"options":["4.10<sup>14</sup>Hz","4.10<sup>5</sup>Mz","4.10<sup>11</sup>Hz","400MHz"],"question":"Ánh sáng đỏ có bước sóng 0,75µm có tần số:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Công thức liên hệ giữa tần số $f$, bước sóng $\\lambda$ và tốc độ truyền sóng $c$ trong chân không: $f = \\dfrac{c}{\\lambda}$, với $c = 3.10^8$ m/s.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị bước sóng: $\\lambda = 0{,}75\\ \\mu m = 0{,}75.10^{-6}$ m $= 7{,}5.10^{-7}$ m.</p><p class=\"text-base leading-relaxed my-2\">Tần số của ánh sáng đỏ: $f = \\dfrac{3.10^8}{7{,}5.10^{-7}} = 4.10^{14}$ Hz.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tần số ánh sáng đỏ là $4.10^{14}$ Hz, chọn đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":850,"idx":16,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Đặc điểm và thang sóng điện từ","answer":0,"options":["4.10<sup>14</sup>Hz","4.10<sup>5</sup>Mz","4.10<sup>11</sup>Hz","400MHz"],"question":"Ánh sáng đỏ có bước sóng 0,75µm có tần số:","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1228159,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Dao động cưỡng bức và hiện tượng cộng hưởng","answer":0,"options":["5.10<sup>−2</sup> kg.","5 g.","5 kg.","0,05 g."],"question":"Một con lắc lò xo gồm vật nhỏ có khối lượng m gắn vào một lò xo có độ cứng 50 N/m. Tác dụng lên vật ngoại lực cưỡng bức  $F=40cos\\left(10\\pi t−\\pi \\right)$ (N) dọc theo trục xò xo thì hiện tượng cộng hưởng cơ xảy ra. Lấy  $\\pi^2=10$ . Giá trị của m là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Tần số góc của ngoại lực cưỡng bức: $\\omega_f = 10\\pi$ rad/s (lấy từ pha của $F = 40\\cos(10\\pi t - \\pi)$ N).</p><p class=\"text-base leading-relaxed my-2\">Hiện tượng cộng hưởng xảy ra khi tần số của ngoại lực bằng tần số riêng của hệ: $\\omega_f = \\omega_0$.</p><p class=\"text-base leading-relaxed my-2\">Tần số góc riêng của con lắc lò xo: $\\omega_0 = \\sqrt{\\dfrac{k}{m}}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $m = \\dfrac{k}{\\omega_0^2} = \\dfrac{k}{\\omega_f^2}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $k = 50$ N/m và $\\pi^2 = 10$: $m = \\dfrac{50}{(10\\pi)^2} = \\dfrac{50}{100\\pi^2} = \\dfrac{50}{100 \\cdot 10} = 0{,}05$ kg $= 5\\cdot 10^{-2}$ kg.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: khối lượng vật $m = 5\\cdot 10^{-2}$ kg, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":852,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Dao động cưỡng bức và hiện tượng cộng hưởng","answer":0,"options":["5.10<sup>−2</sup> kg.","5 g.","5 kg.","0,05 g."],"question":"Một con lắc lò xo gồm vật nhỏ có khối lượng m gắn vào một lò xo có độ cứng 50 N/m. Tác dụng lên vật ngoại lực cưỡng bức  $F=40cos\\left(10\\pi t−\\pi \\right)$ (N) dọc theo trục xò xo thì hiện tượng cộng hưởng cơ xảy ra. Lấy  $\\pi^2=10$ . Giá trị của m là","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Tần số góc của ngoại lực cưỡng bức: $\\omega_f = 10\\pi$ rad/s (lấy từ pha của $F = 40\\cos(10\\pi t - \\pi)$ N).</p><p class=\"text-base leading-relaxed my-2\">Hiện tượng cộng hưởng xảy ra khi tần số của ngoại lực bằng tần số riêng của hệ: $\\omega_f = \\omega_0$.</p><p class=\"text-base leading-relaxed my-2\">Tần số góc riêng của con lắc lò xo: $\\omega_0 = \\sqrt{\\dfrac{k}{m}}$.</p><p class=\"text-base leading-relaxed my-2\">Suy ra: $m = \\dfrac{k}{\\omega_0^2} = \\dfrac{k}{\\omega_f^2}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $k = 50$ N/m và $\\pi^2 = 10$: $m = \\dfrac{50}{(10\\pi)^2} = \\dfrac{50}{100\\pi^2} = \\dfrac{50}{100 \\cdot 10} = 0{,}05$ kg $= 5\\cdot 10^{-2}$ kg.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: khối lượng vật $m = 5\\cdot 10^{-2}$ kg, đáp án A.</p>","difficultySource":"ai"}}]},{"id":1228166,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Bước sóng, chu kì, tần số, tốc độ truyền sóng","answer":0,"options":["20,2.10<sup>3</sup> Hz","18,2.10<sup>3</sup> Hz","28,2.10<sup>3</sup> Hz","19,2.10<sup>3</sup> Hz"],"question":"Âm thanh là sóng dọc có thể lan truyền qua môi trường rắn. Tính tần số của sóng âm có bước sóng 0,250 m truyền qua một tấm thép với tốc độ 5060 m/s.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng âm truyền qua thép có tốc độ $v = 5060\\ \\text{m/s}$ và bước sóng $\\lambda = 0{,}250\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Công thức liên hệ tốc độ, bước sóng và tần số: $v = \\lambda f$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$f = \\dfrac{v}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $f = \\dfrac{5060}{0{,}250} = 20240\\ \\text{Hz} = 20{,}2\\cdot 10^{3}\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tần số của sóng âm là $20{,}2\\cdot 10^{3}\\ \\text{Hz}$, chọn đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":852,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Bước sóng, chu kì, tần số, tốc độ truyền sóng","answer":0,"options":["20,2.10<sup>3</sup> Hz","18,2.10<sup>3</sup> Hz","28,2.10<sup>3</sup> Hz","19,2.10<sup>3</sup> Hz"],"question":"Âm thanh là sóng dọc có thể lan truyền qua môi trường rắn. Tính tần số của sóng âm có bước sóng 0,250 m truyền qua một tấm thép với tốc độ 5060 m/s.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng âm truyền qua thép có tốc độ $v = 5060\\ \\text{m/s}$ và bước sóng $\\lambda = 0{,}250\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Công thức liên hệ tốc độ, bước sóng và tần số: $v = \\lambda f$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$f = \\dfrac{v}{\\lambda}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $f = \\dfrac{5060}{0{,}250} = 20240\\ \\text{Hz} = 20{,}2\\cdot 10^{3}\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: tần số của sóng âm là $20{,}2\\cdot 10^{3}\\ \\text{Hz}$, chọn đáp án A.</p>","difficultySource":"ai"}}]},{"id":1228401,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Sóng điện từ","answer":3,"options":["2.10<sup>8</sup> m/s.","3.10<sup>5</sup> km/h.","3.10<sup>−8</sup> m/s.","3.10<sup>8</sup> m/s."],"question":"Trong chân không, tất cả các sóng điện từ đều truyền với tốc độ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo lí thuyết về sóng điện từ, trong chân không mọi sóng điện từ (không phụ thuộc tần số) đều lan truyền với cùng một tốc độ, bằng tốc độ ánh sáng trong chân không.</p><p class=\"text-base leading-relaxed my-2\">$c = 3.10^{8}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $2.10^{8}$ m/s: sai giá trị.</p><p class=\"text-base leading-relaxed my-2\">B. $3.10^{5}$ km/h $= \\dfrac{3.10^{8}}{3{,}6}\\approx 8{,}3.10^{7}$ m/s: sai.</p><p class=\"text-base leading-relaxed my-2\">C. $3.10^{-8}$ m/s: sai, vô lí.</p><p class=\"text-base leading-relaxed my-2\">D. $3.10^{8}$ m/s: đúng.</p><p class=\"text-base leading-relaxed my-2\"><b>Đáp án: D</b></p>","difficultySource":"ai"},"ex":[{"exam":853,"idx":15,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Sóng điện từ","answer":3,"options":["2.10<sup>8</sup> m/s.","3.10<sup>5</sup> km/h.","3.10<sup>−8</sup> m/s.","3.10<sup>8</sup> m/s."],"question":"Trong chân không, tất cả các sóng điện từ đều truyền với tốc độ","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo lí thuyết về sóng điện từ, trong chân không mọi sóng điện từ (không phụ thuộc tần số) đều lan truyền với cùng một tốc độ, bằng tốc độ ánh sáng trong chân không.</p><p class=\"text-base leading-relaxed my-2\">$c = 3.10^{8}\\ \\text{m/s}$</p><p class=\"text-base leading-relaxed my-2\">Kiểm tra các phương án:</p><p class=\"text-base leading-relaxed my-2\">A. $2.10^{8}$ m/s: sai giá trị.</p><p class=\"text-base leading-relaxed my-2\">B. $3.10^{5}$ km/h $= \\dfrac{3.10^{8}}{3{,}6}\\approx 8{,}3.10^{7}$ m/s: sai.</p><p class=\"text-base leading-relaxed my-2\">C. $3.10^{-8}$ m/s: sai, vô lí.</p><p class=\"text-base leading-relaxed my-2\">D. $3.10^{8}$ m/s: đúng.</p><p class=\"text-base leading-relaxed my-2\"><b>Đáp án: D</b></p>","difficultySource":"ai"}}]},{"id":1229387,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":0,"options":["3,6.10<sup>−4</sup> J","7,2.10<sup>−4</sup> J","7,6.10<sup>−4</sup> J","1.10<sup>−4</sup> J"],"question":"Một vật có khối lượng  $50 gam,$  dao động điều hòa với biên độ  $4 cm$  và tần số góc  $3 rad/s.$  Động năng cực đại của vật là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động năng cực đại của vật dao động điều hòa bằng cơ năng, được tính theo công thức: $W_{d,max} = W = \\frac{1}{2}m\\omega^2A^2$, trong đó $m$ là khối lượng, $\\omega$ là tần số góc và $A$ là biên độ.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 50\\text{ g} = 0{,}05\\text{ kg}$; $A = 4\\text{ cm} = 0{,}04\\text{ m}$; $\\omega = 3\\text{ rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W_{d,max} = \\frac{1}{2}\\cdot 0{,}05\\cdot 3^2\\cdot 0{,}04^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_{d,max} = 0{,}5\\cdot 0{,}05\\cdot 9\\cdot 0{,}0016 = 3{,}6\\cdot 10^{-4}\\text{ J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy động năng cực đại của vật là $3{,}6\\cdot 10^{-4}\\text{ J}$, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":856,"idx":5,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":0,"options":["3,6.10<sup>−4</sup> J","7,2.10<sup>−4</sup> J","7,6.10<sup>−4</sup> J","1.10<sup>−4</sup> J"],"question":"Một vật có khối lượng  $50 gam,$  dao động điều hòa với biên độ  $4 cm$  và tần số góc  $3 rad/s.$  Động năng cực đại của vật là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Động năng cực đại của vật dao động điều hòa bằng cơ năng, được tính theo công thức: $W_{d,max} = W = \\frac{1}{2}m\\omega^2A^2$, trong đó $m$ là khối lượng, $\\omega$ là tần số góc và $A$ là biên độ.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $m = 50\\text{ g} = 0{,}05\\text{ kg}$; $A = 4\\text{ cm} = 0{,}04\\text{ m}$; $\\omega = 3\\text{ rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $W_{d,max} = \\frac{1}{2}\\cdot 0{,}05\\cdot 3^2\\cdot 0{,}04^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_{d,max} = 0{,}5\\cdot 0{,}05\\cdot 9\\cdot 0{,}0016 = 3{,}6\\cdot 10^{-4}\\text{ J}$</p><p class=\"text-base leading-relaxed my-2\">Vậy động năng cực đại của vật là $3{,}6\\cdot 10^{-4}\\text{ J}$, đáp án A.</p>","difficultySource":"ai"}}]},{"id":1229394,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Bước sóng, chu kì, tần số, tốc độ truyền sóng","answer":0,"options":["3 m","1,5 m","0,33 m","0,16 m"],"question":"Một sóng vô tuyến có tần số 108 Hz được truyền trong không trung với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức liên hệ giữa tốc độ truyền sóng, tần số và bước sóng: $\\lambda = \\dfrac{v}{f}$, trong đó $v$ là tốc độ truyền sóng (m/s) và $f$ là tần số (Hz).</p><p class=\"text-base leading-relaxed my-2\">Thay số với $v = 3.10^{8}$ m/s và $f = 10^{8}$ Hz:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda = \\dfrac{3.10^{8}}{10^{8}} = 3$ m</p><p class=\"text-base leading-relaxed my-2\">Vậy bước sóng của sóng vô tuyến là 3 m, đáp án A.</p>","difficultySource":"ai"},"ex":[{"exam":856,"idx":12,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Bước sóng, chu kì, tần số, tốc độ truyền sóng","answer":0,"options":["3 m","1,5 m","0,33 m","0,16 m"],"question":"Một sóng vô tuyến có tần số 108 Hz được truyền trong không trung với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng đó là","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức liên hệ giữa tốc độ truyền sóng, tần số và bước sóng: $\\lambda = \\dfrac{v}{f}$, trong đó $v$ là tốc độ truyền sóng (m/s) và $f$ là tần số (Hz).</p><p class=\"text-base leading-relaxed my-2\">Thay số với $v = 3.10^{8}$ m/s và $f = 10^{8}$ Hz:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda = \\dfrac{3.10^{8}}{10^{8}} = 3$ m</p><p class=\"text-base leading-relaxed my-2\">Vậy bước sóng của sóng vô tuyến là 3 m, đáp án A.</p>","difficultySource":"ai"}}]},{"id":1230707,"nq":{"form":"bai_tap","type":"short_answer","topic":"Đặc điểm và thang sóng điện từ","answer":"4","question":"Một bức xạ ánh sáng đỏ có bước sóng 7,5.10<sup>−7</sup> m trong chân không, tần số ánh sáng đỏ này y.10<sup>14</sup> Hz. Giá trị của y bằng bao nhiêu?<br>C.âu 4.\t4.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Tần số của ánh sáng liên hệ với bước sóng trong chân không theo công thức:</p><p class=\"text-base leading-relaxed my-2\">$f = \\dfrac{c}{\\lambda}$</p><p class=\"text-base leading-relaxed my-2\">trong đó $c = 3\\cdot10^{8}$ m/s là tốc độ ánh sáng trong chân không và $\\lambda = 7{,}5\\cdot10^{-7}$ m.</p><p class=\"text-base leading-relaxed my-2\">Thay số:</p><p class=\"text-base leading-relaxed my-2\">$f = \\dfrac{3\\cdot10^{8}}{7{,}5\\cdot10^{-7}} = 4\\cdot10^{14}$ Hz</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$y = 4$.</p>","difficultySource":"ai"},"ex":[{"exam":858,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Đặc điểm và thang sóng điện từ","answer":"4","question":"Một bức xạ ánh sáng đỏ có bước sóng 7,5.10<sup>−7</sup> m trong chân không, tần số ánh sáng đỏ này y.10<sup>14</sup> Hz. Giá trị của y bằng bao nhiêu?<br>C.âu 4.\t4.","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1232565,"nq":{"form":"bai_tap","type":"short_answer","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":"0,08","question":"Theo báo Kinh tế Sài gòn online, Tập đoàn VNPT đã đấu giá thành công quyền sử dụng tần số đối với khối băng tần 3700 - 3800 MHz phục vụ cho cung cấp dịch vụ 5G trong thời gian tới. Hiện tại băng tần 5G đang ngày càng phổ biến ở Việt Nam. Vậy sóng điện từ có tần số 3750 MHz thì có bước sóng là bao nhiêu mét? Cho tốc độ truyền sóng là 3.10<sup>8</sup> m/s.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ truyền trong chân không (hoặc không khí) với tốc độ $c$ không đổi. Bước sóng $\\lambda$, tần số $f$ và tốc độ truyền sóng $c$ liên hệ theo công thức: $\\lambda = \\dfrac{c}{f}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị tần số: $f = 3750\\ \\text{MHz} = 3750 \\cdot 10^{6}\\ \\text{Hz} = 3{,}75 \\cdot 10^{9}\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $c = 3 \\cdot 10^{8}\\ \\text{m/s}$:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda = \\dfrac{3 \\cdot 10^{8}}{3{,}75 \\cdot 10^{9}}\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\lambda = 0{,}08\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy sóng điện từ có tần số 3750 MHz có bước sóng là $0{,}08\\ \\text{m}$ (8 cm).</p>","difficultySource":"ai"},"ex":[{"exam":862,"idx":19,"el":{"form":"bai_tap","type":"short_answer","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":"0,08","question":"Theo báo Kinh tế Sài gòn online, Tập đoàn VNPT đã đấu giá thành công quyền sử dụng tần số đối với khối băng tần 3700 - 3800 MHz phục vụ cho cung cấp dịch vụ 5G trong thời gian tới. Hiện tại băng tần 5G đang ngày càng phổ biến ở Việt Nam. Vậy sóng điện từ có tần số 3750 MHz thì có bước sóng là bao nhiêu mét? Cho tốc độ truyền sóng là 3.10<sup>8</sup> m/s.","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Sóng điện từ truyền trong chân không (hoặc không khí) với tốc độ $c$ không đổi. Bước sóng $\\lambda$, tần số $f$ và tốc độ truyền sóng $c$ liên hệ theo công thức: $\\lambda = \\dfrac{c}{f}$.</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị tần số: $f = 3750\\ \\text{MHz} = 3750 \\cdot 10^{6}\\ \\text{Hz} = 3{,}75 \\cdot 10^{9}\\ \\text{Hz}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $c = 3 \\cdot 10^{8}\\ \\text{m/s}$:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda = \\dfrac{3 \\cdot 10^{8}}{3{,}75 \\cdot 10^{9}}\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\lambda = 0{,}08\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy sóng điện từ có tần số 3750 MHz có bước sóng là $0{,}08\\ \\text{m}$ (8 cm).</p>","difficultySource":"ai"}}]},{"id":1232830,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":3,"options":["3,72.10<sup>−12</sup> W/m2.","9,76.10<sup>−12</sup> W/m2.","2,44.10<sup>−12</sup> W/m2.","4,88.10<sup>−12</sup> W/m2."],"question":"Một vệ tinh nhân tạo chuyển động ở độ cao 2,02.10<sup>7</sup> m so với mặt đất phát sóng vô tuyến giống nhau theo mọi hướng với công suất bằng 25 kW. Bỏ qua sự hấp thụ sóng của khí quyển, cường độ sóng nhận được bởi một máy thu vô tuyến đặt tại mặt đất do vệ tinh này truyền tới có giá trị lớn nhất bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Kiến thức:</strong> Sóng vô tuyến được phát đẳng hướng từ nguồn điểm, năng lượng trải đều trên mặt cầu bán kính $R$. Cường độ sóng là công suất truyền qua một đơn vị diện tích vuông góc với phương truyền:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{P}{4\\pi R^2}$</p><p class=\"text-base leading-relaxed my-2\">Cường độ lớn nhất ứng với máy thu đặt ngay dưới vệ tinh, khi khoảng cách từ vệ tinh đến máy thu nhỏ nhất, tức bằng độ cao $h$ của vệ tinh (bỏ qua bán kính Trái Đất theo đề).</p><p class=\"text-base leading-relaxed my-2\"><strong>Tóm tắt:</strong> $P = 25\\ \\text{kW} = 2{,}5.10^4\\ \\text{W}$; $R = h = 2{,}02.10^7\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Tính diện tích mặt cầu:</p><p class=\"text-base leading-relaxed my-2\">$4\\pi R^2 = 4\\pi (2{,}02.10^7)^2 \\approx 5{,}128.10^{15}\\ \\text{m}^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I_{max} = \\dfrac{2{,}5.10^4}{5{,}128.10^{15}} \\approx 4{,}88.10^{-12}\\ \\text{W/m}^2$</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Cường độ sóng lớn nhất nhận được tại mặt đất là $4{,}88.10^{-12}$ W/m², chọn đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":864,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":3,"options":["3,72.10<sup>−12</sup> W/m2.","9,76.10<sup>−12</sup> W/m2.","2,44.10<sup>−12</sup> W/m2.","4,88.10<sup>−12</sup> W/m2."],"question":"Một vệ tinh nhân tạo chuyển động ở độ cao 2,02.10<sup>7</sup> m so với mặt đất phát sóng vô tuyến giống nhau theo mọi hướng với công suất bằng 25 kW. Bỏ qua sự hấp thụ sóng của khí quyển, cường độ sóng nhận được bởi một máy thu vô tuyến đặt tại mặt đất do vệ tinh này truyền tới có giá trị lớn nhất bằng","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>Kiến thức:</strong> Sóng vô tuyến được phát đẳng hướng từ nguồn điểm, năng lượng trải đều trên mặt cầu bán kính $R$. Cường độ sóng là công suất truyền qua một đơn vị diện tích vuông góc với phương truyền:</p><p class=\"text-base leading-relaxed my-2\">$I = \\dfrac{P}{4\\pi R^2}$</p><p class=\"text-base leading-relaxed my-2\">Cường độ lớn nhất ứng với máy thu đặt ngay dưới vệ tinh, khi khoảng cách từ vệ tinh đến máy thu nhỏ nhất, tức bằng độ cao $h$ của vệ tinh (bỏ qua bán kính Trái Đất theo đề).</p><p class=\"text-base leading-relaxed my-2\"><strong>Tóm tắt:</strong> $P = 25\\ \\text{kW} = 2{,}5.10^4\\ \\text{W}$; $R = h = 2{,}02.10^7\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Tính diện tích mặt cầu:</p><p class=\"text-base leading-relaxed my-2\">$4\\pi R^2 = 4\\pi (2{,}02.10^7)^2 \\approx 5{,}128.10^{15}\\ \\text{m}^2$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow I_{max} = \\dfrac{2{,}5.10^4}{5{,}128.10^{15}} \\approx 4{,}88.10^{-12}\\ \\text{W/m}^2$</p><p class=\"text-base leading-relaxed my-2\"><strong>Kết luận:</strong> Cường độ sóng lớn nhất nhận được tại mặt đất là $4{,}88.10^{-12}$ W/m², chọn đáp án D.</p>","difficultySource":"ai"}}]},{"id":1236319,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Sóng điện từ","question":"Hãy chọn Đúng (Đ) hoặc Sai (S) cho các phát biểu sau về sóng điện từ.","difficulty":"trung-binh","statements":[{"text":"Sóng điện từ là sóng ngang.","answer":true},{"text":"Sóng điện từ luôn lan truyền với tốc độ 3.10<sup>8</sup> m/s.","answer":false},{"text":"Sóng điện từ không truyền được trong chân không.","answer":false},{"text":"Sóng điện từ có bước sóng λ = 6 m lan truyền trong không khí với tốc độ c = 3.10<sup>8</sup>  m/s, chu kì của sóng này là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218428259-hinh-18.png\" alt=\"Hình 18\" class=\"eq\" style=\"width:85.3px;height:14.7px\" />","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Đúng: sóng điện từ là sóng ngang, vectơ $\\vec E$ và $\\vec B$ vuông góc với phương truyền.</p><p class=\"text-base leading-relaxed my-2\">b) Sai: tốc độ $3\\cdot10^8$ m/s chỉ là trong chân không; trong môi trường vật chất tốc độ nhỏ hơn.</p><p class=\"text-base leading-relaxed my-2\">c) Sai: sóng điện từ truyền được cả trong chân không, đó là điểm khác với sóng cơ.</p><p class=\"text-base leading-relaxed my-2\">d) Đúng: $T=\\dfrac{\\lambda}{c}=\\dfrac{6}{3\\cdot10^8}=2\\cdot10^{-8}$ s, khớp với giá trị trong đề.</p>","difficultySource":"ai"},"ex":[{"exam":868,"idx":20,"el":{"form":"ly_thuyet","type":"true_false","topic":"Sóng điện từ","question":"Hãy chọn Đúng (Đ) hoặc Sai (S) cho các phát biểu sau về sóng điện từ.","difficulty":"trung-binh","statements":[{"text":"Sóng điện từ là sóng ngang.","answer":true},{"text":"Sóng điện từ luôn lan truyền với tốc độ 3.10<sup>8</sup> m/s.","answer":false},{"text":"Sóng điện từ không truyền được trong chân không.","answer":false},{"text":"Sóng điện từ có bước sóng λ = 6 m lan truyền trong không khí với tốc độ c = 3.10<sup>8</sup>  m/s, chu kì của sóng này là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218428259-hinh-18.png\" alt=\"Hình 18\" class=\"eq\" style=\"width:85.3px;height:14.7px\" />","answer":true}],"explanation":"","difficultySource":"ai"}}]},{"id":1236494,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Bước sóng, chu kì, tần số, tốc độ truyền sóng","answer":0,"options":["nhỏ hơn 1500 m/s.","lớn hơn 1500 m/s và nhỏ hơn 1,5.10<sup>6</sup> m/s.","lớn hơn 1,5.10<sup>9</sup> m/s.","lớn hơn 1,5.10<sup>6</sup> m/s và nhỏ hơn 1,5.10<sup>9</sup> m/s."],"question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218435238-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:126.4px;height:auto\" />Để sóng siêu âm có tần số 1,5.10<sup>6</sup> Hz có thể truyền xuyên qua mô của cơ thể người và cho hình ảnh rõ nét thì bước sóng của sóng siêu âm này phải nhỏ hơn 1,0 mm. Tốc độ của sóng siêu âm qua các mô của cơ thể","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng $\\lambda=\\dfrac{v}{f}$ và đề yêu cầu $\\lambda\\lt1{,}0$ mm $=1{,}0\\cdot10^{-3}$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v=\\lambda f\\lt1{,}0\\cdot10^{-3}\\cdot1{,}5\\cdot10^{6}=1500$ m/s.</p><p class=\"text-base leading-relaxed my-2\">Vậy tốc độ siêu âm trong mô phải nhỏ hơn 1500 m/s. Chọn A; B, C, D đều cho các khoảng giá trị lớn hơn 1500 m/s nên sai.</p>","difficultySource":"ai"},"ex":[{"exam":869,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Bước sóng, chu kì, tần số, tốc độ truyền sóng","answer":0,"options":["nhỏ hơn 1500 m/s.","lớn hơn 1500 m/s và nhỏ hơn 1,5.10<sup>6</sup> m/s.","lớn hơn 1,5.10<sup>9</sup> m/s.","lớn hơn 1,5.10<sup>6</sup> m/s và nhỏ hơn 1,5.10<sup>9</sup> m/s."],"question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218435238-hinh-4.jpg\" alt=\"Hình 4\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:126.4px;height:auto\" />Để sóng siêu âm có tần số 1,5.10<sup>6</sup> Hz có thể truyền xuyên qua mô của cơ thể người và cho hình ảnh rõ nét thì bước sóng của sóng siêu âm này phải nhỏ hơn 1,0 mm. Tốc độ của sóng siêu âm qua các mô của cơ thể","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1236944,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nút, bụng sóng và điều kiện có sóng dừng","answer":0,"options":["$AB=2\\lambda$  với (n = 4).","$AB=3\\lambda$  với (n = 6).","$AB=2,25\\lambda$  với (n = 4).","$AB=3,25\\lambda$  với (n = 6)."],"question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218449091-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:239.3px;height:auto\" />Sóng dừng trên một sợi dây đàn hồi được mô tả như Hình bên, bước sóng của sóng trên dây là λ. Khi có sóng dừng trên dây, chiều dài AB bằng<br>ĐÚNG/SAI ĐỀ CHẴN<br>Bài 1. Hình 6.4 là đồ thị li độ - khoảng cách của một sóng truyền dọc trên một sợi dây tại một thời điểm xác định. Cho biết tốc độ truyền sóng trên dây bằng 100 cm/s.<br>a) Khoảng cách giữa 2 đỉnh sóng liên tiếp tương ứng với 1 bước sóng.               Đ<br>b) Bước sóng là  $\\lambda =250cm$     S<br>c) Tần số là f= 4 Hz             Đ<br>d) Sau khoảng thời gian ngắn nhất bằng 0,25 s thì điểm M lại hạ xuống thấp nhất một lần nữa.\t\t\t\tĐ<br>Bài 2. Cho các tia bức xạ: tia tử ngoại, tia Rơn-ghen, tia hồng ngoại, ánh sáng nhìn thấy trong thang của sóng điện từ.<br>a) Sóng điện từ là sóng dọc, truyền được trong chân không.   S<br>b) Trong chân không, các bức xạ được sắp xếp theo thứ tự bước sóng giảm dần là: tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, tia Rơn-ghen. Đ<br>c) Tia Rơn-ghen có tần số nhỏ hơn tần số của tia tử ngoại.  S<br>d) Bước sóng của bức xạ màu da cam trong chân không có vận tốc v = 3.10<sup>8</sup> m/s là 600 nm thì tần số của bức xạ đó là 5.10<sup>14</sup>  Hz.    Đ<br>Bài 3. Trong thí nghiệm giao thoa sóng trên mặt nước, hai nguồn kết hợp A và B dao động cùng pha với tần số f= 15 Hz. Vận tốc truyền sóng trên mặt nước là 45 cm/s.<br>a) Hiện tượng hai sóng gặp nhau tạo nên các gợn sóng không ổn định gọi là hiện tượng giao thoa của hai sóng.    S<br>b) Những điểm nào cách nguồn một khoảng bằng (k+ $\\frac{1}{2}$ )λ thì dao động ngược pha với nguồn.  Đ<br>c) Bước sóng có giá trị 2 cm.           S<br>d) Khoảng cách giữa hai điểm liên tiếp trên đoạn AB dao động với biên độ cực tiểu bằng 1,5 cm       Đ<br>ĐÚNG/SAI ĐỀ LẺ<br>Bài 1. Hình 6.4 là đồ thị li độ - khoảng cách của một sóng truyền dọc trên một sợi dây tại một thời điểm xác định. Cho biết tốc độ truyền sóng trên dây bằng 75 cm/s.<br>a) Khoảng cách giữa 2 đỉnh sóng liên tiếp tương ứng với 2 bước sóng.               S<br>b) Bước sóng là  $\\lambda =25 cm$     Đ<br>c) Tần số là f= 3 Hz      Đ<br>d) Sau khoảng thời gian ngắn nhất bằng 0,83 s thì điểm M lại hạ xuống thấp nhất một lần nữa.\t\t\t\tS<br>Bài 2. Cho các tia bức xạ: tia tử ngoại, tia hồng ngoại, sóng vô tuyến, ánh sáng nhìn thấy trong thang của sóng điện từ.<br>a) Sóng điện từ là sóng ngang, truyền được trong chân không.   Đ<br>b) Trong chân không, các bức xạ được sắp xếp theo thứ tự bước sóng giảm dần là: tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, sóng vô tuyến . S<br>c) Tia hồng ngoại có tần số nhỏ hơn tần số của tia tử ngoại.  Đ<br>d) Bước sóng của bức xạ màu tím trong chân không có vận tốc v = 3.10<sup>8</sup> m/s là 400 nm thì tần số của bức xạ đó là 75  Hz.  S<br>Bài 3. Trong thí nghiệm giao thoa sóng trên mặt nước, hai nguồn kết hợp A và B dao động cùng pha với tần số f= 15 Hz. Vận tốc truyền sóng trên mặt nước là 30 cm/s.<br>a) Hiện tượng hai sóng gặp nhau tạo nên các gợn sóng ổn định gọi là hiện tượng giao thoa của hai sóng.    Đ<br>b) Những điểm nào cách nguồn một khoảng bằng kλ thì dao động ngược pha với nguồn.  S<br>c) Bước sóng có giá trị 2 cm.           Đ<br>d) Khoảng cách giữa hai điểm liên tiếp trên đoạn AB dao động với biên độ cực đại bằng 2 cm.       S<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218450156-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:315.3px;height:auto\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218450156-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:315.3px;height:auto\" />","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Dây có hai đầu A, B cố định: điều kiện sóng dừng $AB = n\\dfrac{\\lambda}{2}$ với $n$ là số bó sóng.</p><p class=\"text-base leading-relaxed my-2\">Đọc hình: giữa A và B có 4 bó sóng (5 nút kể cả hai đầu)</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$n=4$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$AB = 4\\cdot\\dfrac{\\lambda}{2}=2\\lambda$.</p><p class=\"text-base leading-relaxed my-2\">Chọn A. Phương án C ($2{,}25\\lambda$) ứng với một đầu tự do, trái với hình ghi A, B đều cố định.</p>","difficultySource":"ai"},"ex":[{"exam":870,"idx":14,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nút, bụng sóng và điều kiện có sóng dừng","answer":0,"options":["$AB=2\\lambda$  với (n = 4).","$AB=3\\lambda$  với (n = 6).","$AB=2,25\\lambda$  với (n = 4).","$AB=3,25\\lambda$  với (n = 6)."],"question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218449091-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:239.3px;height:auto\" />Sóng dừng trên một sợi dây đàn hồi được mô tả như Hình bên, bước sóng của sóng trên dây là λ. Khi có sóng dừng trên dây, chiều dài AB bằng<br>ĐÚNG/SAI ĐỀ CHẴN<br>Bài 1. Hình 6.4 là đồ thị li độ - khoảng cách của một sóng truyền dọc trên một sợi dây tại một thời điểm xác định. Cho biết tốc độ truyền sóng trên dây bằng 100 cm/s.<br>a) Khoảng cách giữa 2 đỉnh sóng liên tiếp tương ứng với 1 bước sóng.               Đ<br>b) Bước sóng là  $\\lambda =250cm$     S<br>c) Tần số là f= 4 Hz             Đ<br>d) Sau khoảng thời gian ngắn nhất bằng 0,25 s thì điểm M lại hạ xuống thấp nhất một lần nữa.\t\t\t\tĐ<br>Bài 2. Cho các tia bức xạ: tia tử ngoại, tia Rơn-ghen, tia hồng ngoại, ánh sáng nhìn thấy trong thang của sóng điện từ.<br>a) Sóng điện từ là sóng dọc, truyền được trong chân không.   S<br>b) Trong chân không, các bức xạ được sắp xếp theo thứ tự bước sóng giảm dần là: tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, tia Rơn-ghen. Đ<br>c) Tia Rơn-ghen có tần số nhỏ hơn tần số của tia tử ngoại.  S<br>d) Bước sóng của bức xạ màu da cam trong chân không có vận tốc v = 3.10<sup>8</sup> m/s là 600 nm thì tần số của bức xạ đó là 5.10<sup>14</sup>  Hz.    Đ<br>Bài 3. Trong thí nghiệm giao thoa sóng trên mặt nước, hai nguồn kết hợp A và B dao động cùng pha với tần số f= 15 Hz. Vận tốc truyền sóng trên mặt nước là 45 cm/s.<br>a) Hiện tượng hai sóng gặp nhau tạo nên các gợn sóng không ổn định gọi là hiện tượng giao thoa của hai sóng.    S<br>b) Những điểm nào cách nguồn một khoảng bằng (k+ $\\frac{1}{2}$ )λ thì dao động ngược pha với nguồn.  Đ<br>c) Bước sóng có giá trị 2 cm.           S<br>d) Khoảng cách giữa hai điểm liên tiếp trên đoạn AB dao động với biên độ cực tiểu bằng 1,5 cm       Đ<br>ĐÚNG/SAI ĐỀ LẺ<br>Bài 1. Hình 6.4 là đồ thị li độ - khoảng cách của một sóng truyền dọc trên một sợi dây tại một thời điểm xác định. Cho biết tốc độ truyền sóng trên dây bằng 75 cm/s.<br>a) Khoảng cách giữa 2 đỉnh sóng liên tiếp tương ứng với 2 bước sóng.               S<br>b) Bước sóng là  $\\lambda =25 cm$     Đ<br>c) Tần số là f= 3 Hz      Đ<br>d) Sau khoảng thời gian ngắn nhất bằng 0,83 s thì điểm M lại hạ xuống thấp nhất một lần nữa.\t\t\t\tS<br>Bài 2. Cho các tia bức xạ: tia tử ngoại, tia hồng ngoại, sóng vô tuyến, ánh sáng nhìn thấy trong thang của sóng điện từ.<br>a) Sóng điện từ là sóng ngang, truyền được trong chân không.   Đ<br>b) Trong chân không, các bức xạ được sắp xếp theo thứ tự bước sóng giảm dần là: tia hồng ngoại, ánh sáng nhìn thấy, tia tử ngoại, sóng vô tuyến . S<br>c) Tia hồng ngoại có tần số nhỏ hơn tần số của tia tử ngoại.  Đ<br>d) Bước sóng của bức xạ màu tím trong chân không có vận tốc v = 3.10<sup>8</sup> m/s là 400 nm thì tần số của bức xạ đó là 75  Hz.  S<br>Bài 3. Trong thí nghiệm giao thoa sóng trên mặt nước, hai nguồn kết hợp A và B dao động cùng pha với tần số f= 15 Hz. Vận tốc truyền sóng trên mặt nước là 30 cm/s.<br>a) Hiện tượng hai sóng gặp nhau tạo nên các gợn sóng ổn định gọi là hiện tượng giao thoa của hai sóng.    Đ<br>b) Những điểm nào cách nguồn một khoảng bằng kλ thì dao động ngược pha với nguồn.  S<br>c) Bước sóng có giá trị 2 cm.           Đ<br>d) Khoảng cách giữa hai điểm liên tiếp trên đoạn AB dao động với biên độ cực đại bằng 2 cm.       S<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218450156-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:315.3px;height:auto\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218450156-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:315.3px;height:auto\" />","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Dây có hai đầu A, B cố định: điều kiện sóng dừng $AB = n\\dfrac{\\lambda}{2}$ với $n$ là số bó sóng.</p><p class=\"text-base leading-relaxed my-2\">Đọc hình: giữa A và B có 4 bó sóng (5 nút kể cả hai đầu)</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$n=4$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$AB = 4\\cdot\\dfrac{\\lambda}{2}=2\\lambda$.</p><p class=\"text-base leading-relaxed my-2\">Chọn A. Phương án C ($2{,}25\\lambda$) ứng với một đầu tự do, trái với hình ghi A, B đều cố định.</p>","difficultySource":"ai"}}]},{"id":1238744,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":1,"options":["0,12 m đến 0,35 m; Mắt nhìn thấy.","0,12 m đến 0,35 m; Mắt không nhìn thấy.","2,83 m đến 8,67 m; Mắt nhìn thấy.","2,83 m đến 8,67 m; Mắt không nhìn thấy."],"question":"Vào thời điểm năm 2022, điện thoại di động ở Việt Nam sử dụng sóng điện từ có tần số trong khoảng từ 850 MHz đến 2500 MHz. Coi tốc độ của sóng điện từ trong không khí bằng 3.10<sup>8</sup> m/s. Tính bước sóng của sóng điện từ tương ứng với dải tần số này. Mắt chúng ta có thể thấy được các sóng này không?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức $\\lambda = \\dfrac{c}{f}$, trong đó $c = 3\\cdot 10^{8}$ m/s là tốc độ sóng điện từ trong không khí.</p><p class=\"text-base leading-relaxed my-2\">Với $f_1 = 850$ MHz $= 8{,}5\\cdot 10^{8}$ Hz:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda_1 = \\dfrac{3\\cdot 10^{8}}{8{,}5\\cdot 10^{8}} \\approx 0{,}35$ m</p><p class=\"text-base leading-relaxed my-2\">Với $f_2 = 2500$ MHz $= 2{,}5\\cdot 10^{9}$ Hz:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda_2 = \\dfrac{3\\cdot 10^{8}}{2{,}5\\cdot 10^{9}} = 0{,}12$ m</p><p class=\"text-base leading-relaxed my-2\">Vậy bước sóng nằm trong khoảng từ $0{,}12$ m đến $0{,}35$ m.</p><p class=\"text-base leading-relaxed my-2\">Mắt người chỉ nhìn thấy ánh sáng có bước sóng trong khoảng khoảng $380$ nm đến $760$ nm, tức là $(3{,}8$ đến $7{,}6)\\cdot 10^{-7}$ m. Các sóng trên có bước sóng hàng chục cm, lớn hơn rất nhiều so với vùng này, nên mắt không nhìn thấy.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là B.</p>","difficultySource":"ai"},"ex":[{"exam":875,"idx":10,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Ứng dụng sóng điện từ trong truyền thông","answer":1,"options":["0,12 m đến 0,35 m; Mắt nhìn thấy.","0,12 m đến 0,35 m; Mắt không nhìn thấy.","2,83 m đến 8,67 m; Mắt nhìn thấy.","2,83 m đến 8,67 m; Mắt không nhìn thấy."],"question":"Vào thời điểm năm 2022, điện thoại di động ở Việt Nam sử dụng sóng điện từ có tần số trong khoảng từ 850 MHz đến 2500 MHz. Coi tốc độ của sóng điện từ trong không khí bằng 3.10<sup>8</sup> m/s. Tính bước sóng của sóng điện từ tương ứng với dải tần số này. Mắt chúng ta có thể thấy được các sóng này không?","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức $\\lambda = \\dfrac{c}{f}$, trong đó $c = 3\\cdot 10^{8}$ m/s là tốc độ sóng điện từ trong không khí.</p><p class=\"text-base leading-relaxed my-2\">Với $f_1 = 850$ MHz $= 8{,}5\\cdot 10^{8}$ Hz:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda_1 = \\dfrac{3\\cdot 10^{8}}{8{,}5\\cdot 10^{8}} \\approx 0{,}35$ m</p><p class=\"text-base leading-relaxed my-2\">Với $f_2 = 2500$ MHz $= 2{,}5\\cdot 10^{9}$ Hz:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda_2 = \\dfrac{3\\cdot 10^{8}}{2{,}5\\cdot 10^{9}} = 0{,}12$ m</p><p class=\"text-base leading-relaxed my-2\">Vậy bước sóng nằm trong khoảng từ $0{,}12$ m đến $0{,}35$ m.</p><p class=\"text-base leading-relaxed my-2\">Mắt người chỉ nhìn thấy ánh sáng có bước sóng trong khoảng khoảng $380$ nm đến $760$ nm, tức là $(3{,}8$ đến $7{,}6)\\cdot 10^{-7}$ m. Các sóng trên có bước sóng hàng chục cm, lớn hơn rất nhiều so với vùng này, nên mắt không nhìn thấy.</p><p class=\"text-base leading-relaxed my-2\">Đáp án đúng là B.</p>","difficultySource":"ai"}}]},{"id":1238751,"nq":{"form":"bai_tap","type":"true_false","topic":"Năng lượng trong dao động điều hoà","question":"Một con lắc lò xo có vật nặng khối lượng 0,5 kg, dao động điều hoà. Đồ thị vận tốc v theo thời gian t như Hình 5.7","difficulty":"kho","statements":[{"text":"Vận tốc cực đại của vật là 0,3 cm/s.","answer":true},{"text":"Động năng cực đại của vật là 22,5 mJ.","answer":false},{"text":"Cơ năng của con lắc bằng 2,25.10<sup>−6</sup>J.","answer":true},{"text":"Vị trí mà Wđ = 2Wt là x = ±<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218514074-hinh-34.png\" alt=\"Hình 34\" class=\"eq\" style=\"width:38.3px;height:41.7px\" />cm.","answer":false}],"explanation":"","difficultySource":"ai"},"ex":[{"exam":875,"idx":17,"el":{"form":"bai_tap","type":"true_false","topic":"Năng lượng trong dao động điều hoà","question":"Một con lắc lò xo có vật nặng khối lượng 0,5 kg, dao động điều hoà. Đồ thị vận tốc v theo thời gian t như Hình 5.7","difficulty":"kho","statements":[{"text":"Vận tốc cực đại của vật là 0,3 cm/s.","answer":true},{"text":"Động năng cực đại của vật là 22,5 mJ.","answer":false},{"text":"Cơ năng của con lắc bằng 2,25.10<sup>−6</sup>J.","answer":true},{"text":"Vị trí mà Wđ = 2Wt là x = ±<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218514074-hinh-34.png\" alt=\"Hình 34\" class=\"eq\" style=\"width:38.3px;height:41.7px\" />cm.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1247024,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Sóng điện từ","question":"Hình vẽ dưới mô tả sóng điện từ, nêu ý kiến của em về các nhận định sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218714122-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:202.5px;height:auto\" />","difficulty":"kho","statements":[{"text":"Trong quá trình lan truyền, các thành phần véctơ đặc trưng cho điện trường ( $\\vec{E}$ ) và từ trường ( $\\vec{B}$ ) luôn dao dao động cùng pha.","answer":true},{"text":"Xét một phương truyền sóng điện từ có phương thẳng đứng hướng lên. Vào thời điểm t, tại điểm M trên phương truyền nếu vectơ cảm ứng từ đang có độ lớn cực đại và hướng về phía Bắc thì vectơ cường độ điện trường có độ lớn cực đại và hướng về phía Tây.","answer":false},{"text":"Sóng điện từ trong chân không lan truyền với tốc độ c = 3.10<sup>8</sup> m/s, có tần số f = 150 kHz thì bước sóng của sóng điện từ đó là 2 km.","answer":true},{"text":"Hai thành phần điện trường và từ trường có phương vuông góc với nhau và vuông góc với phương truyền sóng  $\\vec{v}$ .","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Trong sóng điện từ, $\\vec E$ và $\\vec B$ tại mỗi điểm luôn dao động cùng pha (hình: cùng đạt cực đại tại cùng vị trí). Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Ba vectơ $\\vec E$, $\\vec B$, $\\vec v$ tạo thành tam diện thuận: $\\vec E \\times \\vec B$ cùng hướng $\\vec v$. Chọn Đông, Bắc, Lên làm ba trục thuận; $\\vec v$ hướng lên, $\\vec B$ hướng Bắc</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\vec E$ hướng Đông, không phải Tây. Sai.</p><p class=\"text-base leading-relaxed my-2\">c) $\\lambda = \\dfrac{c}{f} = \\dfrac{3\\cdot 10^8}{150\\cdot 10^3} = 2000$ m $= 2$ km. Đúng.</p><p class=\"text-base leading-relaxed my-2\">d) Sóng điện từ là sóng ngang: $\\vec E \\perp \\vec B$ và cả hai vuông góc với phương truyền. Đúng.</p>","difficultySource":"ai"},"ex":[{"exam":884,"idx":20,"el":{"form":"ly_thuyet","type":"true_false","topic":"Sóng điện từ","question":"Hình vẽ dưới mô tả sóng điện từ, nêu ý kiến của em về các nhận định sau:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218714122-hinh-2.jpg\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:202.5px;height:auto\" />","difficulty":"kho","statements":[{"text":"Trong quá trình lan truyền, các thành phần véctơ đặc trưng cho điện trường ( $\\vec{E}$ ) và từ trường ( $\\vec{B}$ ) luôn dao dao động cùng pha.","answer":true},{"text":"Xét một phương truyền sóng điện từ có phương thẳng đứng hướng lên. Vào thời điểm t, tại điểm M trên phương truyền nếu vectơ cảm ứng từ đang có độ lớn cực đại và hướng về phía Bắc thì vectơ cường độ điện trường có độ lớn cực đại và hướng về phía Tây.","answer":false},{"text":"Sóng điện từ trong chân không lan truyền với tốc độ c = 3.10<sup>8</sup> m/s, có tần số f = 150 kHz thì bước sóng của sóng điện từ đó là 2 km.","answer":true},{"text":"Hai thành phần điện trường và từ trường có phương vuông góc với nhau và vuông góc với phương truyền sóng  $\\vec{v}$ .","answer":true}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) Trong sóng điện từ, $\\vec E$ và $\\vec B$ tại mỗi điểm luôn dao động cùng pha (hình: cùng đạt cực đại tại cùng vị trí). Đúng.</p><p class=\"text-base leading-relaxed my-2\">b) Ba vectơ $\\vec E$, $\\vec B$, $\\vec v$ tạo thành tam diện thuận: $\\vec E \\times \\vec B$ cùng hướng $\\vec v$. Chọn Đông, Bắc, Lên làm ba trục thuận; $\\vec v$ hướng lên, $\\vec B$ hướng Bắc</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\vec E$ hướng Đông, không phải Tây. Sai.</p><p class=\"text-base leading-relaxed my-2\">c) $\\lambda = \\dfrac{c}{f} = \\dfrac{3\\cdot 10^8}{150\\cdot 10^3} = 2000$ m $= 2$ km. Đúng.</p><p class=\"text-base leading-relaxed my-2\">d) Sóng điện từ là sóng ngang: $\\vec E \\perp \\vec B$ và cả hai vuông góc với phương truyền. Đúng.</p>","difficultySource":"ai"}}]},{"id":1247583,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Li độ, biên độ, chu kì, tần số, pha ban đầu","answer":1,"options":["2,18.10<sup>14</sup> rad/s.","1,80.10<sup>15</sup> rad/s.","4,57.10<sup>14</sup> rad/s.","3,48.10<sup>15</sup> rad/s."],"question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218723053-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:170.7px;height:auto\" />Các nhà thực nghiệm đo được tần số dao động của một hệ gồm thanh silicon siêu nhỏ có virus dính trên đó đang thực hiện dao động là 2,87.10<sup>14</sup> Hz. Tần số góc của hệ dao động trên xấp xỉ bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Tần số góc: $\\omega = 2\\pi f$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\omega = 2\\pi\\cdot 2{,}87\\cdot 10^{14} \\approx 1{,}80\\cdot 10^{15}$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">Chọn B. Phương án D ($3{,}48\\cdot 10^{15}$) không ứng với phép tính nào đúng; A, C sai bậc hoặc hệ số.</p>","difficultySource":"ai"},"ex":[{"exam":885,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Li độ, biên độ, chu kì, tần số, pha ban đầu","answer":1,"options":["2,18.10<sup>14</sup> rad/s.","1,80.10<sup>15</sup> rad/s.","4,57.10<sup>14</sup> rad/s.","3,48.10<sup>15</sup> rad/s."],"question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/118/1791218723053-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:170.7px;height:auto\" />Các nhà thực nghiệm đo được tần số dao động của một hệ gồm thanh silicon siêu nhỏ có virus dính trên đó đang thực hiện dao động là 2,87.10<sup>14</sup> Hz. Tần số góc của hệ dao động trên xấp xỉ bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Tần số góc: $\\omega = 2\\pi f$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$\\omega = 2\\pi\\cdot 2{,}87\\cdot 10^{14} \\approx 1{,}80\\cdot 10^{15}$ rad/s.</p><p class=\"text-base leading-relaxed my-2\">Chọn B. Phương án D ($3{,}48\\cdot 10^{15}$) không ứng với phép tính nào đúng; A, C sai bậc hoặc hệ số.</p>","difficultySource":"ai"}}]},{"id":1248403,"nq":{"form":"bai_tap","type":"true_false","topic":"Đặc điểm và thang sóng điện từ","question":"Sóng điện từ:","difficulty":"kho","statements":[{"text":"Tia tử ngoại được dùng để tìm vết nứt trên bề mặt sản phẩm bằng kim loại.","answer":true},{"text":"Một máy phát sóng vô tuyến AM đẳng hướng trong không gian. Ở khoảng cách 30 km từ máy phát này, ta nhận được sóng có cường độ bằng 4,42.10<sup>−6</sup> W/m2. Máy phát vô tuyến này có công suất bằng  20 kW","answer":false},{"text":"Một sóng vô tuyến có tần số 108 Hz được truyền trong không trung với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng đó là 3 m","answer":true},{"text":"Cơ thể con người có thân nhiệt 37oC là một nguồn phát ra tia tử ngoại.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><b>a) Đúng.</b> Tia tử ngoại có khả năng làm phát quang một số chất, nên được dùng trong kiểm tra không phá hủy để phát hiện vết nứt trên bề mặt sản phẩm bằng kim loại (phương pháp thẩm thấu huỳnh quang).</p><p class=\"text-base leading-relaxed my-2\"><b>b) Sai.</b> Máy phát đẳng hướng nên công suất phân bố đều trên mặt cầu bán kính $r$. Cường độ âm/sóng: $I=\\dfrac{P}{4\\pi r^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$P=I\\cdot 4\\pi r^2$.</p><p class=\"text-base leading-relaxed my-2\">Đổi $r=30\\text{ km}=3.10^4\\text{ m}$, ta có $4\\pi r^2=4\\pi(3.10^4)^2\\approx 1,131.10^{10}\\text{ m}^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow$$P=4,42.10^{-6}\\cdot 1,131.10^{10}\\approx 5.10^4\\text{ W}=50\\text{ kW}$, khác với 20 kW nêu trong đề.</p><p class=\"text-base leading-relaxed my-2\"><b>c) Đúng.</b> Bước sóng: $\\lambda=\\dfrac{v}{f}=\\dfrac{3.10^8}{10^8}=3\\text{ m}$.</p><p class=\"text-base leading-relaxed my-2\"><b>d) Sai.</b> Vật ở nhiệt độ khoảng 37°C (không quá cao) phát ra chủ yếu bức xạ hồng ngoại, không phải tia tử ngoại.</p>","difficultySource":"ai"},"ex":[{"exam":886,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Đặc điểm và thang sóng điện từ","question":"Sóng điện từ:","difficulty":"kho","statements":[{"text":"Tia tử ngoại được dùng để tìm vết nứt trên bề mặt sản phẩm bằng kim loại.","answer":true},{"text":"Một máy phát sóng vô tuyến AM đẳng hướng trong không gian. Ở khoảng cách 30 km từ máy phát này, ta nhận được sóng có cường độ bằng 4,42.10<sup>−6</sup> W/m2. Máy phát vô tuyến này có công suất bằng  20 kW","answer":false},{"text":"Một sóng vô tuyến có tần số 108 Hz được truyền trong không trung với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng đó là 3 m","answer":true},{"text":"Cơ thể con người có thân nhiệt 37oC là một nguồn phát ra tia tử ngoại.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1248678,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":2,"options":["3cm.","4cm.","3<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218744248-hinh-13.png\" alt=\"Hình 13\" class=\"eq\" style=\"width:25px;height:22.3px\" />cm.","4<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218744248-hinh-13.png\" alt=\"Hình 13\" class=\"eq\" style=\"width:25px;height:22.3px\" />cm."],"question":"Hai điện tích điểm q1 =10-9C và q2 = -2.10<sup>−9</sup>C hút nhau bằng 1 lực có độ lớn 10-5N khi đặt trong không khí. Khoảng cách giữa chúng là:","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Coulomb: $F=k\\dfrac{|q_1q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r=\\sqrt{\\dfrac{k|q_1q_2|}{F}}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $r=\\sqrt{\\dfrac{9\\cdot 10^9\\cdot 10^{-9}\\cdot 2\\cdot 10^{-9}}{10^{-5}}}=\\sqrt{1,8\\cdot 10^{-3}}$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r\\approx 0,0424$ m $=3\\sqrt2$ cm.</p><p class=\"text-base leading-relaxed my-2\">Chọn C (A, B, D không khớp kết quả).</p>","difficultySource":"ai"},"ex":[{"exam":701,"idx":15,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Định luật Coulomb","answer":2,"options":["3cm.","4cm.","3<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218744248-hinh-13.png\" alt=\"Hình 13\" class=\"eq\" style=\"width:25px;height:22.3px\" />cm.","4<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218744248-hinh-13.png\" alt=\"Hình 13\" class=\"eq\" style=\"width:25px;height:22.3px\" />cm."],"question":"Hai điện tích điểm q1 =10-9C và q2 = -2.10<sup>−9</sup>C hút nhau bằng 1 lực có độ lớn 10-5N khi đặt trong không khí. Khoảng cách giữa chúng là:","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Định luật Coulomb: $F=k\\dfrac{|q_1q_2|}{r^2}$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r=\\sqrt{\\dfrac{k|q_1q_2|}{F}}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số: $r=\\sqrt{\\dfrac{9\\cdot 10^9\\cdot 10^{-9}\\cdot 2\\cdot 10^{-9}}{10^{-5}}}=\\sqrt{1,8\\cdot 10^{-3}}$ m.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r\\approx 0,0424$ m $=3\\sqrt2$ cm.</p><p class=\"text-base leading-relaxed my-2\">Chọn C (A, B, D không khớp kết quả).</p>","difficultySource":"ai"}}]},{"id":1248701,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Suất điện động và điện trở trong của nguồn","answer":1,"options":["<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750161-hinh-42.png\" alt=\"Hình 42\" class=\"eq\" style=\"width:76px;height:14.4px\" />","<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750320-hinh-43.png\" alt=\"Hình 43\" class=\"eq\" style=\"width:66.4px;height:14.2px\" />","<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750498-hinh-44.png\" alt=\"Hình 44\" class=\"eq\" style=\"width:66.4px;height:14.3px\" />","<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750667-hinh-45.png\" alt=\"Hình 45\" class=\"eq\" style=\"width:64px;height:14px\" />"],"question":"Người ta mắc một bộ <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750872-hinh-37.png\" alt=\"Hình 37\" class=\"eq\" style=\"width:10px;height:16.8px\" /> pin giống nhau song song thì thu được một bộ nguồn có suất điện động <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751038-hinh-38.png\" alt=\"Hình 38\" class=\"eq\" style=\"width:30.4px;height:14.1px\" /> và điện trở trong <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751196-hinh-39.png\" alt=\"Hình 39\" class=\"eq\" style=\"width:32px;height:13.9px\" /> Mỗi pin có suất điện động và điện trở trong là<br>-------------------------------------------<br>--- II. PHẦN TỰ LUẬN (3 điểm)<br>Câu 1 (1 điểm): Hai quả cầu nhỏ có điện tích lần lượt là 4.10<sup>−7</sup> C và 3.10<sup>−8</sup> C tác dụng vào nhau một lực là 0,27 N trong chân không. Cho hệ số tỉ lệ k = 9.10<sup>9</sup> Nm2/C2 . Tính khoảng cách giữa hai quả cầu.<br>Câu 2 (1 điểm): Để bóc một lớp đồng diện tích 4 cm2, dày 12<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751359-hinh-40.png\" alt=\"Hình 40\" class=\"eq\" style=\"width:28px;height:15.1px\" /> trên bề mặt tấm đồng, người ta dùng tấm đồng làm Anốt bình điện phân dung dịch CuSO4. Người ta cho dòng điện chạy qua bình điện phân trong khoảng thời gian 14 phút 25 giây. Biết đương lượng điện hóa của đồng là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751549-hinh-41.png\" alt=\"Hình 41\" class=\"eq\" style=\"width:121.3px;height:18.1px\" />. Khối lượng riêng của đồng là 8900 kg/m3. Tính cường độ dòng điện qua bình điện phân.<br>Câu 3 (0,5 điểm): Trong không khí hai quả cầu nhỏ cùng khối lượng 0,1 g được treo vào một điểm bằng hai sợi dây nhẹ cách điện có độ dài bằng nhau. Cho hai quả cầu nhiễm điện thì chúng đẩy nhau. Khi hai quả cầu cân bằng, hai dây treo hợp với nhau một góc 300. Lấy g = 10 $m/s^2$. Tính độ lớn lực tương tác tĩnh điện giữa hai quả cầu .<br>Câu 4 (0,5 điểm): Cho một mạch điện kín gồm nguồn điện có suất điện động E = 12 V, điện trở trong r = 3 Ω, mạch ngoài gồm điện trở R1 = 6 Ω mắc song song với một điện trở R. Để công suất tiêu thụ trên điện trở R đạt giá trị lớn nhất thì điện trở R phải có giá trị là bao nhiêu?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Ghép song song $n=3$ nguồn giống nhau: $E_b=E$ và $r_b=\\dfrac{r}{n}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow E=E_b=9$ V.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow r=n\\,r_b=3\\cdot 3=9\\ \\Omega$.</p><p class=\"text-base leading-relaxed my-2\">Chọn B ($9$ V; $9\\ \\Omega$). A nhân sai $E$; C, D sai điện trở trong.</p>","difficultySource":"ai"},"ex":[{"exam":701,"idx":27,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Suất điện động và điện trở trong của nguồn","answer":3,"options":["<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750161-hinh-42.png\" alt=\"Hình 42\" class=\"eq\" style=\"width:76px;height:14.4px\" />","<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750320-hinh-43.png\" alt=\"Hình 43\" class=\"eq\" style=\"width:66.4px;height:14.2px\" />","<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750498-hinh-44.png\" alt=\"Hình 44\" class=\"eq\" style=\"width:66.4px;height:14.3px\" />","<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750667-hinh-45.png\" alt=\"Hình 45\" class=\"eq\" style=\"width:64px;height:14px\" />"],"question":"Người ta mắc một bộ <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218750872-hinh-37.png\" alt=\"Hình 37\" class=\"eq\" style=\"width:10px;height:16.8px\" /> pin giống nhau song song thì thu được một bộ nguồn có suất điện động <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751038-hinh-38.png\" alt=\"Hình 38\" class=\"eq\" style=\"width:30.4px;height:14.1px\" /> và điện trở trong <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751196-hinh-39.png\" alt=\"Hình 39\" class=\"eq\" style=\"width:32px;height:13.9px\" /> Mỗi pin có suất điện động và điện trở trong là<br>-------------------------------------------<br>--- II. PHẦN TỰ LUẬN (3 điểm)<br>Câu 1 (1 điểm): Hai quả cầu nhỏ có điện tích lần lượt là 4.10<sup>−7</sup> C và 3.10<sup>−8</sup> C tác dụng vào nhau một lực là 0,27 N trong chân không. Cho hệ số tỉ lệ k = 9.10<sup>9</sup> Nm2/C2 . Tính khoảng cách giữa hai quả cầu.<br>Câu 2 (1 điểm): Để bóc một lớp đồng diện tích 4 cm2, dày 12<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751359-hinh-40.png\" alt=\"Hình 40\" class=\"eq\" style=\"width:28px;height:15.1px\" /> trên bề mặt tấm đồng, người ta dùng tấm đồng làm Anốt bình điện phân dung dịch CuSO4. Người ta cho dòng điện chạy qua bình điện phân trong khoảng thời gian 14 phút 25 giây. Biết đương lượng điện hóa của đồng là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/114/1791218751549-hinh-41.png\" alt=\"Hình 41\" class=\"eq\" style=\"width:121.3px;height:18.1px\" />. Khối lượng riêng của đồng là 8900 kg/m3. Tính cường độ dòng điện qua bình điện phân.<br>Câu 3 (0,5 điểm): Trong không khí hai quả cầu nhỏ cùng khối lượng 0,1 g được treo vào một điểm bằng hai sợi dây nhẹ cách điện có độ dài bằng nhau. Cho hai quả cầu nhiễm điện thì chúng đẩy nhau. Khi hai quả cầu cân bằng, hai dây treo hợp với nhau một góc 300. Lấy g = 10 m/s2. Tính độ lớn lực tương tác tĩnh điện giữa hai quả cầu .<br>Câu 4 (0,5 điểm): Cho một mạch điện kín gồm nguồn điện có suất điện động E = 12 V, điện trở trong r = 3 Ω, mạch ngoài gồm điện trở R1 = 6 Ω mắc song song với một điện trở R. Để công suất tiêu thụ trên điện trở R đạt giá trị lớn nhất thì điện trở R phải có giá trị là bao nhiêu?","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1252682,"nq":{"form":"bai_tap","type":"short_answer","topic":"Đặc điểm và thang sóng điện từ","answer":"1,5","question":"Một sóng vô tuyến có tần số 2.10<sup>8</sup> Hz lan truyền trong không trung với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng này bằng bao nhiêu mét ?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức liên hệ giữa tốc độ truyền sóng, tần số và bước sóng: $v = \\lambda f$, suy ra $\\lambda = \\dfrac{v}{f}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $v = 3.10^{8}\\ \\text{m/s}$ và $f = 2.10^{8}\\ \\text{Hz}$:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\lambda = \\dfrac{3.10^{8}}{2.10^{8}} = 1{,}5\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: bước sóng của sóng vô tuyến này bằng $1{,}5\\ \\text{m}$.</p>","difficultySource":"ai"},"ex":[{"exam":889,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Đặc điểm và thang sóng điện từ","answer":"1,5","question":"Một sóng vô tuyến có tần số 2.10<sup>8</sup> Hz lan truyền trong không trung với tốc độ 3.10<sup>8</sup> m/s. Bước sóng của sóng này bằng bao nhiêu mét ?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức liên hệ giữa tốc độ truyền sóng, tần số và bước sóng: $v = \\lambda f$, suy ra $\\lambda = \\dfrac{v}{f}$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $v = 3.10^{8}\\ \\text{m/s}$ và $f = 2.10^{8}\\ \\text{Hz}$:</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow \\lambda = \\dfrac{3.10^{8}}{2.10^{8}} = 1{,}5\\ \\text{m}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: bước sóng của sóng vô tuyến này bằng $1{,}5\\ \\text{m}$.</p>","difficultySource":"ai"}}]},{"id":1254582,"nq":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"5,93","question":"Một electron di chuyển trong điện trường đều $E$ một đoạn 0,6 cm, từ điểm <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218910663-hinh-4.png\" alt=\"Hình 4\" class=\"eq\" style=\"width:19.3px;height:15.6px\" /> đến điểm <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218910819-hinh-5.png\" alt=\"Hình 5\" class=\"eq\" style=\"width:17.9px;height:17.3px\" /> dọc theo một đường sức điện thì lực điện sinh công 9,6.10<sup>−18</sup> J. Sau đó nó di chuyển tiếp 0,4 cm từ điểm <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218910819-hinh-5.png\" alt=\"Hình 5\" class=\"eq\" style=\"width:17.9px;height:17.3px\" /> đến điểm $P$ theo phương và chiều nói trên thì tốc độ của electron tại $P$ là bao nhiêu (…..x106 m/s) (lấy tròn 2 chữ số thập phân)? Biết rằng tại M, electron không có vận tốc đầu. Bỏ qua tác dụng của trường hấp dẫn. Khối lượng của electron là 9,1.10<sup>−31</sup> kg.","difficulty":"kho","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trường đều nên lực điện không đổi: công của lực điện tỉ lệ với quãng đường dọc đường sức, $A = qEd$ (với $d$ cùng chiều lực).</p><p class=\"text-base leading-relaxed my-2\">$A_{MN} = 9{,}6\\cdot 10^{-18}$ J ứng với $d_{MN} = 0{,}6$ cm. Đoạn tiếp theo $d_{NP} = 0{,}4$ cm nên $A_{NP} = 9{,}6\\cdot 10^{-18}\\cdot\\dfrac{0{,}4}{0{,}6} = 6{,}4\\cdot 10^{-18}$ J.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow A_{MP} = A_{MN} + A_{NP} = 1{,}6\\cdot 10^{-17}$ J.</p><p class=\"text-base leading-relaxed my-2\">Định lí động năng, electron không có vận tốc đầu tại M: $A_{MP} = \\dfrac{1}{2}mv^2 - 0$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow v = \\sqrt{\\dfrac{2A_{MP}}{m}} = \\sqrt{\\dfrac{2\\cdot 1{,}6\\cdot 10^{-17}}{9{,}1\\cdot 10^{-31}}} \\approx 5{,}93\\cdot 10^{6}$ m/s.</p>","difficultySource":"ai"},"ex":[{"exam":823,"idx":15,"el":{"form":"bai_tap","type":"short_answer","topic":"Công của lực điện và thế năng điện","answer":"5,93","question":"Một electron di chuyển trong điện trường đều $E$ một đoạn 0,6 cm, từ điểm <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218910663-hinh-4.png\" alt=\"Hình 4\" class=\"eq\" style=\"width:19.3px;height:15.6px\" /> đến điểm <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218910819-hinh-5.png\" alt=\"Hình 5\" class=\"eq\" style=\"width:17.9px;height:17.3px\" /> dọc theo một đường sức điện thì lực điện sinh công 9,6.10<sup>−18</sup> J. Sau đó nó di chuyển tiếp 0,4 cm từ điểm <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218910819-hinh-5.png\" alt=\"Hình 5\" class=\"eq\" style=\"width:17.9px;height:17.3px\" /> đến điểm $P$ theo phương và chiều nói trên thì tốc độ của electron tại $P$ là bao nhiêu (…..x106 m/s) (lấy tròn 2 chữ số thập phân)? Biết rằng tại M, electron không có vận tốc đầu. Bỏ qua tác dụng của trường hấp dẫn. Khối lượng của electron là 9,1.10<sup>−31</sup> kg.","difficulty":"kho","explanation":"","difficultySource":"ai"}}]},{"id":1255007,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":1,"options":["20 J.","2.10<sup>−3</sup> J.","8.10<sup>−3</sup> J.","0,5 J."],"question":"Một vật nhỏ khối lượng 0,1 kg  dao động điều hòa với biên độ 0,04 m, tần số góc bằng 10 rad/s. Mốc thế năng ở vị trí cân bằng. Khi qua vị trí có li độ x = 0,02 m thì thế năng của vật bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng của con lắc lò xo dao động điều hòa, với mốc thế năng ở vị trí cân bằng, được tính theo công thức: $W_t = \\dfrac{1}{2} m\\omega^2 x^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $m = 0{,}1\\ \\text{kg}$, $\\omega = 10\\ \\text{rad/s}$, $x = 0{,}02\\ \\text{m}$:</p><p class=\"text-base leading-relaxed my-2\">$W_t = \\dfrac{1}{2}\\cdot 0{,}1\\cdot 10^2\\cdot (0{,}02)^2 = 0{,}5\\cdot 0{,}1\\cdot 100\\cdot 4\\cdot 10^{-4} = 2\\cdot 10^{-3}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thế năng của vật khi qua vị trí $x = 0{,}02\\ \\text{m}$ là $2\\cdot 10^{-3}\\ \\text{J}$, chọn đáp án B.</p>","difficultySource":"ai"},"ex":[{"exam":890,"idx":19,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng, thế năng của vật dao động","answer":1,"options":["20 J.","2.10<sup>−3</sup> J.","8.10<sup>−3</sup> J.","0,5 J."],"question":"Một vật nhỏ khối lượng 0,1 kg  dao động điều hòa với biên độ 0,04 m, tần số góc bằng 10 rad/s. Mốc thế năng ở vị trí cân bằng. Khi qua vị trí có li độ x = 0,02 m thì thế năng của vật bằng","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng của con lắc lò xo dao động điều hòa, với mốc thế năng ở vị trí cân bằng, được tính theo công thức: $W_t = \\dfrac{1}{2} m\\omega^2 x^2$.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $m = 0{,}1\\ \\text{kg}$, $\\omega = 10\\ \\text{rad/s}$, $x = 0{,}02\\ \\text{m}$:</p><p class=\"text-base leading-relaxed my-2\">$W_t = \\dfrac{1}{2}\\cdot 0{,}1\\cdot 10^2\\cdot (0{,}02)^2 = 0{,}5\\cdot 0{,}1\\cdot 100\\cdot 4\\cdot 10^{-4} = 2\\cdot 10^{-3}\\ \\text{J}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thế năng của vật khi qua vị trí $x = 0{,}02\\ \\text{m}$ là $2\\cdot 10^{-3}\\ \\text{J}$, chọn đáp án B.</p>","difficultySource":"ai"}}]},{"id":1341437,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng trong dao động điều hoà","answer":3,"options":["30,375.10<sup>10</sup> J","32,018.10<sup>7</sup> J","32,018.10<sup>3</sup> J","30,375.10<sup>6</sup> J"],"question":"Một số tòa nhà cao tầng sử dụng các con lắc nặng trong bộ giảm chấn khối lượng (mass damper) để giảm thiểu sự rung động gây ra bởi gió hay những cơn địa chấn nhỏ. Giả sử vật nặng của con lắc có khối lượng 3,0.10<sup>5</sup> kg, thực hiện dao động điều hòa với tần số góc  $30\\sqrt{10}$  rad/s, biên độ dao động là 15 cm. Hãy xác định thế năng cực đại của hệ con lắc trong bộ giảm chấn khối lượng.","difficulty":"trung-binh","explanation":"<p class=\"text-base leading-relaxed my-2\">Thế năng cực đại của con lắc bằng cơ năng dao động, vì khi vật ở vị trí biên thì động năng bằng 0 và thế năng đạt cực đại:</p><p class=\"text-base leading-relaxed my-2\">$W_{t,max} = W = \\dfrac{1}{2}m\\omega^2A^2$</p><p class=\"text-base leading-relaxed my-2\">Đổi đơn vị: $A = 15\\ \\text{cm} = 0{,}15\\ \\text{m}$, $m = 3{,}0.10^5\\ \\text{kg}$, $\\omega = 30\\sqrt{10}\\ \\text{rad/s}$.</p><p class=\"text-base leading-relaxed my-2\">Ta có $\\omega^2 = (30\\sqrt{10})^2 = 9000\\ \\text{rad}^2/\\text{s}^2$ và $A^2 = 0{,}0225\\ \\text{m}^2$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_{t,max} = \\dfrac{1}{2}\\cdot 3{,}0.10^5 \\cdot 9000 \\cdot 0{,}0225$</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow W_{t,max} = 3{,}0375.10^7\\ \\text{J} = 30{,}375.10^6\\ \\text{J}$</p><p class=\"text-base leading-relaxed my-2\">Kết luận: thế năng cực đại của hệ con lắc là $30{,}375.10^6\\ \\text{J}$, đáp án D.</p>","difficultySource":"ai"},"ex":[{"exam":893,"idx":13,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Năng lượng trong dao động điều hoà","answer":3,"options":["30,375.10<sup>10</sup> J","32,018.10<sup>7</sup> J","32,018.10<sup>3</sup> J","30,375.10<sup>6</sup> J"],"question":"Một số tòa nhà cao tầng sử dụng các con lắc nặng trong bộ giảm chấn khối lượng (mass damper) để giảm thiểu sự rung động gây ra bởi gió hay những cơn địa chấn nhỏ. Giả sử vật nặng của con lắc có khối lượng 3,0.10<sup>5</sup> kg, thực hiện dao động điều hòa với tần số góc  $30\\sqrt{10}$  rad/s, biên độ dao động là 15 cm. Hãy xác định thế năng cực đại của hệ con lắc trong bộ giảm chấn khối lượng.","difficulty":"trung-binh","explanation":"","difficultySource":"ai"}}]},{"id":1346886,"nq":{"form":"ly_thuyet","type":"true_false","topic":"Đặc điểm và thang sóng điện từ","question":"Cho các nhận định sau:","difficulty":"de","statements":[{"text":"Trong chân không, tốc độ sóng ánh sáng có giá trị khoảng 3.10<sup>8</sup> m/s.","answer":true},{"text":"Tia tử ngoại, tia hồng ngoại có cùng bản chất sóng điện từ với ánh sáng nhìn thấy.","answer":true},{"text":"Ánh sáng nhìn thấy chỉ bao gồm bảy màu: đỏ, cam, vàng, lục, lam, chàm, tím.","answer":false},{"text":"Sóng điện từ chỉ truyền được trong môi trường rắn, lỏng, khí.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>a) Đúng.</strong> Trong chân không, sóng điện từ (trong đó có ánh sáng) lan truyền với tốc độ $c \\approx 3\\cdot10^8$ m/s.</p><p class=\"text-base leading-relaxed my-2\"><strong>b) Đúng.</strong> Tia tử ngoại, tia hồng ngoại và ánh sáng nhìn thấy đều là sóng điện từ, chỉ khác nhau về bước sóng (tần số).</p><p class=\"text-base leading-relaxed my-2\"><strong>c) Sai.</strong> Ánh sáng nhìn thấy là một dải liên tục các bước sóng từ khoảng $380$ nm đến $760$ nm, có vô số màu sắc chuyển tiếp. Bảy màu đỏ, cam, vàng, lục, lam, chàm, tím chỉ là cách phân chia quy ước.</p><p class=\"text-base leading-relaxed my-2\"><strong>d) Sai.</strong> Sóng điện từ truyền được cả trong chân không, không cần môi trường vật chất (khác với sóng cơ học).</p>","difficultySource":"ai"},"ex":[{"exam":899,"idx":15,"el":{"form":"ly_thuyet","type":"true_false","topic":"Đặc điểm và thang sóng điện từ","question":"Cho các nhận định sau:","difficulty":"de","statements":[{"text":"Trong chân không, tốc độ sóng ánh sáng có giá trị khoảng 3.10<sup>8</sup> m/s.","answer":true},{"text":"Tia tử ngoại, tia hồng ngoại có cùng bản chất sóng điện từ với ánh sáng nhìn thấy.","answer":true},{"text":"Ánh sáng nhìn thấy chỉ bao gồm bảy màu: đỏ, cam, vàng, lục, lam, chàm, tím.","answer":false},{"text":"Sóng điện từ chỉ truyền được trong môi trường rắn, lỏng, khí.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\"><strong>a) Đúng.</strong> Trong chân không, sóng điện từ (trong đó có ánh sáng) lan truyền với tốc độ $c \\approx 3\\cdot10^8$ m/s.</p><p class=\"text-base leading-relaxed my-2\"><strong>b) Đúng.</strong> Tia tử ngoại, tia hồng ngoại và ánh sáng nhìn thấy đều là sóng điện từ, chỉ khác nhau về bước sóng (tần số).</p><p class=\"text-base leading-relaxed my-2\"><strong>c) Sai.</strong> Ánh sáng nhìn thấy là một dải liên tục các bước sóng từ khoảng $380$ nm đến $760$ nm, có vô số màu sắc chuyển tiếp. Bảy màu đỏ, cam, vàng, lục, lam, chàm, tím chỉ là cách phân chia quy ước.</p><p class=\"text-base leading-relaxed my-2\"><strong>d) Sai.</strong> Sóng điện từ truyền được cả trong chân không, không cần môi trường vật chất (khác với sóng cơ học).</p>","difficultySource":"ai"}}]},{"id":1348465,"nq":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"3900","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791224945005-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:188.1px;height:auto\" />Hai điện cực của bộ phận bugi đánh lửa trong một chiếc ô tô có thể được xem như là hai tấm kim loại phẳng, song song được tích điện trái dấu, cách nhau 1,3 mm (như hình vẽ). Điện trường tồn tại ở khe hở giữa hai điện cực được xem như là đều. Tia lửa điện được tạo ra khi điện trường đạt cường độ 3,0.10<sup>6</sup> V/m. Hiệu điện thế giữa hai điện cực khi tia lửa điện bắt đầu xuất hiện có giá trị bao nhiêu Vôn ?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Điện trường đều giữa hai điện cực: $U=Ed$.</p><p class=\"text-base leading-relaxed my-2\">Đổi $d=1{,}3\\ \\text{mm}=1{,}3\\cdot10^{-3}\\ \\text{m}$, $E=3{,}0\\cdot10^{6}\\ \\text{V/m}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow U=3{,}0\\cdot10^{6}\\cdot1{,}3\\cdot10^{-3}=3900\\ \\text{V}$</p>","difficultySource":"ai"},"ex":[{"exam":900,"idx":13,"el":{"form":"bai_tap","type":"short_answer","topic":"Điện thế, hiệu điện thế và liên hệ U = Ed","answer":"3900","question":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/120/1791224945005-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:188.1px;height:auto\" />Hai điện cực của bộ phận bugi đánh lửa trong một chiếc ô tô có thể được xem như là hai tấm kim loại phẳng, song song được tích điện trái dấu, cách nhau 1,3 mm (như hình vẽ). Điện trường tồn tại ở khe hở giữa hai điện cực được xem như là đều. Tia lửa điện được tạo ra khi điện trường đạt cường độ 3,0.10<sup>6</sup> V/m. Hiệu điện thế giữa hai điện cực khi tia lửa điện bắt đầu xuất hiện có giá trị bao nhiêu Vôn ?","difficulty":"de","explanation":"","difficultySource":"ai"}}]},{"id":1475519,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":1,"options":["0,67.105 Pa.","0,33.105 Pa.","1,5.10<sup>5</sup> Pa.","0,5.105 Pa."],"question":"Một lượng khí lí tưởng chứa trong xi lanh có pit-tông di chuyển không ma sát như hình vẽ. Pit-tông có tiết diện  $S=30 {cm}^2$ . Ban đầu khối khí có thể tích  $V_1=240 {cm}^3$ , áp suất  $p_1={10}^5 Pa$ . Sau đó, ta kéo pit-tông di chuyển chậm sang phải một đoạn 4 cm để nhiệt độ khối khí không đổi. Áp suất khí trong xi lanh khi đó đã giảm đi<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1790617072866-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Do khối khí thực hiện quá trình đẳng nhiệt nên ta có:<br>$p_1.V_1=p_2.V_2$    ${10}^5.240=p_2.\\left(240+30.4\\right)$<br>$p_2\\approx 0,67.{10}^5 Pa$ .<br>Vậy áp suất khối khí giảm đi  ${10}^5-0,67.{10}^5=0,33.{10}^5 Pa$ .","difficultySource":"ai"},"ex":[{"exam":236,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Quá trình đẳng nhiệt và định luật Boyle","answer":1,"options":["0,67.105 Pa.","0,33.105 Pa.","1,5.10<sup>5</sup> Pa.","0,5.105 Pa."],"question":"Một lượng khí lí tưởng chứa trong xi lanh có pit-tông di chuyển không ma sát như hình vẽ. Pit-tông có tiết diện  $S=30 {cm}^2$ . Ban đầu khối khí có thể tích  $V_1=240 {cm}^3$ , áp suất  $p_1={10}^5 Pa$ . Sau đó, ta kéo pit-tông di chuyển chậm sang phải một đoạn 4 cm để nhiệt độ khối khí không đổi. Áp suất khí trong xi lanh khi đó đã giảm đi<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1790617072866-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Do khối khí thực hiện quá trình đẳng nhiệt nên ta có:<br>$p_1.V_1=p_2.V_2$    ${10}^5.240=p_2.\\left(240+30.4\\right)$<br>$p_2\\approx 0,67.{10}^5 Pa$ .<br>Vậy áp suất khối khí giảm đi  ${10}^5-0,67.{10}^5=0,33.{10}^5 Pa$ .","difficultySource":"ai"}}]},{"id":1475584,"nq":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Cung cấp nhiệt lượng 1,5 J cho một khối khí lí tưởng trong một xilanh kín đặt nằm ngang. Chất khí nở ra đẩy pít-tông đi một đoạn 6,0 cm. Biết lực ma sát giữa pít-tông và xilanh có độ lớn là 20,0 N, diện tích tiết diện của pít-tông là 1,0 cm2. Coi pít-tông chuyển động thẳng đều. Trong các phát biểu sau, phát biểu nào là đúng, phát biểu nào là sai?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045263253-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong quá trình dãn nở, áp suất của chất khí là 2,0.10<sup>5</sup> Pa.","answer":true},{"text":"Công của khối khí thực hiện là 1,2 J.","answer":true},{"text":"Độ biến thiên nội năng của khối khí là 0,50 J.","answer":false},{"text":"Thể tích khí trong xilanh tăng 6,0 lít.","answer":false}],"explanation":"a) đúng<br>Áp suất chất khí:  $p=\\frac{F}{S}=\\frac{20,0}{1,0.10^{−4}}=2,0.10^5 N/m^2=2,0.10^5 Pa$<br>b) đúng<br>Do pít-tông chuyển động thẳng đều nên lực đẩy của khối khí tác dụng lên pít-tông cân bằng với lực ma sát giữa pít-tông và xilanh. Độ lớn lực đẩy của khối khí lên pít-tông: F = 20,0 N.<br>c) sai<br>Theo định luật I nhiệt động lực học: U = A + Q.<br>Trường hợp này, hệ thực hiện công và nhận nhiệt nên: A = -1,2 J và Q = 1,5 J.<br>Do đó: U = -1,2+ 1,5 = 0,30 J.<br>d) sai<br>Thể tích khí trong xilanh tăng:<br>V = S.s = (1,0.10<sup>−4</sup> m2).(0,060 m) = 6,0.10<sup>−6</sup> m3 = 6,0 ml.","difficultySource":"ai"},"ex":[{"exam":270,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Vận dụng ΔU = A + Q","question":"Cung cấp nhiệt lượng 1,5 J cho một khối khí lí tưởng trong một xilanh kín đặt nằm ngang. Chất khí nở ra đẩy pít-tông đi một đoạn 6,0 cm. Biết lực ma sát giữa pít-tông và xilanh có độ lớn là 20,0 N, diện tích tiết diện của pít-tông là 1,0 cm2. Coi pít-tông chuyển động thẳng đều. Trong các phát biểu sau, phát biểu nào là đúng, phát biểu nào là sai?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045263253-hinh-6.webp\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Trong quá trình dãn nở, áp suất của chất khí là 2,0.10<sup>5</sup> Pa.","answer":true},{"text":"Công của khối khí thực hiện là 1,2 J.","answer":true},{"text":"Độ biến thiên nội năng của khối khí là 0,50 J.","answer":false},{"text":"Thể tích khí trong xilanh tăng 6,0 lít.","answer":false}],"explanation":"a) đúng<br>Áp suất chất khí:  $p=\\frac{F}{S}=\\frac{20,0}{1,0.10^{−4}}=2,0.10^5 N/m^2=2,0.10^5 Pa$<br>b) đúng<br>Do pít-tông chuyển động thẳng đều nên lực đẩy của khối khí tác dụng lên pít-tông cân bằng với lực ma sát giữa pít-tông và xilanh. Độ lớn lực đẩy của khối khí lên pít-tông: F = 20,0 N.<br>c) sai<br>Theo định luật I nhiệt động lực học: U = A + Q.<br>Trường hợp này, hệ thực hiện công và nhận nhiệt nên: A = -1,2 J và Q = 1,5 J.<br>Do đó: U = -1,2+ 1,5 = 0,30 J.<br>d) sai<br>Thể tích khí trong xilanh tăng:<br>V = S.s = (1,0.10<sup>−4</sup> m2).(0,060 m) = 6,0.10<sup>−6</sup> m3 = 6,0 ml.","difficultySource":"ai"}}]},{"id":1475612,"nq":{"form":"bai_tap","type":"true_false","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","question":"Một khung dây dẫn hình chữ nhật có AB = CD = 5 cm; BC = 8 cm. Khung dây nằm trong từ trường đều có B = 0,15 T, đường sức từ có chiều như hình vẽ. Cường độ dòng điện trong khung dây là 2 A. Khung dây có thể quay quanh trục ∆ nằm trong mặt phẳng khung dây (∆ là đường trung trực của BC).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045281236-hinh-7.webp\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Mỗi cạnh AB và CD chịu tác dụng của lực từ  $\\vec{F}$  có độ lớn là F = 1,5 N.","answer":false},{"text":"Lực từ tác dụng lên đoạn dây AB và CD có phương thẳng đứng.","answer":false},{"text":"Moment ngẫu lực tác dụng lên khung dây có độ lớn là M = F.d = 12.10<sup>−4</sup> N.m.","answer":true},{"text":"Lực từ tác dụng lên hai đoạn dây AB và CD là ngẫu lực làm cho khung dây quay quanh trục ∆.","answer":true}],"explanation":"a) sai<br>a)\tĐổi 5 cm = 0,05 m; 8 cm = 0,08 m.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Mỗi cạnh AB và CD chịu tác dụng của lực từ  $\\vec{F}$  có độ lớn là:<br>𝐹 = 𝐵.𝐼.𝑙.𝑠𝑖𝑛 $\\left(\\vec{B};\\vec{I}\\right)$ = 0,15.2.0,05.𝑠𝑖𝑛 900 = 0,015 𝑁.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>b)\tLực từ tác dụng lên đoạn dây AB và CD có phương vuông góc với mặt phẳng chứa đoạn dây dẫn<br>mang dòng điện và vector cảm ứng từ.<br>c) đúng<br>c)\tMoment ngẫu lực tác dụng lên khung dây có độ lớn là M = F.d = 0,015.0,08 = 12.10<sup>−4</sup> N.m.<br>d) đúng<br>Lực từ tác dụng lên hai đoạn dây AB và CD có cùng phương, ngược chiều, cùng độ lớn và tác dụng lên khung dây ABCD nên chúng là ngẫu lực. Và ngẫu lực có tác dụng làm quay khung dây quanh trục ∆.","difficultySource":"ai"},"ex":[{"exam":272,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Lực từ tác dụng lên khung dây. Ngẫu lực từ","question":"Một khung dây dẫn hình chữ nhật có AB = CD = 5 cm; BC = 8 cm. Khung dây nằm trong từ trường đều có B = 0,15 T, đường sức từ có chiều như hình vẽ. Cường độ dòng điện trong khung dây là 2 A. Khung dây có thể quay quanh trục ∆ nằm trong mặt phẳng khung dây (∆ là đường trung trực của BC).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045281236-hinh-7.webp\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Mỗi cạnh AB và CD chịu tác dụng của lực từ  $\\vec{F}$  có độ lớn là F = 1,5 N.","answer":false},{"text":"Lực từ tác dụng lên đoạn dây AB và CD có phương thẳng đứng.","answer":false},{"text":"Moment ngẫu lực tác dụng lên khung dây có độ lớn là M = F.d = 12.10<sup>−4</sup> N.m.","answer":true},{"text":"Lực từ tác dụng lên hai đoạn dây AB và CD là ngẫu lực làm cho khung dây quay quanh trục ∆.","answer":true}],"explanation":"a) sai<br>a)\tĐổi 5 cm = 0,05 m; 8 cm = 0,08 m.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Mỗi cạnh AB và CD chịu tác dụng của lực từ  $\\vec{F}$  có độ lớn là:<br>𝐹 = 𝐵.𝐼.𝑙.𝑠𝑖𝑛 $\\left(\\vec{B};\\vec{I}\\right)$ = 0,15.2.0,05.𝑠𝑖𝑛 900 = 0,015 𝑁.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>b)\tLực từ tác dụng lên đoạn dây AB và CD có phương vuông góc với mặt phẳng chứa đoạn dây dẫn<br>mang dòng điện và vector cảm ứng từ.<br>c) đúng<br>c)\tMoment ngẫu lực tác dụng lên khung dây có độ lớn là M = F.d = 0,015.0,08 = 12.10<sup>−4</sup> N.m.<br>d) đúng<br>Lực từ tác dụng lên hai đoạn dây AB và CD có cùng phương, ngược chiều, cùng độ lớn và tác dụng lên khung dây ABCD nên chúng là ngẫu lực. Và ngẫu lực có tác dụng làm quay khung dây quanh trục ∆.","difficultySource":"ai"}}]},{"id":1475639,"nq":{"form":"bai_tap","type":"true_false","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","question":"Một máy phát điện xoay chiều một pha tạo ra dòng điện có cường độ biến theo thời gian được cho trong hình vẽ sau.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045309736-hinh-7.webp\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Dòng điện được tạo ra là dòng điện xoay chiều.","answer":true},{"text":"Cường độ dòng điện hiệu dụng có giá trị  $5\\frac{\\sqrt2}{4}A$ .","answer":false},{"text":"Chu kì của dòng điện là 4.10<sup>−3</sup> s $.$","answer":true},{"text":"Phương trình của dòng điện là  $i=5\\cos\\left(\\left(200\\pi t-\\frac{\\pi }{6}\\right)\\right)A.$","answer":false}],"explanation":"a) đúng<br>Vì đồ thị là đường hình sin<br>b) sai<br>Từ đồ thị ta thấy  $I_0=5 A\\rightarrow I=\\frac{I_0}{\\sqrt2}=5\\frac{\\sqrt2}{2}A$<br>c) đúng<br>Từ đồ thị nhận thấy T = 4.10<sup>−3</sup> s<br>d) sai<br>Lúc t = 0, i = 0 và đang tăng nên  $\\varphi_i=-\\frac{\\pi }{2}$","difficultySource":"ai"},"ex":[{"exam":274,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Giá trị hiệu dụng của dòng điện xoay chiều","question":"Một máy phát điện xoay chiều một pha tạo ra dòng điện có cường độ biến theo thời gian được cho trong hình vẽ sau.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045309736-hinh-7.webp\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Dòng điện được tạo ra là dòng điện xoay chiều.","answer":true},{"text":"Cường độ dòng điện hiệu dụng có giá trị  $5\\frac{\\sqrt2}{4}A$ .","answer":false},{"text":"Chu kì của dòng điện là 4.10<sup>−3</sup> s $.$","answer":true},{"text":"Phương trình của dòng điện là  $i=5\\cos\\left(\\left(200\\pi t-\\frac{\\pi }{6}\\right)\\right)A.$","answer":false}],"explanation":"a) đúng<br>Vì đồ thị là đường hình sin<br>b) sai<br>Từ đồ thị ta thấy  $I_0=5 A\\rightarrow I=\\frac{I_0}{\\sqrt2}=5\\frac{\\sqrt2}{2}A$<br>c) đúng<br>Từ đồ thị nhận thấy T = 4.10<sup>−3</sup> s<br>d) sai<br>Lúc t = 0, i = 0 và đang tăng nên  $\\varphi_i=-\\frac{\\pi }{2}$","difficultySource":"ai"}}]},{"id":1475700,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"9,6","question":"Một khung dây phẳng kín gồm 100 vòng dây có diện tích giới hạn 20 cm2. Khung dây đặt trong từ trường đều có độ lớn cảm ứng từ B = 2,4.10<sup>−4</sup> T. Véctơ cảm ứng từ  $\\vec{B}$  hợp với mặt phẳng khung dây một góc 300. Cho từ trường giảm đều đến 0 trong khoảng thời gian 0,025 s. Độ lớn suất điện động cảm ứng xuất hiện trong khung dây trong khoảng thời gian đó là x.10<sup>−4</sup>. Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045404854-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$e_c=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=N\\left|\\frac{\\Delta B}{\\Delta t}\\right|S.cos\\alpha =9,6.10^{-4} V$","difficultySource":"ai"},"ex":[{"exam":282,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"9,6","question":"Một khung dây phẳng kín gồm 100 vòng dây có diện tích giới hạn 20 cm2. Khung dây đặt trong từ trường đều có độ lớn cảm ứng từ B = 2,4.10<sup>−4</sup> T. Véctơ cảm ứng từ  $\\vec{B}$  hợp với mặt phẳng khung dây một góc 300. Cho từ trường giảm đều đến 0 trong khoảng thời gian 0,025 s. Độ lớn suất điện động cảm ứng xuất hiện trong khung dây trong khoảng thời gian đó là x.10<sup>−4</sup>. Giá trị của x là bao nhiêu (làm tròn kết quả đến chữ số phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045404854-hinh-8.webp\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"$e_c=\\left|\\frac{\\Delta \\Phi }{\\Delta t}\\right|=N\\left|\\frac{\\Delta B}{\\Delta t}\\right|S.cos\\alpha =9,6.10^{-4} V$","difficultySource":"ai"}}]},{"id":1475855,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một ấm đun nước có công suất không đổi 2 100 W và có nhiệt kế hiển thị nhiệt độ tức thời của nước trong ấm. Một bạn học sinh dùng ấm này để đun nước với lượng nước có sẵn trong ấm, nhiệt độ hiển thị ban đầu là  $t_0=20℃$ . Sau khoảng thời gian đun  ${}_1=1$  phút thì nhiệt độ của nước tăng lên tới  $t_1=40℃$  và bạn học sinh bắt đầu thêm nước ở nhiệt độ  $t_x$  C ( $t_x<t_1$ ) vào trong ấm (nước được đun liên tục và đảm bảo an toàn về điện). Tại thời điểm  ${}_2=5$  phút thì nhiệt độ của nước đạt  $t_2=60℃$ . Sau khoảng thời gian 5 phút kể từ thời điểm  ${}_2$  thì nước bắt đầu sôi.<br>Hình vẽ bên là đồ thị biểu diễn nhiệt độ của nước trong ấm theo thời gian trong quá trình đun. Bỏ qua sự truyền nhiệt ra môi trường. Quá trình trao đổi nhiệt diễn ra nhanh chóng. Biết nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4 200 J/(kg.K) và 2,3.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045470004-hinh-17.webp\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng do ấm cung cấp từ thời điểm ban đầu đến thời điểm nước bắt đầu sôi là 21 000 J.","answer":false},{"text":"Lượng nước có sẵn trong ấm và lượng nước được thêm vào ấm lần lượt là 2,25 kg và 1,5 kg.","answer":false},{"text":"Nhiệt độ ban đầu của lượng nước được thêm vào ấm là  $t_x=20℃$ .","answer":true},{"text":"Khi nước sôi, bạn học sinh lấy ra 3 kg nước từ ấm. Bạn quên đậy nắp và không ngắt điện nên sau 10 phút nước trong ấm bay hơi hoàn toàn.","answer":false}],"explanation":"a) Sai: nhiệt lượng ấm cung cấp từ đầu (τ=0) đến khi nước bắt đầu sôi (τ=10 phút=600s) là Q=P.t=2100.600=1 260 000 J, không phải 21000 J.<br>b) Sai: từ τ=0 đến $\\tau_1$=1 phút, nước có sẵn m1 nhận nhiệt Q=P.60=126000 J để tăng từ 20°C lên 40°C: 126000=m1.4200.20 ⟹ m1=1,5 kg; từ $\\tau_2$=5 phút đến lúc sôi ($\\tau_3$=10 phút), cả khối nước (m1+m2) nhận nhiệt P.5.60=630000 J để tăng từ 60°C lên 100°C: 630000=(1,5+m2).4200.40 ⟹ m2=2,25 kg — vậy lượng có sẵn là 1,5 kg và lượng thêm vào là 2,25 kg, ngược với thứ tự đề nêu.<br>c) Đúng: từ $\\tau_1$=1 phút đến $\\tau_2$=5 phút, nhiệt lượng cấp P.(5−1).60=504000 J làm m1 tăng từ 40°C lên 60°C và m2 (thêm vào ở tx) tăng từ tx lên 60°C: 504000=1,5.4200.(60−40)+2,25.4200.(60−tx) ⟹ giải ra tx=20°C.<br>d) Sai: sau khi múc ra 3 kg, nước còn lại trong ấm là (1,5+2,25)−3=0,75 kg; thời gian để lượng nước này bay hơi hoàn toàn là t=L.m/P=2,3.10⁶.0,75/2100=5750/7≈13,7 phút, không phải 10 phút như đề nêu.<br>a) sai<br>Nhiệt lượng do ấm cung cấp từ thời điểm ban đầu đến thời điểm nước bắt đầu sôi là:<br>$Q=P.=2100.10.60=1 260 000$  J.<br>b) sai<br>Do bỏ qua sự truyền nhiệt ra môi trường nên nhiệt lượng ấm tỏa ra bằng nhiệt lượng nước thu vào.<br>Trong khoảng thời gian từ  $=0$  đến  ${}_1=1$  phút, ta có:<br>$P.\\left({}_1-\\right)=m_1.c.\\left(t_1-t_0\\right)$<br>$2100.\\left(1.60-0\\right)=m_1.4200.\\left(40-20\\right)$<br>$m_1=1,5$  kg.<br>Lượng nước có sẵn trong ấm là 1,5 kg.<br>Trong khoảng thời gian từ  ${}_2=5$  phút đến thời điểm  ${}_3$  nước trong ấm bắt đầu sôi, ta có:<br>$P.\\left({}_3-{}_2\\right)=\\left(m_1+m_2\\right).c.\\left(100-t_2\\right)$<br>$2100.5.60=\\left(1,5+m_2\\right).4200.\\left(100-60\\right)$<br>$m_2=2,25$  kg.<br>Lượng nước được thêm vào ấm là 2,25 kg.<br>c) đúng<br>Trong khoảng thời gian từ  ${}_1=1$  phút đến  ${}_2=5$  phút, ta có:<br>$P.\\left({}_2-{}_1\\right)=m_1.c.\\left(t_2-t_1\\right)+m_2.c.\\left(t_2-t_x\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$2100.\\left(5.60-1.60\\right)=1,5.4200.\\left(60-40\\right)+2,25.4200.\\left(60-t_x\\right)$<br>$t_x=20℃$ .<br>d) sai<br>Sau khi bạn học sinh lấy ra 3 kg nước thì lượng nước còn lại trong ấm là  $1,5+2,25-3=0,75$  kg.<br>Thời gian để lượng nước còn lại hóa hơi hoàn toàn là:<br>$P.t=L.m$    $2100.t=2,3.{10}^6.0,75$    $t=\\frac{5750}{7}$  s  $\\approx 13,7$  phút.","difficultySource":"ai"},"ex":[{"exam":288,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt dung riêng, nhiệt nóng chảy riêng, nhiệt hoá hơi riêng","question":"Một ấm đun nước có công suất không đổi 2 100 W và có nhiệt kế hiển thị nhiệt độ tức thời của nước trong ấm. Một bạn học sinh dùng ấm này để đun nước với lượng nước có sẵn trong ấm, nhiệt độ hiển thị ban đầu là  $t_0=20℃$ . Sau khoảng thời gian đun  ${}_1=1$  phút thì nhiệt độ của nước tăng lên tới  $t_1=40℃$  và bạn học sinh bắt đầu thêm nước ở nhiệt độ  $t_x$  C ( $t_x<t_1$ ) vào trong ấm (nước được đun liên tục và đảm bảo an toàn về điện). Tại thời điểm  ${}_2=5$  phút thì nhiệt độ của nước đạt  $t_2=60℃$ . Sau khoảng thời gian 5 phút kể từ thời điểm  ${}_2$  thì nước bắt đầu sôi.<br>Hình vẽ bên là đồ thị biểu diễn nhiệt độ của nước trong ấm theo thời gian trong quá trình đun. Bỏ qua sự truyền nhiệt ra môi trường. Quá trình trao đổi nhiệt diễn ra nhanh chóng. Biết nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4 200 J/(kg.K) và 2,3.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045470004-hinh-17.webp\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng do ấm cung cấp từ thời điểm ban đầu đến thời điểm nước bắt đầu sôi là 21 000 J.","answer":false},{"text":"Lượng nước có sẵn trong ấm và lượng nước được thêm vào ấm lần lượt là 2,25 kg và 1,5 kg.","answer":false},{"text":"Nhiệt độ ban đầu của lượng nước được thêm vào ấm là  $t_x=20℃$ .","answer":true},{"text":"Khi nước sôi, bạn học sinh lấy ra 3 kg nước từ ấm. Bạn quên đậy nắp và không ngắt điện nên sau 10 phút nước trong ấm bay hơi hoàn toàn.","answer":false}],"explanation":"a) Sai: nhiệt lượng ấm cung cấp từ đầu (τ=0) đến khi nước bắt đầu sôi (τ=10 phút=600s) là Q=P.t=2100.600=1 260 000 J, không phải 21000 J.<br>b) Sai: từ τ=0 đến $\\tau_1$=1 phút, nước có sẵn m1 nhận nhiệt Q=P.60=126000 J để tăng từ 20°C lên 40°C: 126000=m1.4200.20 ⟹ m1=1,5 kg; từ $\\tau_2$=5 phút đến lúc sôi ($\\tau_3$=10 phút), cả khối nước (m1+m2) nhận nhiệt P.5.60=630000 J để tăng từ 60°C lên 100°C: 630000=(1,5+m2).4200.40 ⟹ m2=2,25 kg — vậy lượng có sẵn là 1,5 kg và lượng thêm vào là 2,25 kg, ngược với thứ tự đề nêu.<br>c) Đúng: từ $\\tau_1$=1 phút đến $\\tau_2$=5 phút, nhiệt lượng cấp P.(5−1).60=504000 J làm m1 tăng từ 40°C lên 60°C và m2 (thêm vào ở tx) tăng từ tx lên 60°C: 504000=1,5.4200.(60−40)+2,25.4200.(60−tx) ⟹ giải ra tx=20°C.<br>d) Sai: sau khi múc ra 3 kg, nước còn lại trong ấm là (1,5+2,25)−3=0,75 kg; thời gian để lượng nước này bay hơi hoàn toàn là t=L.m/P=2,3.10⁶.0,75/2100=5750/7≈13,7 phút, không phải 10 phút như đề nêu.<br>a) sai<br>Nhiệt lượng do ấm cung cấp từ thời điểm ban đầu đến thời điểm nước bắt đầu sôi là:<br>$Q=P.=2100.10.60=1 260 000$  J.<br>b) sai<br>Do bỏ qua sự truyền nhiệt ra môi trường nên nhiệt lượng ấm tỏa ra bằng nhiệt lượng nước thu vào.<br>Trong khoảng thời gian từ  $=0$  đến  ${}_1=1$  phút, ta có:<br>$P.\\left({}_1-\\right)=m_1.c.\\left(t_1-t_0\\right)$<br>$2100.\\left(1.60-0\\right)=m_1.4200.\\left(40-20\\right)$<br>$m_1=1,5$  kg.<br>Lượng nước có sẵn trong ấm là 1,5 kg.<br>Trong khoảng thời gian từ  ${}_2=5$  phút đến thời điểm  ${}_3$  nước trong ấm bắt đầu sôi, ta có:<br>$P.\\left({}_3-{}_2\\right)=\\left(m_1+m_2\\right).c.\\left(100-t_2\\right)$<br>$2100.5.60=\\left(1,5+m_2\\right).4200.\\left(100-60\\right)$<br>$m_2=2,25$  kg.<br>Lượng nước được thêm vào ấm là 2,25 kg.<br>c) đúng<br>Trong khoảng thời gian từ  ${}_1=1$  phút đến  ${}_2=5$  phút, ta có:<br>$P.\\left({}_2-{}_1\\right)=m_1.c.\\left(t_2-t_1\\right)+m_2.c.\\left(t_2-t_x\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$2100.\\left(5.60-1.60\\right)=1,5.4200.\\left(60-40\\right)+2,25.4200.\\left(60-t_x\\right)$<br>$t_x=20℃$ .<br>d) sai<br>Sau khi bạn học sinh lấy ra 3 kg nước thì lượng nước còn lại trong ấm là  $1,5+2,25-3=0,75$  kg.<br>Thời gian để lượng nước còn lại hóa hơi hoàn toàn là:<br>$P.t=L.m$    $2100.t=2,3.{10}^6.0,75$    $t=\\frac{5750}{7}$  s  $\\approx 13,7$  phút.","difficultySource":"ai"}}]},{"id":1475857,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây dẫn hình tròn đường kính 5 cm được đặt trong vùng từ trường đều có các đường sức từ vuông góc với mặt phẳng khung dây. Hai đầu của dây được nối với một bóng đèn nhỏ tạo thành mạch kín (đèn không bị hư). Biết điện trở của khung dây dẫn và bóng đèn lần lượt là  $R_1=1$  Ω và  $R_2=0,5$  Ω. Tại thời điểm ban đầu (t = 0 s), người ta bắt đầu thay đổi độ lớn cảm ứng từ theo đồ thị như hình bên.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045470392-hinh-19.webp\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Tại thời điểm t = 0 s, không có từ thông xuyên qua tiết diện của khung dây dẫn.","answer":true},{"text":"Tổng thời gian đèn sáng trong quá trình thay đổi độ lớn cảm ứng từ nói trên là 5 s.","answer":false},{"text":"Độ sáng của đèn trong khoảng thời gian từ t = 0 s đến t = 1 s mạnh hơn độ sáng của đèn trong khoảng thời gian từ t = 3 s đến t = 4 s.","answer":true},{"text":"Nhiệt lượng tỏa ra trên bóng đèn trong một giây cuối cùng của quá trình thay đổi độ lớn cảm ứng từ xấp xỉ bằng 1,1.10<sup>7</sup> J.","answer":false}],"explanation":"a) Đúng: từ thông Φ = N.B.S.cos(n̂,B); tại t=0 s, theo đồ thị B=0 nên Φ=0, tức không có từ thông xuyên qua tiết diện khung dây.<br>b) Sai: đèn chỉ sáng khi có dòng điện cảm ứng, tức khi B thay đổi theo thời gian; theo đồ thị, B thay đổi trong khoảng 0-1s và 3-5s (tổng 3s), còn từ 1-3s B không đổi nên không có dòng điện, đèn tắt — vậy tổng thời gian đèn sáng là 3s, không phải 5s.<br>c) Đúng: suất điện động cảm ứng tỉ lệ với tốc độ biến thiên |ΔB/Δt|; trong khoảng 0-1s, B tăng từ 0 lên 500 mT nên |ΔB/Δt|=500 mT/s, lớn hơn trong khoảng 3-4s (B giảm từ 500 mT xuống 150 mT nên |ΔB/Δt|=350 mT/s); do đó độ sáng đèn trong 0-1s mạnh hơn trong 3-4s.<br>d) Sai: trong giây cuối (4s→5s), B giảm từ 150 mT về 0 nên |ΔB|=150 mT; suất điện động ec=N.|ΔB|.S/Δt=1.150.10⁻³.(π.0,05²/4)/1=3π/32000 V; dòng điện i=ec/(R1+R2)=(3π/32000)/1,5=π/16000 A; nhiệt lượng toả ra trên bóng đèn Q=i².R2.t=(π/16000)².0,5.1≈1,93.10⁻⁸ J, không phải 1,1.10⁻⁷ J như đề nêu.<br>a) đúng<br>Từ thông xuyên qua tiết diện S của khung dây dẫn là  $=NBS.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)$<br>Tại thời điểm  $t=0$  s, ta có  $B=0$  T nên  $=0$  Wb.<br>Vậy tại thời điểm  $t=0$  s, không có từ thông xuyên qua tiết diện của khung dây dẫn.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Khi độ lớn cảm ứng từ của từ trường thay đổi thì từ thông xuyên qua tiết diện của khung dây dẫn biến thiên và sinh ra dòng điện cảm ứng trong khung dây làm cho đèn sáng.<br>Dựa vào đồ thị đã cho ta xác định được tổng thời gian đèn sáng trong quá trình thay đổi độ lớn cảm ứng từ đã cho là 3 s.<br>c) đúng<br>Diện tích khung dây dẫn là  $S=\\frac{\\pi .d^2}{4}=\\frac{\\pi .{0,05}^2}{4}=\\frac{\\pi }{1600}$  m2.<br>Trong khoảng thời gian từ  $t=0$  s đến  $t=1$  s, suất điện động cảm ứng và cường độ dòng điện sinh ra trong khung dây dẫn có độ lớn lần lượt là:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{1.500.{10}^{-3}.\\frac{\\pi }{1600}.\\cos\\left(0^{\\circ}\\right)}{1}\\right|=\\frac{\\pi }{3200}$  (V).<br>và  $\\left|i_1\\right|=\\frac{\\left|e_c\\right|}{R_1+R_2}=\\frac{\\frac{\\pi }{3200}}{1+0,5}=\\frac{\\pi }{4800}$  (A).<br>Trong khoảng thời gian từ  $t=3$  s đến  $t=4$  s, suất điện động cảm ứng và cường độ dòng điện sinh ra trong khung dây dẫn có độ lớn lần lượt là:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{1.\\left(-350\\right).{10}^{-3}.\\frac{\\pi }{1600}.\\cos\\left(0^{\\circ}\\right)}{1}\\right|=\\frac{7\\pi }{32000}$  (V).<br>và  $\\left|i_2\\right|=\\frac{\\left|e_c\\right|}{R_1+R_2}=\\frac{\\frac{7\\pi }{32000}}{1+0,5}=\\frac{7}{10}.\\frac{\\pi }{4800}$  (A).<br>Do  $\\left|i_1\\right|>\\left|i_2\\right|$  nên độ sáng của đèn trong khoảng thời gian từ t = 0 s đến t = 1 s mạnh hơn độ sáng của đèn trong khoảng thời gian từ t = 3 s đến t = 4 s.<br>d) sai<br>Cường độ dòng điện cảm ứng sinh ra trong khung dây dẫn ở 1 giây cuối có độ lớn là:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{1.\\left(-150\\right).{10}^{-3}.\\frac{\\pi }{1600}.\\cos\\left(0^{\\circ}\\right)}{1}\\right|=\\frac{3\\pi }{32000}$  (V).<br>$\\left|i_3\\right|=\\frac{\\left|e_c\\right|}{R_1+R_2}=\\frac{\\frac{3\\pi }{32000}}{1+0,5}=\\frac{\\pi }{16000}$  (A).<br>Nhiệt lượng tỏa ra trên bóng đèn trong một giây cuối cùng của quá trình thay đổi độ lớn cảm ứng từ là:<br>$Q={\\left|i_3\\right|}^2.R_2.t={\\left(\\frac{\\pi }{16000}\\right)}^2.0,5.1\\approx 1,93.{10}^{-8}$  (J).","difficultySource":"ai"},"ex":[{"exam":288,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Faraday và định luật Lenz","question":"Một khung dây dẫn hình tròn đường kính 5 cm được đặt trong vùng từ trường đều có các đường sức từ vuông góc với mặt phẳng khung dây. Hai đầu của dây được nối với một bóng đèn nhỏ tạo thành mạch kín (đèn không bị hư). Biết điện trở của khung dây dẫn và bóng đèn lần lượt là  $R_1=1$  Ω và  $R_2=0,5$  Ω. Tại thời điểm ban đầu (t = 0 s), người ta bắt đầu thay đổi độ lớn cảm ứng từ theo đồ thị như hình bên.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045470392-hinh-19.webp\" alt=\"Hình 19\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Tại thời điểm t = 0 s, không có từ thông xuyên qua tiết diện của khung dây dẫn.","answer":true},{"text":"Tổng thời gian đèn sáng trong quá trình thay đổi độ lớn cảm ứng từ nói trên là 5 s.","answer":false},{"text":"Độ sáng của đèn trong khoảng thời gian từ t = 0 s đến t = 1 s mạnh hơn độ sáng của đèn trong khoảng thời gian từ t = 3 s đến t = 4 s.","answer":true},{"text":"Nhiệt lượng tỏa ra trên bóng đèn trong một giây cuối cùng của quá trình thay đổi độ lớn cảm ứng từ xấp xỉ bằng 1,1.10<sup>7</sup> J.","answer":false}],"explanation":"a) Đúng: từ thông Φ = N.B.S.cos(n̂,B); tại t=0 s, theo đồ thị B=0 nên Φ=0, tức không có từ thông xuyên qua tiết diện khung dây.<br>b) Sai: đèn chỉ sáng khi có dòng điện cảm ứng, tức khi B thay đổi theo thời gian; theo đồ thị, B thay đổi trong khoảng 0-1s và 3-5s (tổng 3s), còn từ 1-3s B không đổi nên không có dòng điện, đèn tắt — vậy tổng thời gian đèn sáng là 3s, không phải 5s.<br>c) Đúng: suất điện động cảm ứng tỉ lệ với tốc độ biến thiên |ΔB/Δt|; trong khoảng 0-1s, B tăng từ 0 lên 500 mT nên |ΔB/Δt|=500 mT/s, lớn hơn trong khoảng 3-4s (B giảm từ 500 mT xuống 150 mT nên |ΔB/Δt|=350 mT/s); do đó độ sáng đèn trong 0-1s mạnh hơn trong 3-4s.<br>d) Sai: trong giây cuối (4s→5s), B giảm từ 150 mT về 0 nên |ΔB|=150 mT; suất điện động ec=N.|ΔB|.S/Δt=1.150.10⁻³.(π.0,05²/4)/1=3π/32000 V; dòng điện i=ec/(R1+R2)=(3π/32000)/1,5=π/16000 A; nhiệt lượng toả ra trên bóng đèn Q=i².R2.t=(π/16000)².0,5.1≈1,93.10⁻⁸ J, không phải 1,1.10⁻⁷ J như đề nêu.<br>a) đúng<br>Từ thông xuyên qua tiết diện S của khung dây dẫn là  $=NBS.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)$<br>Tại thời điểm  $t=0$  s, ta có  $B=0$  T nên  $=0$  Wb.<br>Vậy tại thời điểm  $t=0$  s, không có từ thông xuyên qua tiết diện của khung dây dẫn.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>b) sai<br>Khi độ lớn cảm ứng từ của từ trường thay đổi thì từ thông xuyên qua tiết diện của khung dây dẫn biến thiên và sinh ra dòng điện cảm ứng trong khung dây làm cho đèn sáng.<br>Dựa vào đồ thị đã cho ta xác định được tổng thời gian đèn sáng trong quá trình thay đổi độ lớn cảm ứng từ đã cho là 3 s.<br>c) đúng<br>Diện tích khung dây dẫn là  $S=\\frac{\\pi .d^2}{4}=\\frac{\\pi .{0,05}^2}{4}=\\frac{\\pi }{1600}$  m2.<br>Trong khoảng thời gian từ  $t=0$  s đến  $t=1$  s, suất điện động cảm ứng và cường độ dòng điện sinh ra trong khung dây dẫn có độ lớn lần lượt là:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{1.500.{10}^{-3}.\\frac{\\pi }{1600}.\\cos\\left(0^{\\circ}\\right)}{1}\\right|=\\frac{\\pi }{3200}$  (V).<br>và  $\\left|i_1\\right|=\\frac{\\left|e_c\\right|}{R_1+R_2}=\\frac{\\frac{\\pi }{3200}}{1+0,5}=\\frac{\\pi }{4800}$  (A).<br>Trong khoảng thời gian từ  $t=3$  s đến  $t=4$  s, suất điện động cảm ứng và cường độ dòng điện sinh ra trong khung dây dẫn có độ lớn lần lượt là:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{1.\\left(-350\\right).{10}^{-3}.\\frac{\\pi }{1600}.\\cos\\left(0^{\\circ}\\right)}{1}\\right|=\\frac{7\\pi }{32000}$  (V).<br>và  $\\left|i_2\\right|=\\frac{\\left|e_c\\right|}{R_1+R_2}=\\frac{\\frac{7\\pi }{32000}}{1+0,5}=\\frac{7}{10}.\\frac{\\pi }{4800}$  (A).<br>Do  $\\left|i_1\\right|>\\left|i_2\\right|$  nên độ sáng của đèn trong khoảng thời gian từ t = 0 s đến t = 1 s mạnh hơn độ sáng của đèn trong khoảng thời gian từ t = 3 s đến t = 4 s.<br>d) sai<br>Cường độ dòng điện cảm ứng sinh ra trong khung dây dẫn ở 1 giây cuối có độ lớn là:<br>$\\left|e_c\\right|=\\left|-\\frac{\\Delta }{\\Delta t}\\right|=\\left|-\\frac{N.\\Delta B.S.\\cos\\left(\\left(\\vec{n};\\vec{B}\\right)\\right)}{\\Delta t}\\right|=\\left|-\\frac{1.\\left(-150\\right).{10}^{-3}.\\frac{\\pi }{1600}.\\cos\\left(0^{\\circ}\\right)}{1}\\right|=\\frac{3\\pi }{32000}$  (V).<br>$\\left|i_3\\right|=\\frac{\\left|e_c\\right|}{R_1+R_2}=\\frac{\\frac{3\\pi }{32000}}{1+0,5}=\\frac{\\pi }{16000}$  (A).<br>Nhiệt lượng tỏa ra trên bóng đèn trong một giây cuối cùng của quá trình thay đổi độ lớn cảm ứng từ là:<br>$Q={\\left|i_3\\right|}^2.R_2.t={\\left(\\frac{\\pi }{16000}\\right)}^2.0,5.1\\approx 1,93.{10}^{-8}$  (J).","difficultySource":"ai"}}]},{"id":1475995,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một bạn học sinh dùng ấm điện có công suất điện không thay đổi để đun hỗn hợp gồm nước và nước đá có nhiệt độ 0 °C, có khối lượng là 2 kg. Khảo sát sự thay đổi nhiệt độ của hỗn hợp nước và nước đá theo nhiệt lượng mà ấm điện cung cấp, thu được đồ thị như hình bên dưới. Bạn đo được khoảng thời gian từ thời điểm bắt đầu đun đến khi nhiệt độ của hỗn hợp bắt đầu tăng lên là 67 giây. Bỏ qua sự truyền nhiệt ra môi trường và ấm; bỏ qua sự bay hơi của nước trong quá trình đun. Biết nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg và nhiệt dung riêng của nước và nước đá lần lượt là 4200 J/(kg.K) và 2100 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045533927-hinh-17.webp\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước có trong hỗn hợp ban đầu là 0,2 kg.","answer":false},{"text":"Công suất của ấm điện xấp xỉ bằng 1 000 W.","answer":true},{"text":"Kể từ thời điểm bắt đầu đun, sau khoảng 13 phút thì nước trong ấm điện bắt đầu sôi.","answer":false},{"text":"Tại thời điểm nước bắt đầu sôi, bạn học sinh ngắt điện và bỏ thêm vào ấm 250 g nước đá ở  5 C. Nhiệt độ của hỗn hợp khi có sự cân bằng nhiệt xảy ra xấp xỉ bằng 80 C.","answer":true}],"explanation":"a) sai<br>Do bỏ qua sự truyền nhiệt ra môi trường và ấm nên nhiệt lượng mà ấm cung cấp bằng nhiệt lượng nước và nước đá thu vào.<br>Xét đoạn OA, lượng nước đá trong hỗn hợp nhận nhiệt lượng để nóng chảy và chuyển hoàn toàn sang thể lỏng. Ta có:<br>$Q_{OA}=.m_đ$    $m_đ=\\frac{Q_{OA}}{}=\\frac{66,8.{10}^3}{3,34.{10}^5}=0,2$  kg.<br>Khối lượng nước có trong hỗn hợp ban đầu là:  $2-0,2=1,8$  kg.<br>b) đúng<br>Do khoảng thời gian từ thời điểm bắt đầu đun đến khi nhiệt độ của hỗn hợp bắt đầu tăng lên là 67 giây nên ta có:<br>$Q_{OA}=P.t_{OA}$    $P=\\frac{Q_{OA}}{t_{OA}}=\\frac{66,8.{10}^3}{67}\\approx 1 000$  W.<br>c) sai<br>Trong khoảng thời gian từ thời điểm bắt đầu đun đến khi nước bắt đầu sôi, ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=Q_{OA}+m_{hh}.c_n.\\Delta T=P.t$    $66,8.{10}^3+2.4200.100=1000.t$    $t=906,8 s\\approx 15$  phút.<br>d) sai<br>Áp dụng phương trình cân bằng nhiệt, ta có:<br>$m_{hh}.c_n.\\left(100-t_{cb}\\right)=m_{đ2}.c_đ.\\left[0-\\left(-5\\right)\\right]+.m_{đ2}+m_{đ2}.c_n.\\left(t_{cb}-0\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$2.4200.\\left(100-t_{cb}\\right)=0,25.2100.5+3,34.{10}^5.0,25+0,25.4200.t_{cb}$<br>$t_{cb}\\approx 80 ℃$ .","difficultySource":"ai"},"ex":[{"exam":293,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một bạn học sinh dùng ấm điện có công suất điện không thay đổi để đun hỗn hợp gồm nước và nước đá có nhiệt độ 0 °C, có khối lượng là 2 kg. Khảo sát sự thay đổi nhiệt độ của hỗn hợp nước và nước đá theo nhiệt lượng mà ấm điện cung cấp, thu được đồ thị như hình bên dưới. Bạn đo được khoảng thời gian từ thời điểm bắt đầu đun đến khi nhiệt độ của hỗn hợp bắt đầu tăng lên là 67 giây. Bỏ qua sự truyền nhiệt ra môi trường và ấm; bỏ qua sự bay hơi của nước trong quá trình đun. Biết nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg và nhiệt dung riêng của nước và nước đá lần lượt là 4200 J/(kg.K) và 2100 J/(kg.K).<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045533927-hinh-17.webp\" alt=\"Hình 17\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng nước có trong hỗn hợp ban đầu là 0,2 kg.","answer":false},{"text":"Công suất của ấm điện xấp xỉ bằng 1 000 W.","answer":true},{"text":"Kể từ thời điểm bắt đầu đun, sau khoảng 13 phút thì nước trong ấm điện bắt đầu sôi.","answer":false},{"text":"Tại thời điểm nước bắt đầu sôi, bạn học sinh ngắt điện và bỏ thêm vào ấm 250 g nước đá ở  5 C. Nhiệt độ của hỗn hợp khi có sự cân bằng nhiệt xảy ra xấp xỉ bằng 80 C.","answer":true}],"explanation":"a) sai<br>Do bỏ qua sự truyền nhiệt ra môi trường và ấm nên nhiệt lượng mà ấm cung cấp bằng nhiệt lượng nước và nước đá thu vào.<br>Xét đoạn OA, lượng nước đá trong hỗn hợp nhận nhiệt lượng để nóng chảy và chuyển hoàn toàn sang thể lỏng. Ta có:<br>$Q_{OA}=.m_đ$    $m_đ=\\frac{Q_{OA}}{}=\\frac{66,8.{10}^3}{3,34.{10}^5}=0,2$  kg.<br>Khối lượng nước có trong hỗn hợp ban đầu là:  $2-0,2=1,8$  kg.<br>b) đúng<br>Do khoảng thời gian từ thời điểm bắt đầu đun đến khi nhiệt độ của hỗn hợp bắt đầu tăng lên là 67 giây nên ta có:<br>$Q_{OA}=P.t_{OA}$    $P=\\frac{Q_{OA}}{t_{OA}}=\\frac{66,8.{10}^3}{67}\\approx 1 000$  W.<br>c) sai<br>Trong khoảng thời gian từ thời điểm bắt đầu đun đến khi nước bắt đầu sôi, ta có:<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q=Q_{OA}+m_{hh}.c_n.\\Delta T=P.t$    $66,8.{10}^3+2.4200.100=1000.t$    $t=906,8 s\\approx 15$  phút.<br>d) sai<br>Áp dụng phương trình cân bằng nhiệt, ta có:<br>$m_{hh}.c_n.\\left(100-t_{cb}\\right)=m_{đ2}.c_đ.\\left[0-\\left(-5\\right)\\right]+.m_{đ2}+m_{đ2}.c_n.\\left(t_{cb}-0\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$2.4200.\\left(100-t_{cb}\\right)=0,25.2100.5+3,34.{10}^5.0,25+0,25.4200.t_{cb}$<br>$t_{cb}\\approx 80 ℃$ .","difficultySource":"ai"}}]},{"id":1476080,"nq":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một mol khí Helium chứa trong một xilanh đậy kín bởi một pittong (pittong có thể dịch chuyển không ma sát). Khối khí thực hiện quá trình biến đổi trạng thái từ (1) → (2) → (3) theo đồ thị hình bên. Biết rằng ở trạng thái (1), khối khí có thể tích 10.10<sup>−3</sup> m3 và áp suất 6.10<sup>5</sup> Pa. Ở trạng thái (2), khối khí có thể tích 30.10<sup>−3</sup> m3 và áp suất 2.10<sup>5</sup> Pa<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045569053-hinh-11.webp\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình từ (1) đến (2) là quá trình đẳng nhiệt.","answer":false},{"text":"Quá trình từ (2) đến (3) là quá trình đẳng áp.","answer":true},{"text":"Nhiệt độ ở trạng thái (2) của khối khí xấp xỉ bằng 722 K.","answer":true},{"text":"Công mà khối khí nhận được trong quá trình biến đổi trạng thái (2) → (3) xấp xỉ 5933 J.","answer":false}],"explanation":"a) sai<br>Quá trình từ (1) đến (2) là quá trình đẳng nhiệt.<br>$\\Rightarrow$  Đường hypebol (không phải là đường thẳng)<br>b) đúng<br>Quá trình từ (2) đến (3) là quá trình đẳng áp.<br>c) đúng<br>$p_2.V_2=8,31.T_2$<br>$\\Rightarrow 2.10^5.30.10^{−3}=8,31.T_2$<br>$\\Rightarrow T_2=722\\left(K\\right)$<br>d) sai<br>$\\frac{2}{6}=\\frac{V_3}{10}\\Rightarrow V_3=\\frac{10}{3}.10^{−3}\\left(m^3\\right)$<br>$\\Rightarrow A=p.\\left(V_3−V_2\\right)=10^5\\left(\\frac{10}{3}.10^{−3}.30.10^{−3}\\right)=5333,33\\left(J\\right)$","difficultySource":"ai"},"ex":[{"exam":296,"idx":19,"el":{"form":"bai_tap","type":"true_false","topic":"Đọc đồ thị các đẳng quá trình","question":"Một mol khí Helium chứa trong một xilanh đậy kín bởi một pittong (pittong có thể dịch chuyển không ma sát). Khối khí thực hiện quá trình biến đổi trạng thái từ (1) → (2) → (3) theo đồ thị hình bên. Biết rằng ở trạng thái (1), khối khí có thể tích 10.10<sup>−3</sup> m3 và áp suất 6.10<sup>5</sup> Pa. Ở trạng thái (2), khối khí có thể tích 30.10<sup>−3</sup> m3 và áp suất 2.10<sup>5</sup> Pa<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045569053-hinh-11.webp\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Quá trình từ (1) đến (2) là quá trình đẳng nhiệt.","answer":false},{"text":"Quá trình từ (2) đến (3) là quá trình đẳng áp.","answer":true},{"text":"Nhiệt độ ở trạng thái (2) của khối khí xấp xỉ bằng 722 K.","answer":true},{"text":"Công mà khối khí nhận được trong quá trình biến đổi trạng thái (2) → (3) xấp xỉ 5933 J.","answer":false}],"explanation":"a) sai<br>Quá trình từ (1) đến (2) là quá trình đẳng nhiệt.<br>$\\Rightarrow$  Đường hypebol (không phải là đường thẳng)<br>b) đúng<br>Quá trình từ (2) đến (3) là quá trình đẳng áp.<br>c) đúng<br>$p_2.V_2=8,31.T_2$<br>$\\Rightarrow 2.10^5.30.10^{−3}=8,31.T_2$<br>$\\Rightarrow T_2=722\\left(K\\right)$<br>d) sai<br>$\\frac{2}{6}=\\frac{V_3}{10}\\Rightarrow V_3=\\frac{10}{3}.10^{−3}\\left(m^3\\right)$<br>$\\Rightarrow A=p.\\left(V_3−V_2\\right)=10^5\\left(\\frac{10}{3}.10^{−3}.30.10^{−3}\\right)=5333,33\\left(J\\right)$","difficultySource":"ai"}}]},{"id":1476130,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Một nhóm học sinh tiến hành làm thí nghiệm đo số mol của một lượng khí không đổi, bằng cách khảo sát mối quan hệ giữa áp suất p và nhiệt độ T . Trong thí nghiệm, các em sử dụng: một bình kín có dung tích  V = 7 l chứa khí; nhiệt kế; áp kế. Các bạn học sinh tiến hành tăng từ từ nhiệt độ của khí và ghi lại số liệu áp suất tương ứng. Từ số liệu ghi được, nhóm học sinh vẽ đồ thị mô tả sự phụ thuộc của áp suất vào nhiệt độ (Hình 2). Mỗi giá trị áp suất ứng với một giá trị nhiệt độ, được biểu diễn bằng một điểm nằm trong ô chữ nhật, kích thước ô chữ nhật cho biết sai số khi đo nhiệt độ là ΔT , sai số khi đo áp suất là Δp.<br>Hình 1<br>Hình 2<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045591029-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045591553-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Sai số khi đo nhiệt độ là ΔT = ± 10 K.","answer":true},{"text":"Sai số khi đo áp suất là Δp = ± 4.10<sup>4</sup> Pa.","answer":false},{"text":"Áp suất p phụ thuộc vào nhiệt độ T theo biểu thức  $p=\\frac{nR}{T}V$ , với R là hằng số khí, n là số mol khí.","answer":false},{"text":"Số mol khí đo được xấp xỉ bằng 0,32 mol.","answer":false}],"explanation":"a) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045591836-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nhìn trên trục nhiệt độ 1 ô sai số có giá trị là 20K<br>Quy ước lấy 1 nửa ô sai số là 2∆t:  $2\\Delta T=20\\Rightarrow \\Delta T=10K$<br>b) sai<br>$\\Delta p=\\pm 0,2.\\left(10^5Pa\\right)$<br>c) sai<br>$pV=nRT$<br>d) sai<br>$n=\\frac{pV}{RT}=\\frac{2.10^5.7.10^{−3}}{8,31.300}=0,56\\left(mol\\right)$","difficultySource":"ai"},"ex":[{"exam":298,"idx":15,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình Clapeyron – Mendeleev","question":"Một nhóm học sinh tiến hành làm thí nghiệm đo số mol của một lượng khí không đổi, bằng cách khảo sát mối quan hệ giữa áp suất p và nhiệt độ T . Trong thí nghiệm, các em sử dụng: một bình kín có dung tích  V = 7 l chứa khí; nhiệt kế; áp kế. Các bạn học sinh tiến hành tăng từ từ nhiệt độ của khí và ghi lại số liệu áp suất tương ứng. Từ số liệu ghi được, nhóm học sinh vẽ đồ thị mô tả sự phụ thuộc của áp suất vào nhiệt độ (Hình 2). Mỗi giá trị áp suất ứng với một giá trị nhiệt độ, được biểu diễn bằng một điểm nằm trong ô chữ nhật, kích thước ô chữ nhật cho biết sai số khi đo nhiệt độ là ΔT , sai số khi đo áp suất là Δp.<br>Hình 1<br>Hình 2<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045591029-hinh-8.jpg\" alt=\"Hình 8\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045591553-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Sai số khi đo nhiệt độ là ΔT = ± 10 K.","answer":true},{"text":"Sai số khi đo áp suất là Δp = ± 4.10<sup>4</sup> Pa.","answer":false},{"text":"Áp suất p phụ thuộc vào nhiệt độ T theo biểu thức  $p=\\frac{nR}{T}V$ , với R là hằng số khí, n là số mol khí.","answer":false},{"text":"Số mol khí đo được xấp xỉ bằng 0,32 mol.","answer":false}],"explanation":"a) đúng<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045591836-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nhìn trên trục nhiệt độ 1 ô sai số có giá trị là 20K<br>Quy ước lấy 1 nửa ô sai số là 2∆t:  $2\\Delta T=20\\Rightarrow \\Delta T=10K$<br>b) sai<br>$\\Delta p=\\pm 0,2.\\left(10^5Pa\\right)$<br>c) sai<br>$pV=nRT$<br>d) sai<br>$n=\\frac{pV}{RT}=\\frac{2.10^5.7.10^{−3}}{8,31.300}=0,56\\left(mol\\right)$","difficultySource":"ai"}}]},{"id":1476158,"nq":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một bạn học sinh dùng ấm điện có công suất không đổi để cung cấp nhiệt lượng cho một khối nước đá ở 0 C, có khối lượng m (kg). Sau khi đun được một khoảng thời gian ngắn, bạn bắt đầu theo dõi và thu được đồ thị biểu diễn sự phụ thuộc của nhiệt độ của nước đá theo nhiệt lượng cung cấp như hình bên dưới. Bỏ qua sự truyền nhiệt ra môi trường và ấm điện. Xem sự bay hơi của nước trong quá trình nóng chảy và tăng nhiệt độ là không đáng kể. Biết nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg; nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4 200 J/(kg.K) và 2,3.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045604800-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng nước đá nhận vào để nóng chảy hoàn toàn là 660 kJ.","answer":false},{"text":"Khối lượng nước đá ban đầu m = 2 kg.","answer":true},{"text":"Nhiệt lượng nước nhận vào để hóa hơi hoàn toàn (tính từ thời điểm nước bắt đầu sôi) là 600 kJ.","answer":false},{"text":"Nếu công suất của ấm điện là 1 000 W thì khoảng thời gian từ thời điểm bắt đầu đun đến thời điểm nước vừa hóa hơi hoàn toàn là 2 100 giây.","answer":false}],"explanation":"a) sai<br>Từ đồ thị, ta xác định được nhiệt lượng nước thu vào để tăng nhiệt độ từ 0 C đến 100 C là 840 kJ.<br>Khối lượng nước đá ban đầu bằng khối lượng nước thu được từ lượng nước đá nóng chảy hoàn toàn, ta có:<br>$Q_t=m.c.\\Delta T$    $m=\\frac{Q}{c.\\Delta T}=\\frac{840000}{4200.100}=2$  kg.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng nước đá nhận vào để nóng chảy hoàn toàn là:<br>$Q_{nc}=.m=3,34.{10}^5.2=668 000$  J.<br>b) đúng<br>Khối lượng nước đá ban đầu là  $m=2$  kg.<br>c) sai<br>Nhiệt lượng nước nhận vào để hóa hơi hoàn toàn (tính từ thời điểm nước bắt đầu sôi) là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{hh}=L.m=2,3.{10}^6.2=4 600 000$  J.<br>d) sai<br>Nhiệt lượng đã cung cấp cho nước đá để nóng chảy hoàn toàn, tăng nhiệt độ đến nhiệt độ sôi và hóa hơi hoàn toàn là Q = 668 000 + 840 000 + 4 600 000 = 6 108 000 J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nếu công suất của ấm điện là 1 000 W thì khoảng thời gian từ thời điểm bắt đầu đun đến thời điểm nước vừa hóa hơi hoàn toàn là  $t=\\frac{Q}{P}=\\frac{6 108 000}{1000}=6 108$  giây.","difficultySource":"ai"},"ex":[{"exam":299,"idx":18,"el":{"form":"bai_tap","type":"true_false","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","question":"Một bạn học sinh dùng ấm điện có công suất không đổi để cung cấp nhiệt lượng cho một khối nước đá ở 0 C, có khối lượng m (kg). Sau khi đun được một khoảng thời gian ngắn, bạn bắt đầu theo dõi và thu được đồ thị biểu diễn sự phụ thuộc của nhiệt độ của nước đá theo nhiệt lượng cung cấp như hình bên dưới. Bỏ qua sự truyền nhiệt ra môi trường và ấm điện. Xem sự bay hơi của nước trong quá trình nóng chảy và tăng nhiệt độ là không đáng kể. Biết nhiệt nóng chảy riêng của nước đá là 3,34.10<sup>5</sup> J/kg; nhiệt dung riêng và nhiệt hóa hơi riêng của nước lần lượt là 4 200 J/(kg.K) và 2,3.10<sup>6</sup> J/kg.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/cat-1791045604800-hinh-9.webp\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Nhiệt lượng nước đá nhận vào để nóng chảy hoàn toàn là 660 kJ.","answer":false},{"text":"Khối lượng nước đá ban đầu m = 2 kg.","answer":true},{"text":"Nhiệt lượng nước nhận vào để hóa hơi hoàn toàn (tính từ thời điểm nước bắt đầu sôi) là 600 kJ.","answer":false},{"text":"Nếu công suất của ấm điện là 1 000 W thì khoảng thời gian từ thời điểm bắt đầu đun đến thời điểm nước vừa hóa hơi hoàn toàn là 2 100 giây.","answer":false}],"explanation":"a) sai<br>Từ đồ thị, ta xác định được nhiệt lượng nước thu vào để tăng nhiệt độ từ 0 C đến 100 C là 840 kJ.<br>Khối lượng nước đá ban đầu bằng khối lượng nước thu được từ lượng nước đá nóng chảy hoàn toàn, ta có:<br>$Q_t=m.c.\\Delta T$    $m=\\frac{Q}{c.\\Delta T}=\\frac{840000}{4200.100}=2$  kg.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nhiệt lượng nước đá nhận vào để nóng chảy hoàn toàn là:<br>$Q_{nc}=.m=3,34.{10}^5.2=668 000$  J.<br>b) đúng<br>Khối lượng nước đá ban đầu là  $m=2$  kg.<br>c) sai<br>Nhiệt lượng nước nhận vào để hóa hơi hoàn toàn (tính từ thời điểm nước bắt đầu sôi) là<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$Q_{hh}=L.m=2,3.{10}^6.2=4 600 000$  J.<br>d) sai<br>Nhiệt lượng đã cung cấp cho nước đá để nóng chảy hoàn toàn, tăng nhiệt độ đến nhiệt độ sôi và hóa hơi hoàn toàn là Q = 668 000 + 840 000 + 4 600 000 = 6 108 000 J.<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>Nếu công suất của ấm điện là 1 000 W thì khoảng thời gian từ thời điểm bắt đầu đun đến thời điểm nước vừa hóa hơi hoàn toàn là  $t=\\frac{Q}{P}=\\frac{6 108 000}{1000}=6 108$  giây.","difficultySource":"ai"}}]},{"id":1477384,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["Khi truyền trong chân không, sóng điện từ không mang theo năng lượng.","Sóng điện từ có thể là sóng dọc hoặc sóng ngang.","Sóng điện từ luôn lan truyền với tốc độ c = 3.10<sup>8</sup> m/s.","Tốc độ truyền sóng điện từ phụ thuộc vào môi trường."],"question":"Khi nói về sóng điện từ phát biểu nào sau đây là đúng?","difficulty":"de","explanation":"A. Sai. Sóng điện từ luôn mang năng lượng.<br>B. Sai. Sóng điện từ là sóng ngang.<br>C. Sai. Trong chân không, sóng điện từ lan truyền với tốc độ c = 3.10<sup>8</sup> m/s.","difficultySource":"ai"},"ex":[{"exam":328,"idx":1,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["Khi truyền trong chân không, sóng điện từ không mang theo năng lượng.","Sóng điện từ có thể là sóng dọc hoặc sóng ngang.","Sóng điện từ luôn lan truyền với tốc độ c = 3.10<sup>8</sup> m/s.","Tốc độ truyền sóng điện từ phụ thuộc vào môi trường."],"question":"Khi nói về sóng điện từ phát biểu nào sau đây là đúng?","difficulty":"de","explanation":"A. Sai. Sóng điện từ luôn mang năng lượng.<br>B. Sai. Sóng điện từ là sóng ngang.<br>C. Sai. Trong chân không, sóng điện từ lan truyền với tốc độ c = 3.10<sup>8</sup> m/s.","difficultySource":"ai"}}]},{"id":1477389,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["200 m.","30 m.","150 m.","300 m."],"question":"Một sóng điện từ có tần số 106 Hz truyền trong một môi trường với tốc độ 3.10<sup>8</sup> m/s. Trong môi trường đó, sóng điện từ này có bước sóng là:","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Bước sóng được tính theo công thức liên hệ giữa tốc độ truyền sóng, tần số và bước sóng: $\\lambda = \\dfrac{v}{f}$.</p><p class=\"text-base leading-relaxed my-2\">Trong đó $v$ là tốc độ truyền sóng trong môi trường, $f$ là tần số sóng.</p><p class=\"text-base leading-relaxed my-2\">Thay số với $f = 10^6\\ \\text{Hz}$ và $v = 3\\cdot 10^8\\ \\text{m/s}$:</p><p class=\"text-base leading-relaxed my-2\">$\\lambda = \\dfrac{3\\cdot 10^8}{10^6} = 300\\ \\text{m}$</p><p class=\"text-base leading-relaxed my-2\">Vậy bước sóng của sóng điện từ trong môi trường đó là $300\\ \\text{m}$. Chọn D.</p>","difficultySource":"ai"},"ex":[{"exam":328,"idx":6,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":3,"options":["200 m.","30 m.","150 m.","300 m."],"question":"Một sóng điện từ có tần số 106 Hz truyền trong một môi trường với tốc độ 3.10<sup>8</sup> m/s. Trong môi trường đó, sóng điện từ này có bước sóng là:","difficulty":"de","explanation":"* Ta có:  $f=\\frac{c}{f}=\\frac{3.10^8}{10^6}=300m$","difficultySource":"ai"}}]},{"id":1477404,"nq":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một quả khí cầu có một lỗ hở ở phía dưới để trao đổi khí với môi trường xung quanh, có thể tích không đổi V = 1,15 m3. Vỏ khí cầu có thể tích không đáng kể và khối lượng m = 0,2 kg (gồm khối lượng vỏ và bộ phận đốt nóng). Ở mặt đất nhiệt độ của không khí là t1 = 200C, áp suất khí quyển là p1 = 1,013.10<sup>5</sup> Pa, khối lượng riêng của không khí là $\\rho_0$ = 1,2 kg/m3, gia tốc trọng trường là g = 10 $m/s^2$.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045831890-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng mol trung bình của không khí là 28,8 kg/mol.","answer":false},{"text":"Nung nóng khí bên trong khí cầu lên thì áp suất trong khí cầu cũng tăng lên.","answer":false},{"text":"Để quả khí cầu bắt đầu bay lên, ta cần nung nóng khí bên trong khí cầu đến nhiệt độ 69,660C.","answer":true},{"text":"Sau khi nung nóng khí bên trong khí cầu, người ta bịt kín lỗ hở lại và thả cho quả khí cầu bay lên. Cho nhiệt độ khí bên trong khí cầu t2 = 1100C không đổi. Nhiệt độ của khí quyển và gia tốc trọng trường ở mặt đất coi như không đổi theo độ cao, còn khối lượng riêng của khí quyển phụ thuộc vào độ cao h (so với mặt đất) theo công thức $\\rho =\\rho_0.e^{\\frac{−\\rho_0.g.h}{p_1}}$ ; với e = 2,718. Độ cao cực đại mà quả khí cầu lên được là 796,77 m.","answer":true}],"explanation":"a) sai<br>$p_1V=\\frac{m}{M}RT_1\\Rightarrow \\rho_0=\\frac{m}{V}=\\frac{p_1M}{RT_1}\\Rightarrow M=\\frac{\\rho_0RT_1}{p_1}=\\frac{1,2.8,31.\\left(20+273\\right)}{1,013.10^5}=0,0288kg/mol=28,8g/mol$<br>b) sai<br>Do phía dưới khí cầu có một lỗ hở, nên áp suất khí cầu luôn bằng áp suất khí quyển<br>c) đúng<br>Tại mặt đất:  $\\frac{p_1M}{R}=\\rho T=hs\\Rightarrow \\rho_0T_1=\\rho_2T_2\\Rightarrow \\rho_2=\\rho_0.\\frac{T_1}{T_2}$<br>* Khí cầu bay bắt đầu bay lên khi:  $F_A=P_{vo}+P_{khi}\\Rightarrow \\rho_0gV=mg+\\rho_2V.g$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045832067-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>* Tại mặt đất:  $\\frac{p_1M}{R}=\\rho T=hs\\Rightarrow \\rho_0T_1=\\rho_3T_3\\Rightarrow \\rho_3=\\rho_0.\\frac{T_1}{T_3}=1,2.\\frac{20+273}{110+273}=0,918\\left(kg/m^3\\right)$<br>* Khí cầu đạt độ cao cực đại thì:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045832232-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>*  $\\rho =\\rho_0.e^{\\frac{−\\rho_0.g.h}{p_1}}\\Rightarrow 1,0919=1,2.2,718^{−\\frac{1,2.10h}{1,013.10^5}}\\Rightarrow h=796,8m$","difficultySource":"ai"},"ex":[{"exam":328,"idx":21,"el":{"form":"bai_tap","type":"true_false","topic":"Phương trình trạng thái khí lí tưởng","question":"Một quả khí cầu có một lỗ hở ở phía dưới để trao đổi khí với môi trường xung quanh, có thể tích không đổi V = 1,15 m3. Vỏ khí cầu có thể tích không đáng kể và khối lượng m = 0,2 kg (gồm khối lượng vỏ và bộ phận đốt nóng). Ở mặt đất nhiệt độ của không khí là t1 = 200C, áp suất khí quyển là p1 = 1,013.10<sup>5</sup> Pa, khối lượng riêng của không khí là $\\rho_0$ = 1,2 kg/m3, gia tốc trọng trường là g = 10 m/s2.<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045831890-hinh-11.jpg\" alt=\"Hình 11\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"kho","statements":[{"text":"Khối lượng mol trung bình của không khí là 28,8 kg/mol.","answer":false},{"text":"Nung nóng khí bên trong khí cầu lên thì áp suất trong khí cầu cũng tăng lên.","answer":false},{"text":"Để quả khí cầu bắt đầu bay lên, ta cần nung nóng khí bên trong khí cầu đến nhiệt độ 69,660C.","answer":true},{"text":"Sau khi nung nóng khí bên trong khí cầu, người ta bịt kín lỗ hở lại và thả cho quả khí cầu bay lên. Cho nhiệt độ khí bên trong khí cầu t2 = 1100C không đổi. Nhiệt độ của khí quyển và gia tốc trọng trường ở mặt đất coi như không đổi theo độ cao, còn khối lượng riêng của khí quyển phụ thuộc vào độ cao h (so với mặt đất) theo công thức $\\rho =\\rho_0.e^{\\frac{−\\rho_0.g.h}{p_1}}$ ; với e = 2,718. Độ cao cực đại mà quả khí cầu lên được là 796,77 m.","answer":true}],"explanation":"a) sai<br>$p_1V=\\frac{m}{M}RT_1\\Rightarrow \\rho_0=\\frac{m}{V}=\\frac{p_1M}{RT_1}\\Rightarrow M=\\frac{\\rho_0RT_1}{p_1}=\\frac{1,2.8,31.\\left(20+273\\right)}{1,013.10^5}=0,0288kg/mol=28,8g/mol$<br>b) sai<br>Do phía dưới khí cầu có một lỗ hở, nên áp suất khí cầu luôn bằng áp suất khí quyển<br>c) đúng<br>Tại mặt đất:  $\\frac{p_1M}{R}=\\rho T=hs\\Rightarrow \\rho_0T_1=\\rho_2T_2\\Rightarrow \\rho_2=\\rho_0.\\frac{T_1}{T_2}$<br>* Khí cầu bay bắt đầu bay lên khi:  $F_A=P_{vo}+P_{khi}\\Rightarrow \\rho_0gV=mg+\\rho_2V.g$<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045832067-hinh-12.png\" alt=\"Hình 12\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>d) đúng<br>* Tại mặt đất:  $\\frac{p_1M}{R}=\\rho T=hs\\Rightarrow \\rho_0T_1=\\rho_3T_3\\Rightarrow \\rho_3=\\rho_0.\\frac{T_1}{T_3}=1,2.\\frac{20+273}{110+273}=0,918\\left(kg/m^3\\right)$<br>* Khí cầu đạt độ cao cực đại thì:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791045832232-hinh-13.png\" alt=\"Hình 13\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>*  $\\rho =\\rho_0.e^{\\frac{−\\rho_0.g.h}{p_1}}\\Rightarrow 1,0919=1,2.2,718^{−\\frac{1,2.10h}{1,013.10^5}}\\Rightarrow h=796,8m$","difficultySource":"ai"}}]},{"id":1477499,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["Khi truyền từ môi trường này sang môi trường khác, tần số sóng điện từ không đổi.","Sóng điện từ có thể là sóng dọc hoặc sóng ngang.","Khi truyền trong chân không, sóng điện từ không mang theo năng lượng.","Sóng điện từ luôn lan truyền với tốc độ c = 3.10<sup>8</sup> m/s."],"question":"Khi nói về sóng điện từ phát biểu nào sau đây là đúng?","difficulty":"de","explanation":"Khi sóng điện từ truyền từ môi trường này sang môi trường khác, chỉ tốc độ truyền (và bước sóng) thay đổi; tần số luôn không đổi vì do nguồn phát quyết định.<br>Xét các phương án còn lại: sóng điện từ là sóng ngang nên B sai; sóng điện từ vẫn mang năng lượng khi truyền trong chân không nên C sai; tốc độ c=3.10^8 m/s chỉ đúng trong chân không (không phải luôn luôn) nên D sai.<br>Sóng điện từ là sóng ngang<br>Khi truyền trong chân không, sóng điện từ mang theo năng lượng<br>Sóng điện từ lan truyền với tốc độ c = 3.10<sup>8</sup> m/s trong chân không","difficultySource":"ai"},"ex":[{"exam":362,"idx":6,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Điện từ trường và sóng điện từ","answer":0,"options":["Khi truyền từ môi trường này sang môi trường khác, tần số sóng điện từ không đổi.","Sóng điện từ có thể là sóng dọc hoặc sóng ngang.","Khi truyền trong chân không, sóng điện từ không mang theo năng lượng.","Sóng điện từ luôn lan truyền với tốc độ c = 3.10<sup>8</sup> m/s."],"question":"Khi nói về sóng điện từ phát biểu nào sau đây là đúng?","difficulty":"de","explanation":"Khi sóng điện từ truyền từ môi trường này sang môi trường khác, chỉ tốc độ truyền (và bước sóng) thay đổi; tần số luôn không đổi vì do nguồn phát quyết định.<br>Xét các phương án còn lại: sóng điện từ là sóng ngang nên B sai; sóng điện từ vẫn mang năng lượng khi truyền trong chân không nên C sai; tốc độ c=3.10^8 m/s chỉ đúng trong chân không (không phải luôn luôn) nên D sai.<br>Sóng điện từ là sóng ngang<br>Khi truyền trong chân không, sóng điện từ mang theo năng lượng<br>Sóng điện từ lan truyền với tốc độ c = 3.10<sup>8</sup> m/s trong chân không","difficultySource":"ai"}}]},{"id":1477667,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":1,"options":["4,28.10<sup>−21</sup> J.","6,42.10<sup>−21</sup> J.","7,66.10<sup>−22</sup> J.","2,07.10<sup>−23</sup> J."],"question":"Một bình kín chứa khí heli ở nhiệt độ 370C. Động năng tịnh tiến trung bình của mỗi phân tử khí xấp xỉ","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng Wđ = (3/2).k.T, với k = 1,38.10⁻²³ J/K là hằng số Boltzmann.<br>Thay số: T = 37 + 273 = 310 K ⇒ Wđ = (3/2).1,38.10⁻²³.310 = 6,42.10⁻²¹ (J).<br>Kết luận: động năng tịnh tiến trung bình mỗi phân tử xấp xỉ 6,42.10⁻²¹ J. Đáp số: B.<br>$\\overline{E}_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,42.10^{−21}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":407,"idx":7,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Động năng trung bình phân tử và nhiệt độ","answer":1,"options":["4,28.10<sup>−21</sup> J.","6,42.10<sup>−21</sup> J.","7,66.10<sup>−22</sup> J.","2,07.10<sup>−23</sup> J."],"question":"Một bình kín chứa khí heli ở nhiệt độ 370C. Động năng tịnh tiến trung bình của mỗi phân tử khí xấp xỉ","difficulty":"de","explanation":"Công thức: động năng tịnh tiến trung bình của phân tử khí lí tưởng Wđ = (3/2).k.T, với k = 1,38.10⁻²³ J/K là hằng số Boltzmann.<br>Thay số: T = 37 + 273 = 310 K ⇒ Wđ = (3/2).1,38.10⁻²³.310 = 6,42.10⁻²¹ (J).<br>Kết luận: động năng tịnh tiến trung bình mỗi phân tử xấp xỉ 6,42.10⁻²¹ J. Đáp số: B.<br>$\\overline{E}_d=\\frac{3}{2}kT=\\frac{3}{2}.1,38.10^{−23}.\\left(27+273\\right)=6,42.10^{−21}\\left(J\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1477686,"nq":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"1,13","question":"Hình bên mô tả một dây dẫn được uốn thành một cung tròn có bán kính r = 30 cm, tâm O. Một dây dẫn thẳng OM có thể quay quanh O và tiếp xúc trượt với cung tại M. Một dây dẫn thẳng ON khác hoàn thành mạch kín. Cả ba dây dẫn đều có tiết diện ngang 2,0 mm2 và điện trở suất 2,65.10<sup>−8</sup> Ω.m. Hệ thống nằm trong từ trường đều có độ lớn B = 0,2 T vuông góc với mặt phẳng hình vẽ. Ban đầu điểm M trùng với N. Dây dẫn OM quay đều từ N với tốc độ góc không đổi 2 rad/s. Cường độ dòng điện cảm ứng chạy trong<br>mạch bằng bao nhiêu A khi OM quay được góc α = 1150 ? (làm tròn kết quả đến chữ số hàng phần trăm)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224518602-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:203.3px;height:auto\" />","difficulty":"kho","explanation":"Công thức: mạch kín gồm hai bán kính OM, ON (mỗi đoạn dài r) và cung MN đã quét (dài r.α); điện trở R = δ.ℓ/S. Vì OM quay đều với tốc độ góc ω không đổi, diện tích quét ΔS/Δt = (1/2)r²ω không đổi nên suất điện động cảm ứng |ec| = B.(1/2)r²ω không đổi theo thời gian; cường độ dòng cảm ứng I = |ec|/R.<br>Thay số: R = (2,65.10⁻⁸/2.10⁻⁶).[0,6 + 0,3.(115°.π/180°)] ≈ 0,016 Ω; |ec| = 0,2.(1/2).0,3².2 = 0,2.0,09 = 0,018 (V).<br>Kết luận: I = 0,018/0,016 ≈ 1,13 A (làm tròn đến hàng phần trăm). Đáp số: 1,13.<br>$\\left|i_C\\right|=\\frac{\\left|e_C\\right|}{R}$<br>$R=\\delta .\\frac{ℓ}{S}=\\frac{2,65.10^{−8}}{2.10^{−6}}.\\left(0,6+\\frac{115^0}{360^0}.2\\pi .0,3\\right)=0,016\\left(\\Omega \\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\left|e_C\\right|=\\frac{\\Delta \\Phi }{\\Delta t}=\\frac{B.\\Delta S}{\\Delta t}=\\frac{B}{\\Delta t}.\\left(\\frac{115^0}{360^9}.\\pi .0,3^2\\right)=\\frac{0,2}{\\left(115^0.\\frac{\\pi }{180}\\right):2}.\\left(\\frac{115^0}{360^9}.\\pi .0,3^2\\right)=0,018\\left(V\\right)Website: thukhoadaihoc.vn$<br>$\\Rightarrow \\left|i_C\\right|=\\frac{\\left|e_C\\right|}{R}=\\frac{0,018}{0,016}\\approx 1,13\\left(A\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"},"ex":[{"exam":407,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"1,13","question":"Hình bên mô tả một dây dẫn được uốn thành một cung tròn có bán kính r = 30 cm, tâm O. Một dây dẫn thẳng OM có thể quay quanh O và tiếp xúc trượt với cung tại M. Một dây dẫn thẳng ON khác hoàn thành mạch kín. Cả ba dây dẫn đều có tiết diện ngang 2,0 mm2 và điện trở suất 2,65.10<sup>−8</sup> Ω.m. Hệ thống nằm trong từ trường đều có độ lớn B = 0,2 T vuông góc với mặt phẳng hình vẽ. Ban đầu điểm M trùng với N. Dây dẫn OM quay đều từ N với tốc độ góc không đổi 2 rad/s. Cường độ dòng điện cảm ứng chạy trong<br>mạch bằng bao nhiêu A khi OM quay được góc α = 1150 ? (làm tròn kết quả đến chữ số hàng phần trăm)<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791224518602-hinh-10.png\" alt=\"Hình 10\" class=\"mx-auto my-2 max-w-full rounded-lg\" style=\"width:203.3px;height:auto\" />","difficulty":"kho","explanation":"Công thức: mạch kín gồm hai bán kính OM, ON (mỗi đoạn dài r) và cung MN đã quét (dài r.α); điện trở R = δ.ℓ/S. Vì OM quay đều với tốc độ góc ω không đổi, diện tích quét ΔS/Δt = (1/2)r²ω không đổi nên suất điện động cảm ứng |ec| = B.(1/2)r²ω không đổi theo thời gian; cường độ dòng cảm ứng I = |ec|/R.<br>Thay số: R = (2,65.10⁻⁸/2.10⁻⁶).[0,6 + 0,3.(115°.π/180°)] ≈ 0,016 Ω; |ec| = 0,2.(1/2).0,3².2 = 0,2.0,09 = 0,018 (V).<br>Kết luận: I = 0,018/0,016 ≈ 1,13 A (làm tròn đến hàng phần trăm). Đáp số: 1,13.<br>$\\left|i_C\\right|=\\frac{\\left|e_C\\right|}{R}$<br>$R=\\delta .\\frac{ℓ}{S}=\\frac{2,65.10^{−8}}{2.10^{−6}}.\\left(0,6+\\frac{115^0}{360^0}.2\\pi .0,3\\right)=0,016\\left(\\Omega \\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$<br>$\\begin{aligned}\\end{aligned}\\left|e_C\\right|=\\frac{\\Delta \\Phi }{\\Delta t}=\\frac{B.\\Delta S}{\\Delta t}=\\frac{B}{\\Delta t}.\\left(\\frac{115^0}{360^9}.\\pi .0,3^2\\right)=\\frac{0,2}{\\left(115^0.\\frac{\\pi }{180}\\right):2}.\\left(\\frac{115^0}{360^9}.\\pi .0,3^2\\right)=0,018\\left(V\\right)Website: thukhoadaihoc.vn$<br>$\\Rightarrow \\left|i_C\\right|=\\frac{\\left|e_C\\right|}{R}=\\frac{0,018}{0,016}\\approx 1,13\\left(A\\right)$<br>$Taøi lieäu ñöôïc phaùt haønh taïi Website: thukhoadaihoc.vn$","difficultySource":"ai"}}]},{"id":1477850,"nq":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"1,95","question":"Hình bên là sơ đồ cấu tạo của 1 bộ pickup trong một loại đàn guitar điện. Biết cuộn dây cảm ứng của pickup này gồm N = 5000 vòng. Khi dây đàn (bằng thép) dao động để đàn phát ra nốt La có tần số 440 Hz thì từ thông qua cuộn dây biến thiên điều hòa với giá trị cực đại qua mỗi vòng dây là $\\Phi_0$ = 2,0.10<sup>−7</sup> Wb.  Suất điện động hiệu dụng xuất hiện trong cuộn dây bằng bao nhiêu vôn (làm tròn kết quả đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046998562-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Ta có:  $\\begin{aligned}E=\\frac{E_0}{\\sqrt2}=\\frac{N\\Phi_0\\omega }{\\sqrt2}=\\frac{N\\Phi_02\\pi f}{\\sqrt2}=\\frac{2\\pi N\\Phi_0.f_{dd}}{\\sqrt2}=\\frac{2.3,14.5000.2.10^{−7}.440}{\\sqrt2}\\approx 1,95\\left(V\\right) <br>Website: thukhoadaihoc.vn\\end{aligned}$","difficultySource":"ai"},"ex":[{"exam":426,"idx":27,"el":{"form":"bai_tap","type":"short_answer","topic":"Suất điện động do thanh dẫn chuyển động","answer":"1,95","question":"Hình bên là sơ đồ cấu tạo của 1 bộ pickup trong một loại đàn guitar điện. Biết cuộn dây cảm ứng của pickup này gồm N = 5000 vòng. Khi dây đàn (bằng thép) dao động để đàn phát ra nốt La có tần số 440 Hz thì từ thông qua cuộn dây biến thiên điều hòa với giá trị cực đại qua mỗi vòng dây là $\\Phi_0$ = 2,0.10<sup>−7</sup> Wb.  Suất điện động hiệu dụng xuất hiện trong cuộn dây bằng bao nhiêu vôn (làm tròn kết quả đến chữ số hàng phần trăm)?<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1791046998562-hinh-20.png\" alt=\"Hình 20\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficulty":"trung-binh","explanation":"Ta có:  $\\begin{aligned}E=\\frac{E_0}{\\sqrt2}=\\frac{N\\Phi_0\\omega }{\\sqrt2}=\\frac{N\\Phi_02\\pi f}{\\sqrt2}=\\frac{2\\pi N\\Phi_0.f_{dd}}{\\sqrt2}=\\frac{2.3,14.5000.2.10^{−7}.440}{\\sqrt2}\\approx 1,95\\left(V\\right) <br>Website: thukhoadaihoc.vn\\end{aligned}$","difficultySource":"ai"}}]},{"id":1477977,"nq":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Coulomb","answer":1,"options":["$F=\\frac{\\left|q_1q_2\\right|}{4\\varepsilon_0r^2}$","$F=\\frac{\\left|q_1q_2\\right|}{4{\\pi \\varepsilon}_0r^2}$","$F=\\frac{\\left|q_1q_2\\right|}{4{\\pi \\varepsilon}_0r}$","$F=\\frac{\\left|q_1q_2\\right|}{{4\\pi r}^2}$"],"question":"Công thức nào sau đây xác định độ lớn lực tương tác tĩnh điện giữa hai điện tích điểm q1, q2 đặt cách nhau một khoảng r trong chân không, với $\\varepsilon_0$= 8,85.10<sup>−12</sup>(C2 / Nm2)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không có độ lớn tỉ lệ thuận với tích độ lớn hai điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $F=k\\dfrac{|q_1q_2|}{r^2}$, với $k=\\dfrac{1}{4\\pi\\varepsilon_0}$ là hệ số tỉ lệ trong chân không.</p><p class=\"text-base leading-relaxed my-2\">Do đó: $F=\\dfrac{|q_1q_2|}{4\\pi\\varepsilon_0 r^2}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là B. Các đáp án A, C, D sai về vị trí của $\\pi$ hoặc lũy thừa của $r$.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":0,"el":{"form":"ly_thuyet","type":"multiple_choice","topic":"Định luật Coulomb","answer":1,"options":["$F=\\frac{\\left|q_1q_2\\right|}{4\\varepsilon_0r^2}$","$F=\\frac{\\left|q_1q_2\\right|}{4{\\pi \\varepsilon}_0r^2}$","$F=\\frac{\\left|q_1q_2\\right|}{4{\\pi \\varepsilon}_0r}$","$F=\\frac{\\left|q_1q_2\\right|}{{4\\pi r}^2}$"],"question":"Công thức nào sau đây xác định độ lớn lực tương tác tĩnh điện giữa hai điện tích điểm q1, q2 đặt cách nhau một khoảng r trong chân không, với $\\varepsilon_0$= 8,85.10<sup>−12</sup>(C2 / Nm2)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Theo định luật Coulomb, lực tương tác tĩnh điện giữa hai điện tích điểm đặt trong chân không có độ lớn tỉ lệ thuận với tích độ lớn hai điện tích và tỉ lệ nghịch với bình phương khoảng cách giữa chúng.</p><p class=\"text-base leading-relaxed my-2\">Công thức chữ: $F=k\\dfrac{|q_1q_2|}{r^2}$, với $k=\\dfrac{1}{4\\pi\\varepsilon_0}$ là hệ số tỉ lệ trong chân không.</p><p class=\"text-base leading-relaxed my-2\">Do đó: $F=\\dfrac{|q_1q_2|}{4\\pi\\varepsilon_0 r^2}$.</p><p class=\"text-base leading-relaxed my-2\">Kết luận: đáp án đúng là B. Các đáp án A, C, D sai về vị trí của $\\pi$ hoặc lũy thừa của $r$.</p>","difficultySource":"ai"}}]},{"id":1477988,"nq":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Cho khoảng cách giữa electron và proton là r = 5,3.10<sup>−11</sup> m. Điện tích electron<br>qe = -1,6.10<sup>−19</sup> C, điện tích proton qp = 1,6.10<sup>−19</sup> C và môi trường giữa chúng là chân không.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác tĩnh điện giữa electron và proton là lực đẩy.","answer":false},{"text":"Lực tương tác tĩnh điện giữa electron và proton là lực hút.","answer":true},{"text":"Biểu thức tính độ lớn lực tương tác tĩnh điện giữa electron và proton là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218895970-hinh-3.png\" alt=\"Hình 3\" class=\"eq\" style=\"width:77.5px;height:41.4px\" />.","answer":false},{"text":"Độ lớn lực tương tác tĩnh điện giữa electron và proton là 4,35.10<sup>−18</sup>N.","answer":false}],"explanation":"<p class=\"text-base leading-relaxed my-2\">a) <b>Sai</b>. Electron mang điện âm, proton mang điện dương, hai điện tích trái dấu nên hút nhau, không phải đẩy.</p><p class=\"text-base leading-relaxed my-2\">b) <b>Đúng</b>. Hai điện tích trái dấu $q_e\\lt0$, $q_p\\gt0$ nên lực tương tác là lực hút.</p><p class=\"text-base leading-relaxed my-2\">c) <b>Sai</b>. Biểu thức đúng của độ lớn lực là $F=k\\dfrac{|q_eq_p|}{r^2}$, còn biểu thức trong đề có $r$ ở mẫu số (không bình phương).</p><p class=\"text-base leading-relaxed my-2\">d) <b>Sai</b>. $F=9.10^9\\cdot\\dfrac{(1{,}6.10^{-19})^2}{(5{,}3.10^{-11})^2}\\approx8{,}2.10^{-8}$ N, không phải $4{,}35.10^{-18}$ N.</p>","difficultySource":"ai"},"ex":[{"exam":812,"idx":11,"el":{"form":"bai_tap","type":"true_false","topic":"Định luật Coulomb","question":"Cho khoảng cách giữa electron và proton là r = 5,3.10<sup>−11</sup> m. Điện tích electron<br>qe = -1,6.10<sup>−19</sup> C, điện tích proton qp = 1,6.10<sup>−19</sup> C và môi trường giữa chúng là chân không.","difficulty":"trung-binh","statements":[{"text":"Lực tương tác tĩnh điện giữa electron và proton là lực đẩy.","answer":false},{"text":"Lực tương tác tĩnh điện giữa electron và proton là lực hút.","answer":true},{"text":"Biểu thức tính độ lớn lực tương tác tĩnh điện giữa electron và proton là <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/119/1791218895970-hinh-3.png\" alt=\"Hình 3\" class=\"eq\" style=\"width:77.5px;height:41.4px\" />.","answer":false},{"text":"Độ lớn lực tương tác tĩnh điện giữa electron và proton là 4,35.10<sup>−18</sup>N.","answer":false}],"explanation":"","difficultySource":"ai"}}]},{"id":1478365,"nq":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"2,8","question":"Xét một thỏi bạc nguyên chất (Ag) có khối lượng 50,0 gam. Bạc là một kim loại có cấu trúc tinh thể đặc khít, trong đó các nguyên tử bạc có thể được coi là những quả cầu xếp cạnh nhau. Cho biết: Khối lượng mol của bạc là 108 g/mol; số Avogadro là 6,02.10<sup>23</sup> mol-1; khối lượng riêng của bạc là 10500 kg/m3. Coi mỗi nguyên tử bạc là một khối cầu và có thể tích khoảng 1,25.10<sup>−29</sup> m3.<br>Số nguyên tử bạc có trong thỏi bạc là x.10<sup>23</sup>. Giá trị của x là bao nhiêu (làm tròn kết quả đến hàng phần mười)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Số mol bạc trong thỏi: $n = \\dfrac{m}{M}$ với $m = 50{,}0\\ \\text{g}$ và $M = 108\\ \\text{g/mol}$.</p><p class=\"text-base leading-relaxed my-2\">$n = \\dfrac{50{,}0}{108} \\approx 0{,}463\\ \\text{mol}$</p><p class=\"text-base leading-relaxed my-2\">Số nguyên tử bạc: $N = n \\cdot N_A$ với $N_A = 6{,}02\\cdot 10^{23}\\ \\text{mol}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = 0{,}463 \\cdot 6{,}02\\cdot 10^{23} \\approx 2{,}787\\cdot 10^{23}\\ \\text{nguyên tử}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x \\approx 2{,}8$ (làm tròn đến hàng phần mười).</p>","difficultySource":"ai"},"ex":[{"exam":128,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Mol, số Avogadro và lượng chất khí","answer":"2,8","question":"Xét một thỏi bạc nguyên chất (Ag) có khối lượng 50,0 gam. Bạc là một kim loại có cấu trúc tinh thể đặc khít, trong đó các nguyên tử bạc có thể được coi là những quả cầu xếp cạnh nhau. Cho biết: Khối lượng mol của bạc là 108 g/mol; số Avogadro là 6,02.10<sup>23</sup> mol-1; khối lượng riêng của bạc là 10500 kg/m3. Coi mỗi nguyên tử bạc là một khối cầu và có thể tích khoảng 1,25.10<sup>−29</sup> m3.<br>Số nguyên tử bạc có trong thỏi bạc là x.10<sup>23</sup>. Giá trị của x là bao nhiêu (làm tròn kết quả đến hàng phần mười)?","difficulty":"de","explanation":"<p class=\"text-base leading-relaxed my-2\">Số mol bạc trong thỏi: $n = \\dfrac{m}{M}$ với $m = 50{,}0\\ \\text{g}$ và $M = 108\\ \\text{g/mol}$.</p><p class=\"text-base leading-relaxed my-2\">$n = \\dfrac{50{,}0}{108} \\approx 0{,}463\\ \\text{mol}$</p><p class=\"text-base leading-relaxed my-2\">Số nguyên tử bạc: $N = n \\cdot N_A$ với $N_A = 6{,}02\\cdot 10^{23}\\ \\text{mol}^{-1}$.</p><p class=\"text-base leading-relaxed my-2\">$\\Rightarrow N = 0{,}463 \\cdot 6{,}02\\cdot 10^{23} \\approx 2{,}787\\cdot 10^{23}\\ \\text{nguyên tử}$</p><p class=\"text-base leading-relaxed my-2\">Vậy $x \\approx 2{,}8$ (làm tròn đến hàng phần mười).</p>","difficultySource":"ai"}}]},{"id":1478366,"nq":{"form":"bai_tap","type":"short_answer","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","answer":"73","question":"Xét một thỏi bạc nguyên chất (Ag) có khối lượng 50,0 gam. Bạc là một kim loại có cấu trúc tinh thể đặc khít, trong đó các nguyên tử bạc có thể được coi là những quả cầu xếp cạnh nhau. Cho biết: Khối lượng mol của bạc là 108 g/mol; số Avogadro là 6,02.10<sup>23</sup> mol-1; khối lượng riêng của bạc là 10500 kg/m3. Coi mỗi nguyên tử bạc là một khối cầu và có thể tích khoảng 1,25.10<sup>−29</sup> m3.<br>Tổng thể tích của tất cả các nguyên tử bạc chiếm bao nhiêu phần trăm so với thể tích của cả thỏi bạc (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$V=N.V_{1nguiyen tu}=\\left(\\frac{50}{108}.6,02.10^{23}\\right).1,25.10^{−29}=3,484.10^{−6}\\left(m^3\\right)∑$<br>$\\frac{V_{nguyen tu}∑}{V_{thoi Bac}}=\\frac{3,484.10^{−6}}{\\frac{5.10^{−3}}{10500}}=73,16%$","difficultySource":"ai"},"ex":[{"exam":128,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Cấu trúc chất rắn, lỏng, khí theo mô hình động học phân tử","answer":"73","question":"Xét một thỏi bạc nguyên chất (Ag) có khối lượng 50,0 gam. Bạc là một kim loại có cấu trúc tinh thể đặc khít, trong đó các nguyên tử bạc có thể được coi là những quả cầu xếp cạnh nhau. Cho biết: Khối lượng mol của bạc là 108 g/mol; số Avogadro là 6,02.10<sup>23</sup> mol-1; khối lượng riêng của bạc là 10500 kg/m3. Coi mỗi nguyên tử bạc là một khối cầu và có thể tích khoảng 1,25.10<sup>−29</sup> m3.<br>Tổng thể tích của tất cả các nguyên tử bạc chiếm bao nhiêu phần trăm so với thể tích của cả thỏi bạc (làm tròn kết quả đến chữ số hàng đơn vị)?","difficulty":"trung-binh","explanation":"$V=N.V_{1nguiyen tu}=\\left(\\frac{50}{108}.6,02.10^{23}\\right).1,25.10^{−29}=3,484.10^{−6}\\left(m^3\\right)∑$<br>$\\frac{V_{nguyen tu}∑}{V_{thoi Bac}}=\\frac{3,484.10^{−6}}{\\frac{5.10^{−3}}{10500}}=73,16%$","difficultySource":"ai"}}]},{"id":1478449,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"504","question":"Dùng bếp điện để đun một ấm nhôm khối lượng 600 g đựng 1,5 lít nước ở nhiệt độ 20°C. Sau 35 phút đã có 20% lượng nước trong ấm đã hoá hơi ở nhiệt độ sôi 100°C. Biết chỉ có 75% nhiệt lượng mà bếp toả ra được dùng vào việc đun ấm nước; nhiệt dung riêng của nhôm 880 J/kg.K; nhiệt dung riêng của nước là 4200 J/kg.K; nhiệt hoá hơi riêng của nước ở nhiệt độ sôi 100°C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng của nước là 1 kg/lít.<br>Nhiệt lượng mà 1,5 lít nước nhận được để tăng từ 20°C đến sôi ở 100°C là bao nhiêu kJ (làm tròn kết quả đến hàng đơn vị)?","difficulty":"de","explanation":"Theo đề:1kg/lít<br>$\\Rightarrow 1,5$  lít  $\\Rightarrow 1,5kg$<br>$Q_3=m_{nc}.c_{nc}.\\Delta t=1,5.4200.\\left(100−20\\right)=504.10^3\\left(J\\right)=504\\left(kJ\\right)$","difficultySource":"ai"},"ex":[{"exam":137,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"504","question":"Dùng bếp điện để đun một ấm nhôm khối lượng 600 g đựng 1,5 lít nước ở nhiệt độ 20°C. Sau 35 phút đã có 20% lượng nước trong ấm đã hoá hơi ở nhiệt độ sôi 100°C. Biết chỉ có 75% nhiệt lượng mà bếp toả ra được dùng vào việc đun ấm nước; nhiệt dung riêng của nhôm 880 J/kg.K; nhiệt dung riêng của nước là 4200 J/kg.K; nhiệt hoá hơi riêng của nước ở nhiệt độ sôi 100°C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng của nước là 1 kg/lít.<br>Nhiệt lượng mà 1,5 lít nước nhận được để tăng từ 20°C đến sôi ở 100°C là bao nhiêu kJ (làm tròn kết quả đến hàng đơn vị)?","difficulty":"de","explanation":"Theo đề:1kg/lít<br>$\\Rightarrow 1,5$  lít  $\\Rightarrow 1,5kg$<br>$Q_3=m_{nc}.c_{nc}.\\Delta t=1,5.4200.\\left(100−20\\right)=504.10^3\\left(J\\right)=504\\left(kJ\\right)$","difficultySource":"ai"}}]},{"id":1478450,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"777","question":"Dùng bếp điện để đun một ấm nhôm khối lượng 600 g đựng 1,5 lít nước ở nhiệt độ 20°C. Sau 35 phút đã có 20% lượng nước trong ấm đã hoá hơi ở nhiệt độ sôi 100°C. Biết chỉ có 75% nhiệt lượng mà bếp toả ra được dùng vào việc đun ấm nước; nhiệt dung riêng của nhôm 880 J/kg.K; nhiệt dung riêng của nước là 4200 J/kg.K; nhiệt hoá hơi riêng của nước ở nhiệt độ sôi 100°C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng của nước là 1 kg/lít.<br>Công suất trung bình của bếp điện là bao nhiêu Oát (W) (làm tròn kết quả đến hàng đơn vị)?","difficulty":"kho","explanation":"$P.\\Delta t.H=\\left(m_{nc}c_n+m_{am}.c_{am}\\right).\\Delta t+20%m_{nc}.K$<br>$\\Rightarrow P.35.60.75%=\\left(1,5.4200+0,6.880\\right)\\left(100−20\\right)+20%.1,5.2,26.10^6$<br>$\\Rightarrow P\\approx 777\\left(W\\right)$","difficultySource":"ai"},"ex":[{"exam":137,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Tính nhiệt lượng theo nhiệt dung riêng","answer":"777","question":"Dùng bếp điện để đun một ấm nhôm khối lượng 600 g đựng 1,5 lít nước ở nhiệt độ 20°C. Sau 35 phút đã có 20% lượng nước trong ấm đã hoá hơi ở nhiệt độ sôi 100°C. Biết chỉ có 75% nhiệt lượng mà bếp toả ra được dùng vào việc đun ấm nước; nhiệt dung riêng của nhôm 880 J/kg.K; nhiệt dung riêng của nước là 4200 J/kg.K; nhiệt hoá hơi riêng của nước ở nhiệt độ sôi 100°C là 2,26.10<sup>6</sup> J/kg; khối lượng riêng của nước là 1 kg/lít.<br>Công suất trung bình của bếp điện là bao nhiêu Oát (W) (làm tròn kết quả đến hàng đơn vị)?","difficulty":"kho","explanation":"$P.\\Delta t.H=\\left(m_{nc}c_n+m_{am}.c_{am}\\right).\\Delta t+20%m_{nc}.K$<br>$\\Rightarrow P.35.60.75%=\\left(1,5.4200+0,6.880\\right)\\left(100−20\\right)+20%.1,5.2,26.10^6$<br>$\\Rightarrow P\\approx 777\\left(W\\right)$","difficultySource":"ai"}}]},{"id":1478454,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["910 W.","91 W.","15 W.","150 W."],"question":"Một chậu có chứa 2,6 kg hỗn hợp nước và nước đá đều ở nhiệt độ 0 °C và được đặt trong phòng kín. Sự thay đổi nhiệt độ của hỗn hợp theo thời gian được biểu diễn bằng đồ thị như hình bên dưới. Biết nhiệt dung riêng của nước là 4200 J/(kg.K), nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Cho rằng sự hấp thụ nhiệt từ môi trường là đều. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259733852-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259734914-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Công suất hấp thụ nhiệt từ môi trường của hỗn hợp nước và nước đá bằng bao nhiêu W?","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Xét giai đoạn hỗn hợp tăng nhiệt độ (đồ thị đi lên):<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $P.\\tau =m_{hh}.c_n.\\Delta T$    $P.\\left(60-50\\right).60=2,6.4200.\\left(5-0\\right)$    $P=91$  W.<br>Công suất hấp thụ nhiệt từ môi trường của hỗn hợp nước và nước đá bằng: 91 W.","difficultySource":"ai"},"ex":[{"exam":139,"idx":1,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Nhiệt nóng chảy riêng và nhiệt hoá hơi riêng","answer":1,"options":["910 W.","91 W.","15 W.","150 W."],"question":"Một chậu có chứa 2,6 kg hỗn hợp nước và nước đá đều ở nhiệt độ 0 °C và được đặt trong phòng kín. Sự thay đổi nhiệt độ của hỗn hợp theo thời gian được biểu diễn bằng đồ thị như hình bên dưới. Biết nhiệt dung riêng của nước là 4200 J/(kg.K), nhiệt nóng chảy riêng của nước đá là 3,4.10<sup>5</sup> J/kg. Cho rằng sự hấp thụ nhiệt từ môi trường là đều. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259733852-hinh-1.png\" alt=\"Hình 1\" class=\"mx-auto my-2 max-w-full rounded-lg\" /> <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259734914-hinh-2.png\" alt=\"Hình 2\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Công suất hấp thụ nhiệt từ môi trường của hỗn hợp nước và nước đá bằng bao nhiêu W?","difficulty":"trung-binh","explanation":"Chọn đáp án B<br>Xét giai đoạn hỗn hợp tăng nhiệt độ (đồ thị đi lên):<br>$\\left|Q_{tỏa}\\right|=\\left|Q_{thu}\\right|$    $P.\\tau =m_{hh}.c_n.\\Delta T$    $P.\\left(60-50\\right).60=2,6.4200.\\left(5-0\\right)$    $P=91$  W.<br>Công suất hấp thụ nhiệt từ môi trường của hỗn hợp nước và nước đá bằng: 91 W.","difficultySource":"ai"}}]},{"id":1478600,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["bằng áp suất khí quyển bên ngoài.","nhỏ hơn áp suất khí quyển bên ngoài.","lớn hơn áp suất khí quyển bên ngoài.","tỉ lệ thuận với nhiệt độ bên trong khí cầu."],"question":"Một chiếc khinh khí cầu có thể tích là 2,00.10<sup>3</sup> m3, không khí ở trong khí cầu được làm nóng bằng một ngọn lửa (hình vẽ). Ở mặt đất, áp suất khí quyển là 1,010.10<sup>5</sup> Pa, không khí trong khinh khí cầu được làm nóng đến nhiệt độ 102°C. Khinh khí cầu bay lên đến độ cao mà áp suất khí quyển giảm xuống còn 0,912.105 Pa. Để duy trì độ cao ổn định, nhiệt độ không khí bên trong khinh khí cầu phải được điều chỉnh lên đến 119°C và một lượng khí trong khinh khí cầu bị thoát ra ngoài trong quá trình di chuyển. Biết khối lượng mol của không khí là 29,0 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259819128-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất không khí bên trong khoang chứa khí của khinh khí cầu","difficulty":"de","explanation":"Chọn đáp án A<br>Đối với các khinh khí cầu hở phía dưới, áp suất khí bên trong luôn tự điều chỉnh để bằng với áp suất khí quyển bên ngoài tại cùng một độ cao nhằm duy trì trạng thái cân bằng.","difficultySource":"ai"},"ex":[{"exam":148,"idx":8,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["bằng áp suất khí quyển bên ngoài.","nhỏ hơn áp suất khí quyển bên ngoài.","lớn hơn áp suất khí quyển bên ngoài.","tỉ lệ thuận với nhiệt độ bên trong khí cầu."],"question":"Một chiếc khinh khí cầu có thể tích là 2,00.10<sup>3</sup> m3, không khí ở trong khí cầu được làm nóng bằng một ngọn lửa (hình vẽ). Ở mặt đất, áp suất khí quyển là 1,010.10<sup>5</sup> Pa, không khí trong khinh khí cầu được làm nóng đến nhiệt độ 102°C. Khinh khí cầu bay lên đến độ cao mà áp suất khí quyển giảm xuống còn 0,912.105 Pa. Để duy trì độ cao ổn định, nhiệt độ không khí bên trong khinh khí cầu phải được điều chỉnh lên đến 119°C và một lượng khí trong khinh khí cầu bị thoát ra ngoài trong quá trình di chuyển. Biết khối lượng mol của không khí là 29,0 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259819128-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Áp suất không khí bên trong khoang chứa khí của khinh khí cầu","difficulty":"de","explanation":"Chọn đáp án A<br>Đối với các khinh khí cầu hở phía dưới, áp suất khí bên trong luôn tự điều chỉnh để bằng với áp suất khí quyển bên ngoài tại cùng một độ cao nhằm duy trì trạng thái cân bằng.","difficultySource":"ai"}}]},{"id":1478601,"nq":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["256 kg.","156 kg.","156.103 kg.","256.103 kg."],"question":"Một chiếc khinh khí cầu có thể tích là 2,00.10<sup>3</sup> m3, không khí ở trong khí cầu được làm nóng bằng một ngọn lửa (hình vẽ). Ở mặt đất, áp suất khí quyển là 1,010.10<sup>5</sup> Pa, không khí trong khinh khí cầu được làm nóng đến nhiệt độ 102°C. Khinh khí cầu bay lên đến độ cao mà áp suất khí quyển giảm xuống còn 0,912.105 Pa. Để duy trì độ cao ổn định, nhiệt độ không khí bên trong khinh khí cầu phải được điều chỉnh lên đến 119°C và một lượng khí trong khinh khí cầu bị thoát ra ngoài trong quá trình di chuyển. Biết khối lượng mol của không khí là 29,0 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259819128-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Lượng không khí thoát ra ngoài trong quá trình di chuyển của khinh khí cầu như trên có khối lượng bằng","difficulty":"kho","explanation":"Chọn đáp án A<br>Trạng thái 1 (mặt đất):  $p_1=1,010.10^5Pa;T_1=102+273=375K$<br>$m_1=\\frac{p_1VM}{RT_1}=\\frac{1,010.10^5.2.10^3.29.10^{−3}}{8,31.375}\\approx 1880,4kg$<br>Trạng thái 2 (trên cao):  $p_2=0,912.10^5Pa;T_2=119+273=329K$<br>$m_2=\\frac{p_2VM}{RT_2}=\\frac{0,912.10^5.2.10^3.29.10^{−3}}{8,31.392}\\approx 1624,3kg$<br>Khối lượng khí thoát ra:  $\\Delta m=m_1−m_2\\approx 256kg$","difficultySource":"ai"},"ex":[{"exam":148,"idx":9,"el":{"form":"bai_tap","type":"multiple_choice","topic":"Vận dụng phương trình trạng thái","answer":0,"options":["256 kg.","156 kg.","156.103 kg.","256.103 kg."],"question":"Một chiếc khinh khí cầu có thể tích là 2,00.10<sup>3</sup> m3, không khí ở trong khí cầu được làm nóng bằng một ngọn lửa (hình vẽ). Ở mặt đất, áp suất khí quyển là 1,010.10<sup>5</sup> Pa, không khí trong khinh khí cầu được làm nóng đến nhiệt độ 102°C. Khinh khí cầu bay lên đến độ cao mà áp suất khí quyển giảm xuống còn 0,912.105 Pa. Để duy trì độ cao ổn định, nhiệt độ không khí bên trong khinh khí cầu phải được điều chỉnh lên đến 119°C và một lượng khí trong khinh khí cầu bị thoát ra ngoài trong quá trình di chuyển. Biết khối lượng mol của không khí là 29,0 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259819128-hinh-3.jpg\" alt=\"Hình 3\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Lượng không khí thoát ra ngoài trong quá trình di chuyển của khinh khí cầu như trên có khối lượng bằng","difficulty":"kho","explanation":"Chọn đáp án A<br>Trạng thái 1 (mặt đất):  $p_1=1,010.10^5Pa;T_1=102+273=375K$<br>$m_1=\\frac{p_1VM}{RT_1}=\\frac{1,010.10^5.2.10^3.29.10^{−3}}{8,31.375}\\approx 1880,4kg$<br>Trạng thái 2 (trên cao):  $p_2=0,912.10^5Pa;T_2=119+273=329K$<br>$m_2=\\frac{p_2VM}{RT_2}=\\frac{0,912.10^5.2.10^3.29.10^{−3}}{8,31.392}\\approx 1624,3kg$<br>Khối lượng khí thoát ra:  $\\Delta m=m_1−m_2\\approx 256kg$","difficultySource":"ai"}}]},{"id":1478617,"nq":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"5,1","question":"Một dây dẫn có tiết diện ngang 1,2 mm2, điện trở suất 1,7.10<sup>−8</sup>Ωm được uốn thành nửa vòng tròn tâm O có bán kính 24 cm như hình vẽ. Hai đoạn dây dẫn OM và OP cùng loại với dây trên. Dây OM cố định, dây OP quay quanh O sao cho P luôn tiếp xúc với cung tròn. Hệ thống đặt trong từ trường đều có độ lớn cảm ứng N từ 0,15 T có hướng vuông góc với mặt phẳng chứa nửa vòng tròn. Tại thời điểm ban đầu OP trùng với OM và tốc độ góc tăng đều theo thời gian. Góc α = POM mà bán kính OP quét được trong khoảng thời gian t được tính theo biểu thức α = σ.t2 với σ là hằng số α =  $\\frac{1}{2}$ γt2 Biết rằng sau 0,25 giây thì dòng điện cảm ứng trong mạch có giá trị cực đại. Giá trị cực đại của dòng điện là bao nhiêu ampe? (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"kho","explanation":"Đáp số 5,1<br>$S\\left(t\\right)=\\frac{1}{2}R^2\\alpha^2=\\frac{1}{2}R^2\\sigma t^2$<br>$\\Phi (t)=B.S\\left(t\\right)=\\frac{1}{2}BR^2\\sigma t^2$ ; suy ra suất điện động cảm ứng:  $e=\\frac{d\\Phi }{dt}=BR^2\\sigma t$<br>Chiều dài toàn bộ mạch điện kín là $L(t)=2R+R\\alpha =R\\left(2+\\sigma t^2\\right)$ , do đó điện trở của mạch là:<br>$R_m=\\rho \\frac{L\\left(t\\right)}{S_0}=\\rho \\frac{R\\left(2+\\sigma t^2\\right)}{S_0}$<br>$I(t)=\\frac{e}{R_m}=\\frac{BRS_0\\sigma t}{\\rho \\left(2+\\rho t^2\\right)}=\\frac{BRS_0\\sigma }{\\rho }.\\frac{1}{\\frac{2}{t}+\\sigma t}$<br>Áp dụng bất đẳng thức Cauchy:  $\\frac{2}{t}+\\sigma t\\ge 2\\sqrt{2\\sigma}$<br>Dấu bằng xảy ra khi  $t=\\sqrt{\\frac{2}{\\sigma }}$<br>Theo đề bài, dòng điện cực đại lúc t  = 0,25 s nên ta có:  $0,25=\\sqrt{\\frac{2}{\\sigma }}\\Rightarrow \\sigma =32\\left(rad/s^2\\right)$<br>Khi đó cụm mẫu số  $\\frac{2}{t}+\\sigma t$  có giá trị bằng 4<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259825546-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":148,"idx":25,"el":{"form":"bai_tap","type":"short_answer","topic":"Định luật Faraday và định luật Lenz","answer":"5,1","question":"Một dây dẫn có tiết diện ngang 1,2 mm2, điện trở suất 1,7.10<sup>−8</sup>Ωm được uốn thành nửa vòng tròn tâm O có bán kính 24 cm như hình vẽ. Hai đoạn dây dẫn OM và OP cùng loại với dây trên. Dây OM cố định, dây OP quay quanh O sao cho P luôn tiếp xúc với cung tròn. Hệ thống đặt trong từ trường đều có độ lớn cảm ứng N từ 0,15 T có hướng vuông góc với mặt phẳng chứa nửa vòng tròn. Tại thời điểm ban đầu OP trùng với OM và tốc độ góc tăng đều theo thời gian. Góc α = POM mà bán kính OP quét được trong khoảng thời gian t được tính theo biểu thức α = σ.t2 với σ là hằng số α =  $\\frac{1}{2}$ γt2 Biết rằng sau 0,25 giây thì dòng điện cảm ứng trong mạch có giá trị cực đại. Giá trị cực đại của dòng điện là bao nhiêu ampe? (Kết quả làm tròn đến chữ số hàng phần mười).","difficulty":"kho","explanation":"Đáp số 5,1<br>$S\\left(t\\right)=\\frac{1}{2}R^2\\alpha^2=\\frac{1}{2}R^2\\sigma t^2$<br>$\\Phi (t)=B.S\\left(t\\right)=\\frac{1}{2}BR^2\\sigma t^2$ ; suy ra suất điện động cảm ứng:  $e=\\frac{d\\Phi }{dt}=BR^2\\sigma t$<br>Chiều dài toàn bộ mạch điện kín là $L(t)=2R+R\\alpha =R\\left(2+\\sigma t^2\\right)$ , do đó điện trở của mạch là:<br>$R_m=\\rho \\frac{L\\left(t\\right)}{S_0}=\\rho \\frac{R\\left(2+\\sigma t^2\\right)}{S_0}$<br>$I(t)=\\frac{e}{R_m}=\\frac{BRS_0\\sigma t}{\\rho \\left(2+\\rho t^2\\right)}=\\frac{BRS_0\\sigma }{\\rho }.\\frac{1}{\\frac{2}{t}+\\sigma t}$<br>Áp dụng bất đẳng thức Cauchy:  $\\frac{2}{t}+\\sigma t\\ge 2\\sqrt{2\\sigma}$<br>Dấu bằng xảy ra khi  $t=\\sqrt{\\frac{2}{\\sigma }}$<br>Theo đề bài, dòng điện cực đại lúc t  = 0,25 s nên ta có:  $0,25=\\sqrt{\\frac{2}{\\sigma }}\\Rightarrow \\sigma =32\\left(rad/s^2\\right)$<br>Khi đó cụm mẫu số  $\\frac{2}{t}+\\sigma t$  có giá trị bằng 4<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259825546-hinh-15.png\" alt=\"Hình 15\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1478618,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"7,88","question":"Trong phản ứng phân hạch hạt nhân urani năng lượng trung bình tỏa ra khi phân hạch một hạt nhân  ${}_{92}^{235}U$ là 200 MeV. Một nhà máy điện nguyên tử dùng nguyên liệu urani, có công suất 500 MW, hiệu suất là 20%. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259824913-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Năng lượng phản ứng hạt nhân trong lò phản ứng hạt nhân của nhà máy tạo ra trong 1 năm (365 ngày) là x.10<sup>16</sup>J. Tính giá trị x (kết quả làm tròn đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"Đáp số 7,88<br>Thời gian một năm hoạt động của nhà máy là t = 365.24.3600 = 31536000 s .<br>Tổng năng lượng điện có ích nhà máy sinh ra trong một năm là<br>A = P.t = 500.106.31536000 = 1,5768.10<sup>16</sup> J .<br>Để tạo ra lượng điện năng này với mức hiệu suất chuyển đổi là 20% , tổng năng lượng phân hạch thực tế phải sinh ra trong lò là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259826103-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"},"ex":[{"exam":148,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"7,88","question":"Trong phản ứng phân hạch hạt nhân urani năng lượng trung bình tỏa ra khi phân hạch một hạt nhân  ${}_{92}^{235}U$ là 200 MeV. Một nhà máy điện nguyên tử dùng nguyên liệu urani, có công suất 500 MW, hiệu suất là 20%. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259824913-hinh-14.png\" alt=\"Hình 14\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Năng lượng phản ứng hạt nhân trong lò phản ứng hạt nhân của nhà máy tạo ra trong 1 năm (365 ngày) là x.10<sup>16</sup>J. Tính giá trị x (kết quả làm tròn đến chữ số hàng phần trăm).","difficulty":"trung-binh","explanation":"Đáp số 7,88<br>Thời gian một năm hoạt động của nhà máy là t = 365.24.3600 = 31536000 s .<br>Tổng năng lượng điện có ích nhà máy sinh ra trong một năm là<br>A = P.t = 500.106.31536000 = 1,5768.10<sup>16</sup> J .<br>Để tạo ra lượng điện năng này với mức hiệu suất chuyển đổi là 20% , tổng năng lượng phân hạch thực tế phải sinh ra trong lò là:<br><img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259826103-hinh-16.png\" alt=\"Hình 16\" class=\"mx-auto my-2 max-w-full rounded-lg\" />","difficultySource":"ai"}}]},{"id":1478674,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"701","question":"Tàu sân bay thế hệ mới sử dụng động cơ đẩy bằng năng lượng hạt nhân. Con tàu được trang bị hai lò phản ứng hạt nhân với tổng công suất hữu ích đầu ra là P = 280 MW. Tàu hoạt động liên tục trong một chiến dịch kéo dài 4 tháng (mỗi tháng 30 ngày). Lò phản ứng sử dụng sự phân hạch của hạt nhân  ${}_{92}^{235}U$ , mỗi phân hạch tỏa ra năng lượng trung bình 202 MeV. Hiệu suất của hệ thống lò phản ứng là 25%. Nhiên liệu Uranium được làm giàu chứa 20% khối lượng là  ${}_{92}^{235}U$ . Cho biết: 1 MeV = 1,6.10<sup>−13</sup>J; khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259850836-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Để tàu hoạt động liên tục đúng công suất trong thời gian trên, khối lượng nhiên liệu Uranium làm giàu tối thiểu cần dùng là bao nhiêu kg? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"kho","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259851488-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Cường độ dòng điện tối thiểu để đoạn dây bắt đầu trượt lên trên mặt phẳng:<br>$F_{t_{min}}=P.\\sin\\left(\\beta \\right)+F_{ms}$<br>$⟺B.I_{min}.L.\\sin\\left(\\alpha \\right)=m.g.\\sin\\left(\\beta \\right)+\\mu .m.g.\\cos\\left(\\beta \\right)$<br>$⟹I_{min}=\\frac{m.g.\\sin\\left(\\beta \\right)+\\mu .m.g}{B.L.\\sin\\left(\\alpha \\right)}=\\frac{0,01∙10∙\\sin\\left(30^{\\circ}\\right)+0,1∙0,01∙10∙\\cos\\left(30^{\\circ}\\right)}{0,23∙0,1∙\\sin\\left(90^{\\circ}\\right)}\\approx 2,55 A.$<br>Sử dụng các thông tin sau cho câu 5 và câu 6: Tàu sân bay thế hệ mới sử dụng động cơ đẩy bằng năng lượng hạt nhân. Con tàu được trang bị hai lò phản ứng hạt nhân với tổng công suất hữu ích đầu ra là P = 280 MW. Tàu hoạt động liên tục trong một chiến dịch kéo dài 4 tháng (mỗi tháng 30 ngày). Lò phản ứng sử dụng sự phân hạch của hạt nhân  ${}_{92}^{235}U$ , mỗi phân hạch tỏa ra năng lượng trung bình 202 MeV. Hiệu suất của hệ thống lò phản ứng là 25%. Nhiên liệu Uranium được làm giàu chứa 20% khối lượng là  ${}_{92}^{235}U$ . Cho biết: 1 MeV = 1,6.10<sup>−13</sup>J; khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol.","difficultySource":"ai"},"ex":[{"exam":151,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"701","question":"Tàu sân bay thế hệ mới sử dụng động cơ đẩy bằng năng lượng hạt nhân. Con tàu được trang bị hai lò phản ứng hạt nhân với tổng công suất hữu ích đầu ra là P = 280 MW. Tàu hoạt động liên tục trong một chiến dịch kéo dài 4 tháng (mỗi tháng 30 ngày). Lò phản ứng sử dụng sự phân hạch của hạt nhân  ${}_{92}^{235}U$ , mỗi phân hạch tỏa ra năng lượng trung bình 202 MeV. Hiệu suất của hệ thống lò phản ứng là 25%. Nhiên liệu Uranium được làm giàu chứa 20% khối lượng là  ${}_{92}^{235}U$ . Cho biết: 1 MeV = 1,6.10<sup>−13</sup>J; khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259850836-hinh-6.png\" alt=\"Hình 6\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Để tàu hoạt động liên tục đúng công suất trong thời gian trên, khối lượng nhiên liệu Uranium làm giàu tối thiểu cần dùng là bao nhiêu kg? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"kho","explanation":"<img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259851488-hinh-7.png\" alt=\"Hình 7\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Cường độ dòng điện tối thiểu để đoạn dây bắt đầu trượt lên trên mặt phẳng:<br>$F_{t_{min}}=P.\\sin\\left(\\beta \\right)+F_{ms}$<br>$⟺B.I_{min}.L.\\sin\\left(\\alpha \\right)=m.g.\\sin\\left(\\beta \\right)+\\mu .m.g.\\cos\\left(\\beta \\right)$<br>$⟹I_{min}=\\frac{m.g.\\sin\\left(\\beta \\right)+\\mu .m.g}{B.L.\\sin\\left(\\alpha \\right)}=\\frac{0,01∙10∙\\sin\\left(30^{\\circ}\\right)+0,1∙0,01∙10∙\\cos\\left(30^{\\circ}\\right)}{0,23∙0,1∙\\sin\\left(90^{\\circ}\\right)}\\approx 2,55 A.$<br>Sử dụng các thông tin sau cho câu 5 và câu 6: Tàu sân bay thế hệ mới sử dụng động cơ đẩy bằng năng lượng hạt nhân. Con tàu được trang bị hai lò phản ứng hạt nhân với tổng công suất hữu ích đầu ra là P = 280 MW. Tàu hoạt động liên tục trong một chiến dịch kéo dài 4 tháng (mỗi tháng 30 ngày). Lò phản ứng sử dụng sự phân hạch của hạt nhân  ${}_{92}^{235}U$ , mỗi phân hạch tỏa ra năng lượng trung bình 202 MeV. Hiệu suất của hệ thống lò phản ứng là 25%. Nhiên liệu Uranium được làm giàu chứa 20% khối lượng là  ${}_{92}^{235}U$ . Cho biết: 1 MeV = 1,6.10<sup>−13</sup>J; khối lượng mol của  ${}_{92}^{235}U$  là 235 g/mol.","difficultySource":"ai"}}]},{"id":1478699,"nq":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"0,12","question":"Giả sử khối kim loại ngập hoàn toàn trong nước. Khối lượng riêng của khối kim loại ở 0oC là D = 8000 kg/m3. Cho biết thể tích V(t) của khối kim loại ở nhiệt độ toC là V(t) = V0(1 + 3t), trong đó V0 là thể tích của khối kim loại ở 0oC và  = 1,2.10<sup>−5</sup> K–1 là hệ số nở dài của kim loại. Từ khi đưa khối kim loại vào nước cho đến khi đạt cân bằng nhiệt, thể tích của khối kim loại giảm đi một lượng bao nhiêu cm3? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Thể tích của kim loại tại 0oC:<br>$V_0=\\frac{m}{D}=\\frac{0,648}{8000}={8,1.10}^{-5} m^3=81 cm^3;$<br>Độ biến thiên thể tích của khối kim loại:<br>$\\Delta V=V_1-V_2=V_0\\left[1 + 3\\left(t_1\\right)\\right]-V_0\\left[1 + 3\\left(t_2\\right)\\right]=V_0\\left[3\\left(t_1-t_2\\right)\\right]$<br>$⟹\\Delta V=81∙\\left[3∙{1,2.10}^{-5}∙\\left(68-28\\right)\\right]\\approx 0,12 cm^3.$","difficultySource":"ai"},"ex":[{"exam":155,"idx":23,"el":{"form":"bai_tap","type":"short_answer","topic":"Nhiệt độ và cân bằng nhiệt","answer":"0,12","question":"Giả sử khối kim loại ngập hoàn toàn trong nước. Khối lượng riêng của khối kim loại ở 0oC là D = 8000 kg/m3. Cho biết thể tích V(t) của khối kim loại ở nhiệt độ toC là V(t) = V0(1 + 3t), trong đó V0 là thể tích của khối kim loại ở 0oC và  = 1,2.10<sup>−5</sup> K–1 là hệ số nở dài của kim loại. Từ khi đưa khối kim loại vào nước cho đến khi đạt cân bằng nhiệt, thể tích của khối kim loại giảm đi một lượng bao nhiêu cm3? (Làm tròn kết quả đến chữ số hàng phần trăm)","difficulty":"trung-binh","explanation":"Thể tích của kim loại tại 0oC:<br>$V_0=\\frac{m}{D}=\\frac{0,648}{8000}={8,1.10}^{-5} m^3=81 cm^3;$<br>Độ biến thiên thể tích của khối kim loại:<br>$\\Delta V=V_1-V_2=V_0\\left[1 + 3\\left(t_1\\right)\\right]-V_0\\left[1 + 3\\left(t_2\\right)\\right]=V_0\\left[3\\left(t_1-t_2\\right)\\right]$<br>$⟹\\Delta V=81∙\\left[3∙{1,2.10}^{-5}∙\\left(68-28\\right)\\right]\\approx 0,12 cm^3.$","difficultySource":"ai"}}]},{"id":1478700,"nq":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"361","question":"Một mol khí Helium chứa trong cylinder đậy kín bởi piston nhẹ, khí biến đổi từ trạng thái (1) sang trạng thái (2) như đồ thị bên dưới. Biết V1 = 2V2 = 20 dm3, p1 = 1,5.10<sup>5</sup> Pa, p2 = 3,0.10<sup>5</sup> Pa. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259883722-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nhiệt độ tại trạng thái (1) bằng bao nhiêu Kelvin? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"de","explanation":"Phương trình Clapeyron cho khí lí tưởng tại trạng thái (1):<br>$p_1.V_1=n.R.T_1$<br>$⟹T_1=\\frac{p_1.V_1}{n.R}=\\frac{{1,5.10}^5∙{20.10}^{-3}}{1∙8,31}\\approx 361 K.$","difficultySource":"ai"},"ex":[{"exam":155,"idx":24,"el":{"form":"bai_tap","type":"short_answer","topic":"Phương trình Clapeyron – Mendeleev","answer":"361","question":"Một mol khí Helium chứa trong cylinder đậy kín bởi piston nhẹ, khí biến đổi từ trạng thái (1) sang trạng thái (2) như đồ thị bên dưới. Biết V1 = 2V2 = 20 dm3, p1 = 1,5.10<sup>5</sup> Pa, p2 = 3,0.10<sup>5</sup> Pa. <img src=\"https://jgvbdbpvjdntdgzthumv.supabase.co/storage/v1/object/public/lesson-media/132/1790259883722-hinh-9.png\" alt=\"Hình 9\" class=\"mx-auto my-2 max-w-full rounded-lg\" /><br>Nhiệt độ tại trạng thái (1) bằng bao nhiêu Kelvin? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"de","explanation":"Phương trình Clapeyron cho khí lí tưởng tại trạng thái (1):<br>$p_1.V_1=n.R.T_1$<br>$⟹T_1=\\frac{p_1.V_1}{n.R}=\\frac{{1,5.10}^5∙{20.10}^{-3}}{1∙8,31}\\approx 361 K.$","difficultySource":"ai"}}]},{"id":1478702,"nq":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5","question":"Một nhà máy điện hạt nhân sử dụng nguyên liệu là  ${}_{92}^{235}U$ . Biết rằng mỗi phân hạch sẽ tỏa ra năng lượng trung bình là 200 MeV, biết 1 MeV = 1,6.10<sup>−13</sup> J. Hiệu suất và công suất phát diện của nhà máy lần lượt là 40% và 640 MW.<br>Trong lò phản ứng, mỗi giây có x.10<sup>19</sup> hạt  ${}_{92}^{235}U$  bị phân hạch. Giá trị của x bằng bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Số phản ứng phân hạch trong mỗi giây:<br>$N.E_0=E=\\frac{A}{H}=\\frac{P.t}{H}$<br>$⟺N∙\\left(200∙{1,6.10}^{-13}\\right)=\\frac{640.{10}^6∙1}{0,4}$<br>$⟹N={5.10}^{19} hạt$<br>$⟹x=5.$","difficultySource":"ai"},"ex":[{"exam":155,"idx":26,"el":{"form":"bai_tap","type":"short_answer","topic":"Năng lượng toả ra của phản ứng hạt nhân","answer":"5","question":"Một nhà máy điện hạt nhân sử dụng nguyên liệu là  ${}_{92}^{235}U$ . Biết rằng mỗi phân hạch sẽ tỏa ra năng lượng trung bình là 200 MeV, biết 1 MeV = 1,6.10<sup>−13</sup> J. Hiệu suất và công suất phát diện của nhà máy lần lượt là 40% và 640 MW.<br>Trong lò phản ứng, mỗi giây có x.10<sup>19</sup> hạt  ${}_{92}^{235}U$  bị phân hạch. Giá trị của x bằng bao nhiêu? (Làm tròn kết quả đến chữ số hàng đơn vị)","difficulty":"trung-binh","explanation":"Số phản ứng phân hạch trong mỗi giây:<br>$N.E_0=E=\\frac{A}{H}=\\frac{P.t}{H}$<br>$⟺N∙\\left(200∙{1,6.10}^{-13}\\right)=\\frac{640.{10}^6∙1}{0,4}$<br>$⟹N={5.10}^{19} hạt$<br>$⟹x=5.$","difficultySource":"ai"}}]},{"id":1478724,"nq":{"form":"bai_tap","type":"true_false","topic":"Điện từ trường và sóng điện từ","question":"Một sóng điện từ lan truyền trong không khí theo phương ngang, có chiều truyền từ Nam đến Bắc. Tần số của sóng là 95,6 MHz. Biết tốc độ lan truyền của sóng điện từ trong không khí xấp xỉ bằng 3.10<sup>8</sup> m/s.","difficulty":"trung-binh","statements":[{"text":"Sóng điện từ là sự lan truyền của điện từ trường trong không gian.","answer":true},{"text":"Bước sóng của sóng điện từ này xấp xỉ bằng 3 m.","answer":true},{"text":"Tại một điểm trên phương truyền sóng, nếu tại một thời điểm vector cảm ứng từ  $\\vec{B}$  có phương thẳng đứng và chiều từ dưới lên trên thì vector cường độ điện trường  $\\vec{E}$  có phương ngang và chiều từ Đông sang Tây.","answer":true},{"text":"Sóng điện từ không có hiện tượng giao thoa như sóng cơ.","answer":false}],"explanation":"a) đúng<br>Sóng điện từ là sự lan truyền của điện từ trường trong không gian, không cần môi trường vật chất.<br>b) đúng<br>Bước sóng của sóng điện từ này là:  $=\\frac{c}{f}=\\frac{3.{10}^8}{95,6.{10}^6}\\approx 3$  m.<br>c) đúng<br>Tại một điểm trên phương truyền của sóng điện từ, ba vector  $\\vec{B}$ ,  $\\vec{E}$  và  $\\vec{v}$  tạo thành tam diện thuận.<br>Sử dụng quy tắc vặn định ốc hoặc một quy tắc tương đương, ta xác định được vector cường độ điện trường  $\\vec{E}$  có phương ngang và chiều từ Đông sang Tây.<br>d) sai<br>Sóng điện từ có đầy đủ các hiện tượng đặc trưng của sóng như giao thoa sóng (ví dụ: giao thoa ánh sáng), phản xạ, khúc xạ, nhiễu xạ,…","difficultySource":"ai"},"ex":[{"exam":156,"idx":20,"el":{"form":"bai_tap","type":"true_false","topic":"Điện từ trường và sóng điện từ","question":"Một sóng điện từ lan truyền trong không khí theo phương ngang, có chiều truyền từ Nam đến Bắc. Tần số của sóng là 95,6 MHz. Biết tốc độ lan truyền của sóng điện từ trong không khí xấp xỉ bằng 3.10<sup>8</sup> m/s.","difficulty":"trung-binh","statements":[{"text":"Sóng điện từ là sự lan truyền của điện từ trường trong không gian.","answer":true},{"text":"Bước sóng của sóng điện từ này xấp xỉ bằng 3 m.","answer":true},{"text":"Tại một điểm trên phương truyền sóng, nếu tại một thời điểm vector cảm ứng từ  $\\vec{B}$  có phương thẳng đứng và chiều từ dưới lên trên thì vector cường độ điện trường  $\\vec{E}$  có phương ngang và chiều từ Đông sang Tây.","answer":true},{"text":"Sóng điện từ không có hiện tượng giao thoa như sóng cơ.","answer":false}],"explanation":"a) đúng<br>Sóng điện từ là sự lan truyền của điện từ trường trong không gian, không cần môi trường vật chất.<br>b) đúng<br>Bước sóng của sóng điện từ này là:  $=\\frac{c}{f}=\\frac{3.{10}^8}{95,6.{10}^6}\\approx 3$  m.<br>c) đúng<br>Tại một điểm trên phương truyền của sóng điện từ, ba vector  $\\vec{B}$ ,  $\\vec{E}$  và  $\\vec{v}$  tạo thành tam diện thuận.<br>Sử dụng quy tắc vặn định ốc hoặc một quy tắc tương đương, ta xác định được vector cường độ điện trường  $\\vec{E}$  có phương ngang và chiều từ Đông sang Tây.<br>d) sai<br>Sóng điện từ có đầy đủ các hiện tượng đặc trưng của sóng như giao thoa sóng (ví dụ: giao thoa ánh sáng), phản xạ, khúc xạ, nhiễu xạ,…","difficultySource":"ai"}}]},{"id":1478728,"nq":{"form":"bai_tap","type":"short_answer","topic":"Tính lực từ F = BIl·sinθ","answer":"2,56","question":"Một đoạn dây dẫn thẳng có chiều dài 30 cm được đặt trong từ trường đều và vuông góc với các 